INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('f815a2e9-b3d3-5ddd-b835-32bfe7bc2269','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-24-01','75ffa2900aa1343e00a3f8e41dd5c20141ee92b9a6bded03a000fc99cdaacd8e','00023-P1-24-01','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('53cd30fd-4c90-5cd9-966d-3d8bf6cc601a','1bc86e3e-2bed-580c-b005-ec4ef354da9b','f815a2e9-b3d3-5ddd-b835-32bfe7bc2269','设 $f(x)=2x^4-3x^2+5$，则 $f''(1)=$','["$2$","$7$","$8$","$-2$"]',1,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-24 导数的运算',0);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('53cd30fd-4c90-5cd9-966d-3d8bf6cc601a',0,'逐项求导：$f''(x)=8x^3-6x$，故 $f''(1)=8-6=2$。
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('c4a6b9c3-ccc0-51da-b081-bf55953ba945','1da6de03-1c89-524f-824a-35bc7bb191ca','P1-24 导数的运算','P1-24 导数的运算');
INSERT INTO release_point (release_id,chapter_id,point_id,title_snapshot) VALUES ('1bc86e3e-2bed-580c-b005-ec4ef354da9b','1da6de03-1c89-524f-824a-35bc7bb191ca','c4a6b9c3-ccc0-51da-b081-bf55953ba945','P1-24 导数的运算');
INSERT INTO question_point (revision_id,point_id) VALUES ('53cd30fd-4c90-5cd9-966d-3d8bf6cc601a','c4a6b9c3-ccc0-51da-b081-bf55953ba945');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('c5132de5-d2b0-5150-8cf6-652410df496b','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-24-02','9653ee6266d6e7cf5351b081c2b86267f6ac766333f3984d0d850018841d2475','00023-P1-24-02','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('a94edcbf-de86-5856-b56f-5ff3ce63db85','1bc86e3e-2bed-580c-b005-ec4ef354da9b','c5132de5-d2b0-5150-8cf6-652410df496b','设 $y=e^{2x}+\\ln x$，$x>0$，则 $y''=$','["$e^{2x}+\\\\frac1x$","$2e^{2x}+\\\\frac1x$","$2e^{2x}+x$","$2e^{2x}-\\\\frac1x$"]',1,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-24 导数的运算',1);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('a94edcbf-de86-5856-b56f-5ff3ce63db85',1,'指数项用链式法则，对数项用基本公式：$y''=e^{2x}\\cdot2+1/x$。
INSERT INTO question_point (revision_id,point_id) VALUES ('a94edcbf-de86-5856-b56f-5ff3ce63db85','c4a6b9c3-ccc0-51da-b081-bf55953ba945');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('8b310560-6e64-5e24-a5bd-753c3452fd2a','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-24-03','a180e8f19f766ebcdcffe14ef1076821103ce65f550f9fa00474b27a89035bf9','00023-P1-24-03','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('ec29460f-bb4b-54da-b8ef-f3ffd0d85e85','1bc86e3e-2bed-580c-b005-ec4ef354da9b','8b310560-6e64-5e24-a5bd-753c3452fd2a','设 $y=\\frac{x^2+1}{x+1}$，则 $y''(1)=$','["$1$","$\\\\frac32$","$\\\\frac12$","$-\\\\frac12$"]',2,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-24 导数的运算',2);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('ec29460f-bb4b-54da-b8ef-f3ffd0d85e85',2,'先用商法则：$y''=\\frac{2x(x+1)-(x^2+1)}{(x+1)^2}$。代入 $x=1$ 得 $(4-2)/4=1/2$。
INSERT INTO question_point (revision_id,point_id) VALUES ('ec29460f-bb4b-54da-b8ef-f3ffd0d85e85','c4a6b9c3-ccc0-51da-b081-bf55953ba945');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('67df8f73-30cd-576f-97bd-fc48620d87d3','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-24-04','943d0ab086b6510a2aae5d797932b5dfd94c59b39f897b330376f0b196edf38e','00023-P1-24-04','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('0f916152-0e41-5af9-b2f5-5465d58e57d1','1bc86e3e-2bed-580c-b005-ec4ef354da9b','67df8f73-30cd-576f-97bd-fc48620d87d3','设 $y=\\ln(1+\\sin^2x)$，则 $y''(\\pi/4)=$','["$\\\\frac13$","$\\\\frac12$","$1$","$\\\\frac23$"]',2,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-24 导数的运算',3);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('0f916152-0e41-5af9-b2f5-5465d58e57d1',3,'逐层求导：$y''=\\frac{2\\sin x\\cos x}{1+\\sin^2x}$。在 $x=\\pi/4$ 处分子为 $1$、分母为 $3/2$，故结果为 $2/3$。
INSERT INTO question_point (revision_id,point_id) VALUES ('0f916152-0e41-5af9-b2f5-5465d58e57d1','c4a6b9c3-ccc0-51da-b081-bf55953ba945');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('da357043-b861-5e88-8409-6f8d526fdaca','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-24-05','6b6d01cf99f2bb0fc2861634077f5ca0651499a963d29c44bd0f8c1fed1b8f25','00023-P1-24-05','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('a9ce9bb3-0e76-58db-960b-185b8988fc07','1bc86e3e-2bed-580c-b005-ec4ef354da9b','da357043-b861-5e88-8409-6f8d526fdaca','设 $f,g$ 在 $x=1$ 的邻域内可导，且 $f(1)=2$、$f''(1)=3$、$g(1)=1$、$g''(1)=-2$。令 $h(x)=\\ln\\frac{f^2(x)+g^2(x)}{f(x)g(x)}$，则 $h''(1)=$','["$\\\\frac{21}{10}$","$\\\\frac85$","$\\\\frac{11}{10}$","$\\\\frac{13}{10}$"]',3,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-24 导数的运算',4);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('a9ce9bb3-0e76-58db-960b-185b8988fc07',0,'在足够小的邻域内 $f,g>0$，拆对数得 $h''=\\frac{2ff''+2gg''}{f^2+g^2}-\\frac{f''}f-\\frac{g''}g$。代入得 $8/5-3/2+2=21/10$。
INSERT INTO question_point (revision_id,point_id) VALUES ('a9ce9bb3-0e76-58db-960b-185b8988fc07','c4a6b9c3-ccc0-51da-b081-bf55953ba945');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('4d994517-e3d7-54cb-9636-90502570d1d0','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-24-06','4c04e065721149495ad601f26006289a232017163736ed2e2319cdb1ca1169b0','00023-P1-24-06','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('17c12c63-a9bb-5a96-b417-d14d53b713da','1bc86e3e-2bed-580c-b005-ec4ef354da9b','4d994517-e3d7-54cb-9636-90502570d1d0','设 $a$ 为实数，$f(x)=\\begin{cases}\\frac{e^{ax}-1}{x},&x\\ne0,\\\\2,&x=0.\\end{cases}$。若 $f$ 在 $x=0$ 处可导，则 $a+f''(0)=$','["$2$","$4$","$6$","$3$"]',3,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-24 导数的运算',5);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('17c12c63-a9bb-5a96-b417-d14d53b713da',1,'可导先要求连续，$\\lim_{x\\to0}(e^{ax}-1)/x=a=2$。再用导数定义，$f''(0)=\\lim_{x\\to0}\\frac{e^{2x}-1-2x}{x^2}=2$，故和为 $4$。
INSERT INTO question_point (revision_id,point_id) VALUES ('17c12c63-a9bb-5a96-b417-d14d53b713da','c4a6b9c3-ccc0-51da-b081-bf55953ba945');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('0d554f36-1e62-5664-8ce6-4494f61cbcc8','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-25-01','5804788c50b672f8db0b996a3877d803318ee9e659c2a4732d847bf8343dbab6','00023-P1-25-01','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('57c0ad48-2ab3-50a3-aec2-dc2ef18dba76','1bc86e3e-2bed-580c-b005-ec4ef354da9b','0d554f36-1e62-5664-8ce6-4494f61cbcc8','由 $x^2+xy+y^2=7$ 确定的可导函数 $y=y(x)$ 在点 $(1,2)$ 处的导数为','["$\\\\frac45$","$-\\\\frac54$","$-\\\\frac45$","$-1$"]',1,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-25 三类特殊函授求导',6);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('57c0ad48-2ab3-50a3-aec2-dc2ef18dba76',2,'对 $x$ 求导：$2x+y+(x+2y)y''=0$，所以 $y''=-(2x+y)/(x+2y)$。代入 $(1,2)$ 得 $-4/5$。
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('9676988c-e477-56d5-b007-e9fdd5838e3f','1da6de03-1c89-524f-824a-35bc7bb191ca','P1-25 三类特殊函授求导','P1-25 三类特殊函授求导');
INSERT INTO release_point (release_id,chapter_id,point_id,title_snapshot) VALUES ('1bc86e3e-2bed-580c-b005-ec4ef354da9b','1da6de03-1c89-524f-824a-35bc7bb191ca','9676988c-e477-56d5-b007-e9fdd5838e3f','P1-25 三类特殊函授求导');
INSERT INTO question_point (revision_id,point_id) VALUES ('57c0ad48-2ab3-50a3-aec2-dc2ef18dba76','9676988c-e477-56d5-b007-e9fdd5838e3f');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('54072db5-9b25-5579-ac27-52192d30d8f3','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-25-02','a9ee38f08957c9ff8efad145eed437eb42c164922d508cf439dcbfcbe18a4e3b','00023-P1-25-02','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('5847cb43-69ed-5fdf-b049-098f0f9b1ae7','1bc86e3e-2bed-580c-b005-ec4ef354da9b','54072db5-9b25-5579-ac27-52192d30d8f3','曲线由 $x=t^2+1$、$y=t^3-t$ 给出，则在 $t=1$ 处 $\\frac{dy}{dx}=$','["$2$","$\\\\frac12$","$-1$","$1$"]',1,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-25 三类特殊函授求导',7);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('5847cb43-69ed-5fdf-b049-098f0f9b1ae7',3,'参数方程求导：$dy/dx=(3t^2-1)/(2t)$。在 $t=1$ 处分子、分母均为 $2$，故结果为 $1$。
INSERT INTO question_point (revision_id,point_id) VALUES ('5847cb43-69ed-5fdf-b049-098f0f9b1ae7','9676988c-e477-56d5-b007-e9fdd5838e3f');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('c8be5862-0e79-586b-b256-a0ef980a240c','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-25-03','e0f0ab3c402f0c78374c0a75a34873cd1375bf68e93d9d7dee95e47f0894fde8','00023-P1-25-03','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('c4afa6e0-e517-55a9-b704-f7255387c3e6','1bc86e3e-2bed-580c-b005-ec4ef354da9b','c8be5862-0e79-586b-b256-a0ef980a240c','设 $y=(1+x)^{2x}$，$x>-1$，则 $y''(1)=$','["$8\\\\ln2+4$","$8\\\\ln2$","$4\\\\ln2+4$","$8\\\\ln2+8$"]',2,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-25 三类特殊函授求导',8);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('c4afa6e0-e517-55a9-b704-f7255387c3e6',0,'取对数：$\\ln y=2x\\ln(1+x)$，故 $y''=y[2\\ln(1+x)+2x/(1+x)]$。由于 $y(1)=4$，得 $y''(1)=8\\ln2+4$。
INSERT INTO question_point (revision_id,point_id) VALUES ('c4afa6e0-e517-55a9-b704-f7255387c3e6','9676988c-e477-56d5-b007-e9fdd5838e3f');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('3b6f77c0-2a48-56dd-b985-b124bfdb4dbc','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-25-04','381f16c21c61854cac5be371618678288bd12640f32b7ce253542f1782f26ace','00023-P1-25-04','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('6ba9804c-229f-5a73-806a-f25b37fa5ad1','1bc86e3e-2bed-580c-b005-ec4ef354da9b','3b6f77c0-2a48-56dd-b985-b124bfdb4dbc','由 $\\ln y+xy=1$ 确定的可导函数 $y=y(x)>0$，在点 $(1,1)$ 处的导数为','["$-1$","$-\\\\frac12$","$\\\\frac12$","$-2$"]',2,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-25 三类特殊函授求导',9);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('6ba9804c-229f-5a73-806a-f25b37fa5ad1',1,'隐式求导得 $y''/y+y+xy''=0$，整理为 $y''=-y/(x+1/y)$。在 $(1,1)$ 处得 $-1/2$。
INSERT INTO question_point (revision_id,point_id) VALUES ('6ba9804c-229f-5a73-806a-f25b37fa5ad1','9676988c-e477-56d5-b007-e9fdd5838e3f');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('2aa45a17-433f-5eb5-99ab-46efe0c885ad','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-25-05','f769a8af57fd89f6212cf16633c72d5ea9b52bf38e81b1343387bdea3045692d','00023-P1-25-05','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('ced24c05-59a5-590c-8d49-0c167fe3fb8e','1bc86e3e-2bed-580c-b005-ec4ef354da9b','2aa45a17-433f-5eb5-99ab-46efe0c885ad','曲线由 $x=t^2+t$、$y=t^3-2t$ 给出，则在 $t=1$ 处 $\\frac{d^2y}{dx^2}=$','["$\\\\frac{16}{9}$","$3$","$\\\\frac{16}{27}$","$\\\\frac{20}{27}$"]',3,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-25 三类特殊函授求导',10);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('ced24c05-59a5-590c-8d49-0c167fe3fb8e',2,'先得 $dy/dx=(3t^2-2)/(2t+1)$。再对 $t$ 求导并除以 $dx/dt$，得 $d^2y/dx^2=\\frac{6t(2t+1)-2(3t^2-2)}{(2t+1)^3}$。代入 $t=1$ 得 $16/27$。
INSERT INTO question_point (revision_id,point_id) VALUES ('ced24c05-59a5-590c-8d49-0c167fe3fb8e','9676988c-e477-56d5-b007-e9fdd5838e3f');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('ec6d27d7-df4d-588b-bd29-417e120f99a5','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-25-06','a7c722820eb7ec9c16468cf7b7eafdd6c5bcf129e5624a2d673fceaea302e0a2','00023-P1-25-06','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('259461a7-88eb-58ff-be28-b461b33749bd','1bc86e3e-2bed-580c-b005-ec4ef354da9b','ec6d27d7-df4d-588b-bd29-417e120f99a5','由 $x^y+y^x=3$ 确定的可导函数 $y=y(x)$，在 $x>0,y>0$ 的点 $(1,2)$ 处，其导数为','["$-2\\\\ln2$","$-2$","$-\\\\frac1{2+2\\\\ln2}$","$-2-2\\\\ln2$"]',3,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-25 三类特殊函授求导',11);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('259461a7-88eb-58ff-be28-b461b33749bd',3,'同时处理两项的底数与指数：$x^y(y''\\ln x+y/x)+y^x(\\ln y+xy''/y)=0$。在 $(1,2)$ 处化为 $2+2\\ln2+y''=0$，得 $y''=-2-2\\ln2$。
INSERT INTO question_point (revision_id,point_id) VALUES ('259461a7-88eb-58ff-be28-b461b33749bd','9676988c-e477-56d5-b007-e9fdd5838e3f');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('0b6b892f-d935-5286-87ab-386426b0cfce','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-26-01','443a0107eeee90fbfbc0235076d1b6ca2bfbb7ee0c91c17f201177908d3a819b','00023-P1-26-01','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('f868b315-c790-556b-9f62-1a07803b4fad','1bc86e3e-2bed-580c-b005-ec4ef354da9b','0b6b892f-d935-5286-87ab-386426b0cfce','设 $f(x)=3x^4-2x^3$，则 $f''''(1)=$','["$24$","$30$","$36$","$6$"]',1,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-26 高阶导数',12);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('f868b315-c790-556b-9f62-1a07803b4fad',0,'连续求导：$f''=12x^3-6x^2$，$f''''=36x^2-12x$。代入 $x=1$ 得 $24$。
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('c0acd71d-23da-5df2-bc92-4682eee88f48','1da6de03-1c89-524f-824a-35bc7bb191ca','P1-26 高阶导数','P1-26 高阶导数');
INSERT INTO release_point (release_id,chapter_id,point_id,title_snapshot) VALUES ('1bc86e3e-2bed-580c-b005-ec4ef354da9b','1da6de03-1c89-524f-824a-35bc7bb191ca','c0acd71d-23da-5df2-bc92-4682eee88f48','P1-26 高阶导数');
INSERT INTO question_point (revision_id,point_id) VALUES ('f868b315-c790-556b-9f62-1a07803b4fad','c0acd71d-23da-5df2-bc92-4682eee88f48');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('8978a3f6-ca3b-5b4f-9ffb-deefaad0d6de','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-26-02','896681235ddae98f3755a53086731b7d66f5ea0aa04029733a154a866e62036c','00023-P1-26-02','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('03d71ce7-5492-5775-bb4d-f6628393dbcd','1bc86e3e-2bed-580c-b005-ec4ef354da9b','8978a3f6-ca3b-5b4f-9ffb-deefaad0d6de','设 $y=e^{-2x}$，则 $y^{(3)}(0)=$','["$8$","$-8$","$-2$","$4$"]',1,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-26 高阶导数',13);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('03d71ce7-5492-5775-bb4d-f6628393dbcd',1,'每次求导都乘 $-2$，所以 $y^{(3)}=(-2)^3e^{-2x}$，代入 $x=0$ 得 $-8$。
INSERT INTO question_point (revision_id,point_id) VALUES ('03d71ce7-5492-5775-bb4d-f6628393dbcd','c0acd71d-23da-5df2-bc92-4682eee88f48');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('8209558a-47e0-590b-b9e3-fc762b7cf4cd','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-26-03','39ab70cc87d3fa02b8195405f06b65b04647c48b1efde9e535aed90422313186','00023-P1-26-03','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('38674c4b-d58d-5b6a-8b80-7b79b98476cc','1bc86e3e-2bed-580c-b005-ec4ef354da9b','8209558a-47e0-590b-b9e3-fc762b7cf4cd','设 $y=x^2\\ln x$，$x>0$，则 $y^{(3)}(1)=$','["$3$","$1$","$2$","$-2$"]',2,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-26 高阶导数',14);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('38674c4b-d58d-5b6a-8b80-7b79b98476cc',2,'用乘积法则连续求导：$y''=2x\\ln x+x$，$y''''=2\\ln x+3$，$y^{(3)}=2/x$，故在 $x=1$ 处为 $2$。
INSERT INTO question_point (revision_id,point_id) VALUES ('38674c4b-d58d-5b6a-8b80-7b79b98476cc','c0acd71d-23da-5df2-bc92-4682eee88f48');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('2ea12cac-57f9-50a3-86ca-2d8217982354','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-26-04','2e8c8434f4663199d6dbdfb27de74df96d7d8bad83dfb60fd98cb3789d1019b8','00023-P1-26-04','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('47de7eab-a760-52ba-9307-af77e535e917','1bc86e3e-2bed-580c-b005-ec4ef354da9b','2ea12cac-57f9-50a3-86ca-2d8217982354','设 $y=\\frac1{1+2x}$，则 $y^{(4)}(0)=$','["$16$","$24$","$-384$","$384$"]',2,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-26 高阶导数',15);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('47de7eab-a760-52ba-9307-af77e535e917',3,'由连续求导归纳：$y^{(n)}=(-1)^n n!2^n(1+2x)^{-n-1}$。令 $n=4,x=0$，得 $4!\\cdot2^4=384$。
INSERT INTO question_point (revision_id,point_id) VALUES ('47de7eab-a760-52ba-9307-af77e535e917','c0acd71d-23da-5df2-bc92-4682eee88f48');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('6dae7602-70d2-5767-af91-29746bfa2634','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-26-05','201d209197bf65d84a8fff5e1e24362963f9baf29a9746a2e43d07e7b6047dc8','00023-P1-26-05','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('cffd31c3-5ec8-5739-8c3d-57a8dd7b218c','1bc86e3e-2bed-580c-b005-ec4ef354da9b','6dae7602-70d2-5767-af91-29746bfa2634','设 $f(x)=x^2e^{2x}$，则 $f^{(5)}(0)=$','["$160$","$16$","$80$","$320$"]',3,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-26 高阶导数',16);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('cffd31c3-5ec8-5739-8c3d-57a8dd7b218c',0,'用莱布尼茨公式。在 $x=0$ 处，$x^2$ 和它的一阶导数均为零，只有二阶项保留：$f^{(5)}(0)=\\binom52\\cdot2\\cdot2^3=160$。
INSERT INTO question_point (revision_id,point_id) VALUES ('cffd31c3-5ec8-5739-8c3d-57a8dd7b218c','c0acd71d-23da-5df2-bc92-4682eee88f48');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('c8cc3054-9921-5808-97b7-cb4c10d1f005','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-26-06','7c91b658d6b24c24316c42190d4e3554c9f2c31f12225bc4c832c927a8301d33','00023-P1-26-06','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('685a20d7-a613-5bc8-b93a-3d4892114569','1bc86e3e-2bed-580c-b005-ec4ef354da9b','c8cc3054-9921-5808-97b7-cb4c10d1f005','由 $x^2+xy+y^2=3$ 确定的二阶可导函数 $y=y(x)$，在点 $(1,1)$ 处的二阶导数为','["$0$","$-\\\\frac23$","$-2$","$\\\\frac23$"]',3,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-26 高阶导数',17);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('685a20d7-a613-5bc8-b93a-3d4892114569',1,'第一次求导得 $2x+y+(x+2y)y''=0$，代入得 $y''=-1$。再求导得 $2+2y''+2(y'')^2+(x+2y)y''''=0$。代入得 $2+3y''''=0$，故 $y''''=-2/3$。
INSERT INTO question_point (revision_id,point_id) VALUES ('685a20d7-a613-5bc8-b93a-3d4892114569','c0acd71d-23da-5df2-bc92-4682eee88f48');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('bb0b083c-8564-59af-a739-25b8509f6fe1','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-27-01','c501d9dfa564928cdf0174557eea536feb3c2ddafbde3401d809f5999505e94d','00023-P1-27-01','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('f423bc11-d80d-56bc-8cfd-b77e2165f403','1bc86e3e-2bed-580c-b005-ec4ef354da9b','bb0b083c-8564-59af-a739-25b8509f6fe1','设 $y=3x^2-2x$，则在 $x=2$ 处的微分 $dy$ 为','["$10\\\\,dx$","$8\\\\,dx$","$12\\\\,dx$","$10$"]',1,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-27 微分及其运算',18);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('f423bc11-d80d-56bc-8cfd-b77e2165f403',0,'先求导数 $y''=6x-2$，再用 $dy=y''\\,dx$。代入 $x=2$，得 $dy=10\\,dx$。
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('f0906895-cb68-5047-aa48-8d61587457c0','1da6de03-1c89-524f-824a-35bc7bb191ca','P1-27 微分及其运算','P1-27 微分及其运算');
INSERT INTO release_point (release_id,chapter_id,point_id,title_snapshot) VALUES ('1bc86e3e-2bed-580c-b005-ec4ef354da9b','1da6de03-1c89-524f-824a-35bc7bb191ca','f0906895-cb68-5047-aa48-8d61587457c0','P1-27 微分及其运算');
INSERT INTO question_point (revision_id,point_id) VALUES ('f423bc11-d80d-56bc-8cfd-b77e2165f403','f0906895-cb68-5047-aa48-8d61587457c0');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('b38e06ea-ecfa-5e3c-bb84-d47a8fb3815e','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-27-02','af3cecbb25028d80a396f0a5545cd078529d927d24bbb90b6ffd32e53d0a0423','00023-P1-27-02','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('0ef89892-f648-5b01-a218-cd13f4e5c271','1bc86e3e-2bed-580c-b005-ec4ef354da9b','b38e06ea-ecfa-5e3c-bb84-d47a8fb3815e','设 $y=\\ln(1+3x)$，则在 $x=0$ 处的微分 $dy$ 为','["$dx$","$3\\\\,dx$","$0$","$-3\\\\,dx$"]',1,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-27 微分及其运算',19);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('0ef89892-f648-5b01-a218-cd13f4e5c271',1,'链式法则给出 $y''=3/(1+3x)$，所以 $dy=\\frac{3}{1+3x}\\,dx$。在 $x=0$ 处为 $3\\,dx$。
INSERT INTO question_point (revision_id,point_id) VALUES ('0ef89892-f648-5b01-a218-cd13f4e5c271','f0906895-cb68-5047-aa48-8d61587457c0');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('ef460a57-0945-53bd-8143-0fac303db672','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-27-03','b50277fdf12408918a266e372c93e3237cb49a599ccb3f7b8ce8c48c937c7b43','00023-P1-27-03','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('f87998cb-34d5-58f0-9c7e-a2ead114f882','1bc86e3e-2bed-580c-b005-ec4ef354da9b','ef460a57-0945-53bd-8143-0fac303db672','由 $xy+\\ln y=2$ 确定的可导函数 $y=y(x)>0$，在点 $(2,1)$ 处的微分 $dy$ 为','["$-\\\\frac12\\\\,dx$","$\\\\frac13\\\\,dx$","$-\\\\frac13\\\\,dx$","$-3\\\\,dx$"]',2,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-27 微分及其运算',20);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('f87998cb-34d5-58f0-9c7e-a2ead114f882',2,'两边微分：$y\\,dx+x\\,dy+\\frac1y\\,dy=0$。代入 $(2,1)$ 得 $dx+3\\,dy=0$，所以 $dy=-\\frac13\\,dx$。
INSERT INTO question_point (revision_id,point_id) VALUES ('f87998cb-34d5-58f0-9c7e-a2ead114f882','f0906895-cb68-5047-aa48-8d61587457c0');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('08c99b1c-1b0b-5959-ac98-8bc27b20f2d1','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-27-04','06f76a11825eb6fd14fad86e64ee46b991d5d1087ea09c4d3f302b02f370a621','00023-P1-27-04','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('beff4ccd-e6c4-5e3c-9cf5-6ebb02b799bd','1bc86e3e-2bed-580c-b005-ec4ef354da9b','08c99b1c-1b0b-5959-ac98-8bc27b20f2d1','用函数 $f(x)=x^{1/4}$ 在 $x=16$ 处的一阶微分近似，估算 $\\sqrt[4]{17}$，所得近似值为','["$\\\\frac{33}{16}$","$\\\\frac94$","$\\\\frac{63}{32}$","$\\\\frac{65}{32}$"]',2,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-27 微分及其运算',21);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('beff4ccd-e6c4-5e3c-9cf5-6ebb02b799bd',3,'$f(16)=2$，$f''(x)=\\frac14x^{-3/4}$，故 $f''(16)=1/32$。取 $\\Delta x=1$，得 $f(17)\\approx f(16)+f''(16)\\Delta x=2+1/32=65/32$。
INSERT INTO question_point (revision_id,point_id) VALUES ('beff4ccd-e6c4-5e3c-9cf5-6ebb02b799bd','f0906895-cb68-5047-aa48-8d61587457c0');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('07bc6a5f-f6d3-5711-8ea7-3e2c0dad84b9','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-27-05','d56b24a98616e3416a11525d45e7b31b71dc969be52e97b7bb3d49f8c5bc9639','00023-P1-27-05','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('4f3ac6f8-4f9c-55e2-8658-61a5cde87bd6','1bc86e3e-2bed-580c-b005-ec4ef354da9b','07bc6a5f-f6d3-5711-8ea7-3e2c0dad84b9','曲线由 $x=t^2+t$、$y=\\frac{t^3-2t}{t^2+t}$ 给出。在 $t=1$ 处，若 $dx=\\frac3{25}$，则对应的微分 $dy=$','["$\\\\frac1{20}$","$\\\\frac3{20}$","$-\\\\frac1{100}$","$\\\\frac1{10}$"]',3,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-27 微分及其运算',22);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('4f3ac6f8-4f9c-55e2-8658-61a5cde87bd6',0,'先用商法则求 $dy/dt$：$\\frac{(3t^2-2)(t^2+t)-(t^3-2t)(2t+1)}{(t^2+t)^2}$，在 $t=1$ 处为 $5/4$。又 $dx/dt=2t+1=3$，故 $dy=\\frac{5}{12}dx=\\frac{5}{12}\\cdot\\frac3{25}=1/20$。
INSERT INTO question_point (revision_id,point_id) VALUES ('4f3ac6f8-4f9c-55e2-8658-61a5cde87bd6','f0906895-cb68-5047-aa48-8d61587457c0');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('5f79e547-100d-56e3-82df-21e69bf0e4db','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-27-06','5b647934e858dbe285800ce6e01459ac8a3e2eb92f0759c7a0cf528ccda73bd8','00023-P1-27-06','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('091af21c-4867-5225-b934-711edfa51b9b','1bc86e3e-2bed-580c-b005-ec4ef354da9b','5f79e547-100d-56e3-82df-21e69bf0e4db','由 $x^2+y^2=5$ 确定的可导函数 $y=y(x)$ 经过点 $(1,2)$。令 $z=\\ln(x+y)+xy$。在该点若 $dx=\\frac3{20}$，则 $dz=$','["$\\\\frac7{20}$","$\\\\frac14$","$\\\\frac9{40}$","$\\\\frac{13}{40}$"]',3,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-27 微分及其运算',23);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('091af21c-4867-5225-b934-711edfa51b9b',1,'先由约束微分得 $2x\\,dx+2y\\,dy=0$，在 $(1,2)$ 处有 $dy=-dx/2$。再求 $dz=\\frac{dx+dy}{x+y}+y\\,dx+x\\,dy$，代入得 $dz=(1/6+3/2)dx=\\frac53\\cdot\\frac3{20}=1/4$。
INSERT INTO question_point (revision_id,point_id) VALUES ('091af21c-4867-5225-b934-711edfa51b9b','f0906895-cb68-5047-aa48-8d61587457c0');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('a3f680f7-6edd-5cef-8b4c-d86dd07bd337','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-28-01','c05ed1fe56c2ef7f608f8f41717a6fcd695738036de8fe2540194b5f894e4c93','00023-P1-28-01','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('428c70eb-5ced-57a9-861a-7b0c8d250a1e','1bc86e3e-2bed-580c-b005-ec4ef354da9b','a3f680f7-6edd-5cef-8b4c-d86dd07bd337','极限 $\\lim_{x\\to0}\\frac{\\sin3x}{2x}=$','["$\\\\frac12$","$3$","$\\\\frac32$","$0$"]',1,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-28 洛必达法则',24);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('428c70eb-5ced-57a9-861a-7b0c8d250a1e',2,'这是 $0/0$ 型。用洛必达法则得 $\\lim_{x\\to0}\\frac{3\\cos3x}{2}=3/2$。
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('0e5f8ec8-52f8-5411-a165-84113d187164','1da6de03-1c89-524f-824a-35bc7bb191ca','P1-28 洛必达法则','P1-28 洛必达法则');
INSERT INTO release_point (release_id,chapter_id,point_id,title_snapshot) VALUES ('1bc86e3e-2bed-580c-b005-ec4ef354da9b','1da6de03-1c89-524f-824a-35bc7bb191ca','0e5f8ec8-52f8-5411-a165-84113d187164','P1-28 洛必达法则');
INSERT INTO question_point (revision_id,point_id) VALUES ('428c70eb-5ced-57a9-861a-7b0c8d250a1e','0e5f8ec8-52f8-5411-a165-84113d187164');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('5868d79b-f1b8-531e-8dcf-68da2dd25949','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-28-02','d8afebf911d6cf7365e6bd6467d56a0c246f83bceb89cc84d64514b73591c65f','00023-P1-28-02','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('80585cdc-c910-53ce-aa87-c88e2e1541e6','1bc86e3e-2bed-580c-b005-ec4ef354da9b','5868d79b-f1b8-531e-8dcf-68da2dd25949','极限 $\\lim_{x\\to0}\\frac{\\ln(1+4x)}x=$','["$1$","$\\\\frac14$","$0$","$4$"]',1,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-28 洛必达法则',25);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('80585cdc-c910-53ce-aa87-c88e2e1541e6',3,'这是 $0/0$ 型。分子、分母分别求导，得 $\\lim_{x\\to0}\\frac4{1+4x}=4$。
INSERT INTO question_point (revision_id,point_id) VALUES ('80585cdc-c910-53ce-aa87-c88e2e1541e6','0e5f8ec8-52f8-5411-a165-84113d187164');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('4ff2317a-2edc-5269-88ee-a05bf69d72a4','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-28-03','5cf1e455aa90b7851f3359dfcf3c380a00912a7932ce61685e116e6dbc7429fe','00023-P1-28-03','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('fb23314b-ee60-5872-a911-69d5f25fb4e9','1bc86e3e-2bed-580c-b005-ec4ef354da9b','4ff2317a-2edc-5269-88ee-a05bf69d72a4','极限 $\\lim_{x\\to0}\\frac{e^{3x}-1-3x}{x^2}=$','["$\\\\frac92$","$9$","$\\\\frac32$","$0$"]',2,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-28 洛必达法则',26);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('fb23314b-ee60-5872-a911-69d5f25fb4e9',0,'原式为 $0/0$ 型。第一次应用洛必达后为 $\\lim_{x\\to0}\\frac{3e^{3x}-3}{2x}$，仍为 $0/0$ 型；再次应用得 $\\lim_{x\\to0}\\frac{9e^{3x}}2=9/2$。
INSERT INTO question_point (revision_id,point_id) VALUES ('fb23314b-ee60-5872-a911-69d5f25fb4e9','0e5f8ec8-52f8-5411-a165-84113d187164');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('001226b1-876a-5306-b970-0a12dda5302b','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-28-04','ac2d8537d5166d88f507368a878427d86278649ea10b12b6b611f708d037d2af','00023-P1-28-04','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('f1f76753-a790-51d9-bba0-3f03ad0da2eb','1bc86e3e-2bed-580c-b005-ec4ef354da9b','001226b1-876a-5306-b970-0a12dda5302b','极限 $\\lim_{x\\to1}\\frac{x^2-1-2\\ln x}{(x-1)^2}=$','["$0$","$2$","$1$","$4$"]',2,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-28 洛必达法则',27);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('f1f76753-a790-51d9-bba0-3f03ad0da2eb',1,'原式为 $0/0$ 型。一次洛必达得到 $\\frac{2x-2/x}{2(x-1)}$，在 $x=1$ 处仍是 $0/0$ 型；再求导得 $\\lim_{x\\to1}\\frac{2+2/x^2}{2}=2$。
INSERT INTO question_point (revision_id,point_id) VALUES ('f1f76753-a790-51d9-bba0-3f03ad0da2eb','0e5f8ec8-52f8-5411-a165-84113d187164');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('1abac2c4-9acb-58f6-a517-32a8501e2687','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-28-05','f4992a0146bddf512f60f40a1257ad691a5148aca23290968c0c0783dc0cfa1a','00023-P1-28-05','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('7297e8bf-c93f-56b6-a738-9a9479609b7a','1bc86e3e-2bed-580c-b005-ec4ef354da9b','1abac2c4-9acb-58f6-a517-32a8501e2687','设 $a,b$ 为实数，且 $L=\\lim_{x\\to0}\\frac{e^{2x}-1-ax-bx^2}{x^3}$ 存在并为有限实数，则 $a+b+L=$','["$\\\\frac{14}{3}$","$4$","$\\\\frac{16}{3}$","$\\\\frac{20}{3}$"]',3,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-28 洛必达法则',28);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('7297e8bf-c93f-56b6-a738-9a9479609b7a',2,'有限极限要求一次项、二次项依次消去：第一次求导后分子趋于 $2-a$，故 $a=2$；第二次求导后分子趋于 $4-2b$，故 $b=2$。此时第三次洛必达给出 $L=\\lim_{x\\to0}\\frac{8e^{2x}}6=4/3$，所以 $a+b+L=16/3$。
INSERT INTO question_point (revision_id,point_id) VALUES ('7297e8bf-c93f-56b6-a738-9a9479609b7a','0e5f8ec8-52f8-5411-a165-84113d187164');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('21718b94-ee5e-5f0a-b62c-da125fa0da99','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-28-06','3d0ff31c0b053a7cf18774af5bea70addc387f562cc408905262582d6ec9157d','00023-P1-28-06','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('7084fe81-28bc-5f0d-81cb-7a468004e7c9','1bc86e3e-2bed-580c-b005-ec4ef354da9b','21718b94-ee5e-5f0a-b62c-da125fa0da99','极限 $\\lim_{x\\to0}\\left(\\frac1{\\ln(1+2x)}-\\frac1{e^{2x}-1}\\right)=$','["$0$","$-1$","$\\\\frac12$","$1$"]',3,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-28 洛必达法则',29);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('7084fe81-28bc-5f0d-81cb-7a468004e7c9',3,'先通分为 $\\frac{e^{2x}-1-\\ln(1+2x)}{\\ln(1+2x)(e^{2x}-1)}$，是 $0/0$ 型。记分子为 $N$、分母为 $D$，有 $N(0)=D(0)=N''(0)=D''(0)=0$。计算 $N''''(0)=4+4=8$，$D''''(0)=2\\cdot2\\cdot2=8$，两次洛必达得极限为 $1$。
INSERT INTO question_point (revision_id,point_id) VALUES ('7084fe81-28bc-5f0d-81cb-7a468004e7c9','0e5f8ec8-52f8-5411-a165-84113d187164');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('9101825e-b0b7-5341-9066-6b49315c5451','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-29-01','d91efaf55ba60355d8a86e115ca4090e3eb3d0e776db8c3e08ad243b8e015093','00023-P1-29-01','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('9aa5af2d-83b8-573f-8b43-b5e0bc94bd16','1bc86e3e-2bed-580c-b005-ec4ef354da9b','9101825e-b0b7-5341-9066-6b49315c5451','函数 $f(x)=x^3-12x$ 的全部最大严格单调递增开区间为','["$(-\\\\infty,-2)$ 和 $(2,+\\\\infty)$","$(-2,2)$","$(-\\\\infty,2)$","$(0,+\\\\infty)$"]',1,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-29 函数的单调性',30);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('9aa5af2d-83b8-573f-8b43-b5e0bc94bd16',0,'$f''(x)=3(x^2-4)$。解 $f''(x)>0$ 得 $x<-2$ 或 $x>2$，因此两段最大递增开区间为 $(-\\infty,-2)$、$(2,+\\infty)$。
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('23f12af8-ba3c-58ff-9da9-55c35bba8d63','1da6de03-1c89-524f-824a-35bc7bb191ca','P1-29 函数的单调性','P1-29 函数的单调性');
INSERT INTO release_point (release_id,chapter_id,point_id,title_snapshot) VALUES ('1bc86e3e-2bed-580c-b005-ec4ef354da9b','1da6de03-1c89-524f-824a-35bc7bb191ca','23f12af8-ba3c-58ff-9da9-55c35bba8d63','P1-29 函数的单调性');
INSERT INTO question_point (revision_id,point_id) VALUES ('9aa5af2d-83b8-573f-8b43-b5e0bc94bd16','23f12af8-ba3c-58ff-9da9-55c35bba8d63');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('a583e3af-8352-5809-b71e-d1faa730a1fd','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-29-02','4eb339cbe66f5df90dfb470474a5950f2f3d0dcd94b5868c002474bb47e0ebd9','00023-P1-29-02','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('75f09e8e-1aee-5278-9c95-47a59a53693b','1bc86e3e-2bed-580c-b005-ec4ef354da9b','a583e3af-8352-5809-b71e-d1faa730a1fd','函数 $f(x)=\\ln x-2x$ 的最大严格单调递减开区间为','["$(0,\\\\frac12)$","$(\\\\frac12,+\\\\infty)$","$(0,+\\\\infty)$","$(2,+\\\\infty)$"]',1,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-29 函数的单调性',31);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('75f09e8e-1aee-5278-9c95-47a59a53693b',1,'定义域为 $x>0$，且 $f''(x)=1/x-2$。在定义域内解 $f''(x)<0$ 得 $x>1/2$，故最大递减开区间为 $(1/2,+\\infty)$。
INSERT INTO question_point (revision_id,point_id) VALUES ('75f09e8e-1aee-5278-9c95-47a59a53693b','23f12af8-ba3c-58ff-9da9-55c35bba8d63');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('4d90343e-b084-53ca-826f-0f538ea689c6','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-29-03','f180e830af2e3443c614ba310c0068f5e5cfa73868e6e50ab8f7958d8af8ddb5','00023-P1-29-03','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('4f08ce2f-28a4-5b45-abf6-43e4de1b4cdb','1bc86e3e-2bed-580c-b005-ec4ef354da9b','4d90343e-b084-53ca-826f-0f538ea689c6','函数 $f(x)=\\frac{x-1}{x+2}$ 的全部最大严格单调递增开区间为','["$(-\\\\infty,+\\\\infty)$","$(-2,+\\\\infty)$","$(-\\\\infty,-2)$ 和 $(-2,+\\\\infty)$","$(-\\\\infty,-2)$"]',2,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-29 函数的单调性',32);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('4f08ce2f-28a4-5b45-abf6-43e4de1b4cdb',2,'定义域排除 $x=-2$。求导得 $f''(x)=3/(x+2)^2>0$，因此在定义域的两个连通区间上分别严格递增，不能跨过无定义点合并。
INSERT INTO question_point (revision_id,point_id) VALUES ('4f08ce2f-28a4-5b45-abf6-43e4de1b4cdb','23f12af8-ba3c-58ff-9da9-55c35bba8d63');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('3ed03785-9b2a-53f4-809a-8985f5061070','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-29-04','c5666588e1f9f9a3b940b65c333cf2de4d6bc5db5a7ec4dd2ddd57cb4f2f0fb6','00023-P1-29-04','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('a4598128-482f-57d7-ac5f-c1908cd0b893','1bc86e3e-2bed-580c-b005-ec4ef354da9b','3ed03785-9b2a-53f4-809a-8985f5061070','函数 $f(x)=xe^{-x^2}$ 的全部最大严格单调递减开区间为','["$(-\\\\frac1{\\\\sqrt2},\\\\frac1{\\\\sqrt2})$","$(-\\\\infty,0)$ 和 $(0,+\\\\infty)$","$(-\\\\infty,-\\\\sqrt2)$ 和 $(\\\\sqrt2,+\\\\infty)$","$(-\\\\infty,-\\\\frac1{\\\\sqrt2})$ 和 $(\\\\frac1{\\\\sqrt2},+\\\\infty)$"]',2,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-29 函数的单调性',33);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('a4598128-482f-57d7-ac5f-c1908cd0b893',3,'乘积与链式法则给出 $f''(x)=e^{-x^2}(1-2x^2)$。指数因子恒正，所以 $f''<0$ 等价于 $x^2>1/2$，得到所列两段最大递减开区间。
INSERT INTO question_point (revision_id,point_id) VALUES ('a4598128-482f-57d7-ac5f-c1908cd0b893','23f12af8-ba3c-58ff-9da9-55c35bba8d63');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('92af90e1-2f60-5bad-b8b6-9c2e0e5ebfdf','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-29-05','1ac490dd1c4b7e5c947dc962a0688c9f4b5855ceba19227325b31701b19bc5de','00023-P1-29-05','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('5110a7bc-5371-5932-a570-aef209f194b6','1bc86e3e-2bed-580c-b005-ec4ef354da9b','92af90e1-2f60-5bad-b8b6-9c2e0e5ebfdf','设 $a$ 为实数。函数 $f_a(x)=x^3-3ax^2+3x$ 在 $\\mathbb R$ 上严格单调递增的充要条件是','["$-1\\\\le a\\\\le1$","$-1<a<1$","$a\\\\le-1$ 或 $a\\\\ge1$","$0\\\\le a\\\\le1$"]',3,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-29 函数的单调性',34);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('5110a7bc-5371-5932-a570-aef209f194b6',0,'$f_a''=3(x^2-2ax+1)=3[(x-a)^2+1-a^2]$。若 $|a|>1$，在 $x=a$ 处导数为负，不可能递增；若 $|a|\\le1$，导数处处非负，且仅可能在一个点为零，不会在任何非退化区间恒为零，故函数严格递增。
INSERT INTO question_point (revision_id,point_id) VALUES ('5110a7bc-5371-5932-a570-aef209f194b6','23f12af8-ba3c-58ff-9da9-55c35bba8d63');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('acae1a97-1184-5e9b-b383-68576c85905c','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-29-06','c16d20c58cbe80ea359dee0a06066fef2bb830bce3c151f7a68cb0537f78473d','00023-P1-29-06','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('05270b6b-cc53-51c2-8592-d7e494d3d80c','1bc86e3e-2bed-580c-b005-ec4ef354da9b','acae1a97-1184-5e9b-b383-68576c85905c','设 $a$ 为实数。函数 $f_a(x)=\\ln x-a\\frac{x-1}{x+1}$ 在 $(0,+\\infty)$ 上严格单调递增的充要条件是','["$a<2$","$a\\\\le2$","$a\\\\le4$","$a\\\\ge2$"]',3,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-29 函数的单调性',35);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('05270b6b-cc53-51c2-8592-d7e494d3d80c',1,'$f_a''=\\frac1x-\\frac{2a}{(x+1)^2}=\\frac{(x-1)^2+2(2-a)x}{x(x+1)^2}$。当 $a\\le2$ 时导数非负，且 $a=2$ 时仅在 $x=1$ 为零，所以仍严格递增。当 $a>2$ 时，$f_a''(1)=1-a/2<0$，故不成立。
INSERT INTO question_point (revision_id,point_id) VALUES ('05270b6b-cc53-51c2-8592-d7e494d3d80c','23f12af8-ba3c-58ff-9da9-55c35bba8d63');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('f447b132-c334-5d2a-9b3f-bb95278e88e2','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-30-01','9c4d7e5169dbe44c97c3f1484b42bc370ce06c049e8a6cd26322f850b6987f74','00023-P1-30-01','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('1864a8a5-326a-58d4-a501-bff777e74e13','1bc86e3e-2bed-580c-b005-ec4ef354da9b','f447b132-c334-5d2a-9b3f-bb95278e88e2','函数 $f(x)=x^3-3x^2+1$ 的极小值为','["$-3$","$1$","$2$","$0$"]',1,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-30 函数的极值与最值',36);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('1864a8a5-326a-58d4-a501-bff777e74e13',0,'$f''(x)=3x(x-2)$，在 $x=2$ 左侧为负、右侧为正，故该点为极小值点。代入得 $f(2)=8-12+1=-3$。
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('0374cb0d-c730-5fff-8c01-330c1baa1558','1da6de03-1c89-524f-824a-35bc7bb191ca','P1-30 函数的极值与最值','P1-30 函数的极值与最值');
INSERT INTO release_point (release_id,chapter_id,point_id,title_snapshot) VALUES ('1bc86e3e-2bed-580c-b005-ec4ef354da9b','1da6de03-1c89-524f-824a-35bc7bb191ca','0374cb0d-c730-5fff-8c01-330c1baa1558','P1-30 函数的极值与最值');
INSERT INTO question_point (revision_id,point_id) VALUES ('1864a8a5-326a-58d4-a501-bff777e74e13','0374cb0d-c730-5fff-8c01-330c1baa1558');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('f60d672e-8c61-5948-b5b9-494240068f50','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-30-02','a7164ea03bbe0fd9839d65143417b124df274ee3b4aae26435ccba37c7b828ec','00023-P1-30-02','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('b8868fb1-6237-58b4-8401-8b071219f467','1bc86e3e-2bed-580c-b005-ec4ef354da9b','f60d672e-8c61-5948-b5b9-494240068f50','函数 $f(x)=x^2-4x+1$ 在区间 $[-1,3]$ 上的最大值为','["$-3$","$6$","$-2$","$2$"]',1,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-30 函数的极值与最值',37);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('b8868fb1-6237-58b4-8401-8b071219f467',1,'驻点为 $x=2$。比较 $f(-1)=6$、$f(2)=-3$、$f(3)=-2$，最大值为 $6$。
INSERT INTO question_point (revision_id,point_id) VALUES ('b8868fb1-6237-58b4-8401-8b071219f467','0374cb0d-c730-5fff-8c01-330c1baa1558');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('53287fea-7b11-5987-8051-6cfb0931671a','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-30-03','bdf84b4028e82371894fb124bb1cca5c107af8bd76af9b44f2aa7ce15d1e965a','00023-P1-30-03','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('dda777f3-0e16-5663-b2fa-4eb218e4ec8b','1bc86e3e-2bed-580c-b005-ec4ef354da9b','53287fea-7b11-5987-8051-6cfb0931671a','函数 $f(x)=x^4-4x^2+3$ 的极大值与极小值之差为','["$3$","$2$","$4$","$-4$"]',2,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-30 函数的极值与最值',38);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('dda777f3-0e16-5663-b2fa-4eb218e4ec8b',2,'$f''=4x(x^2-2)$，驻点为 $0,\\pm\\sqrt2$。由 $f''''=12x^2-8$，知 $0$ 为极大值点、$\\pm\\sqrt2$ 为极小值点。极大值为 $3$，极小值为 $-1$，故差为 $4$。
INSERT INTO question_point (revision_id,point_id) VALUES ('dda777f3-0e16-5663-b2fa-4eb218e4ec8b','0374cb0d-c730-5fff-8c01-330c1baa1558');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('79dabd83-29d4-55d9-8129-af7dcd8312b1','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-30-04','2517c02a86316ef9306b4d8c910a4760e020f31c50fc9216fb235eb4e8797551','00023-P1-30-04','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('ae0a90b7-08c6-59e9-88c3-0a733018f8cd','1bc86e3e-2bed-580c-b005-ec4ef354da9b','79dabd83-29d4-55d9-8129-af7dcd8312b1','函数 $f(x)=\\frac{x}{1+x^2}$ 在区间 $[-2,0]$ 上的最小值为','["$-\\\\frac25$","$\\\\frac12$","$-1$","$-\\\\frac12$"]',2,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-30 函数的极值与最值',39);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('ae0a90b7-08c6-59e9-88c3-0a733018f8cd',3,'$f''(x)=\\frac{1-x^2}{(1+x^2)^2}$，区间内驻点为 $x=-1$。比较 $f(-2)=-2/5$、$f(-1)=-1/2$、$f(0)=0$，最小值为 $-1/2$。
INSERT INTO question_point (revision_id,point_id) VALUES ('ae0a90b7-08c6-59e9-88c3-0a733018f8cd','0374cb0d-c730-5fff-8c01-330c1baa1558');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('38b19d82-4fd5-55d7-ae89-38e6bd03de84','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-30-05','bbb15e276b5916d2aacd1c4f6d5b913c2a0ee781782f3011b8fa0026a8b9a622','00023-P1-30-05','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('c2b96128-aa01-5816-9bc7-060287820256','1bc86e3e-2bed-580c-b005-ec4ef354da9b','38b19d82-4fd5-55d7-ae89-38e6bd03de84','设 $f_a(x)=x^3-3ax^2+3(a^2-1)x$，其中 $a$ 为实数。已知 $x=2$ 是 $f_a$ 的极小值点。若 $M,m$ 分别是该函数在 $[-1,4]$ 上的最大值、最小值，则 $a+M-m=$','["$21$","$20$","$17$","$57$"]',3,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-30 函数的极值与最值',40);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('c2b96128-aa01-5816-9bc7-060287820256',0,'$f_a''=3[(x-a)^2-1]$，其两个驻点为 $a-1$、$a+1$，后者为极小值点，故 $a=1$。于是 $f=x^3-3x^2$。比较端点和驻点：$f(-1)=-4$、$f(0)=0$、$f(2)=-4$、$f(4)=16$，得 $M=16,m=-4$，所以结果为 $1+16+4=21$。
INSERT INTO question_point (revision_id,point_id) VALUES ('c2b96128-aa01-5816-9bc7-060287820256','0374cb0d-c730-5fff-8c01-330c1baa1558');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('95db7686-8150-56bf-93f2-211f582a976c','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-30-06','504fdb7ff20b2e8779c9e2b482f9283f2b3b1aa1cf0af04352d069beb78710fe','00023-P1-30-06','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('187e728b-a1f0-5e8b-86ce-f33b568654a8','1bc86e3e-2bed-580c-b005-ec4ef354da9b','95db7686-8150-56bf-93f2-211f582a976c','函数 $f(x)=|x^2-1|+x$ 在区间 $[-2,2]$ 上的最大值与最小值之差为','["$5$","$6$","$\\\\frac94$","$\\\\frac{25}{4}$"]',3,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-30 函数的极值与最值',41);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('187e728b-a1f0-5e8b-86ce-f33b568654a8',1,'当 $|x|\\ge1$ 时，$f=x^2+x-1$；当 $|x|<1$ 时，$f=1-x^2+x$。需比较端点 $\\pm2$、不可导点 $\\pm1$ 和内部驻点 $1/2$，对应函数值为 $1,5,-1,1,5/4$。故最大值为 $5$、最小值为 $-1$，差为 $6$。
INSERT INTO question_point (revision_id,point_id) VALUES ('187e728b-a1f0-5e8b-86ce-f33b568654a8','0374cb0d-c730-5fff-8c01-330c1baa1558');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('3408bbb7-caa9-5898-8c98-a1690829c934','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-31-01','1719b57b32dc71e7513b94aecaa5d2ff008702bb4922c1460df3ee79ded9a661','00023-P1-31-01','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('9650b606-6f85-51b4-9495-b6f4cefdf125','1bc86e3e-2bed-580c-b005-ec4ef354da9b','3408bbb7-caa9-5898-8c98-a1690829c934','不定积分 $\\int(6x^2-4x+3)\\,dx=$','["$6x^3-4x^2+3x+C$","$2x^3-2x^2+3+C$","$2x^3-2x^2+3x+C$","$2x^3+2x^2+3x+C$"]',1,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-31 原函数与不定积分',42);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('9650b606-6f85-51b4-9495-b6f4cefdf125',2,'逐项积分，使用幂函数积分公式及 $\\int3\\,dx=3x$，得到 $2x^3-2x^2+3x+C$。
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('8b0a4aff-0572-5fa9-a464-d6363c10952b','1da6de03-1c89-524f-824a-35bc7bb191ca','P1-31 原函数与不定积分','P1-31 原函数与不定积分');
INSERT INTO release_point (release_id,chapter_id,point_id,title_snapshot) VALUES ('1bc86e3e-2bed-580c-b005-ec4ef354da9b','1da6de03-1c89-524f-824a-35bc7bb191ca','8b0a4aff-0572-5fa9-a464-d6363c10952b','P1-31 原函数与不定积分');
INSERT INTO question_point (revision_id,point_id) VALUES ('9650b606-6f85-51b4-9495-b6f4cefdf125','8b0a4aff-0572-5fa9-a464-d6363c10952b');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('233266f6-64a7-54f8-9af9-2e21ad3d1864','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-31-02','e2c789de80a89525161f1734fc6c086588e027144659fbec6c75f0f26842fff1','00023-P1-31-02','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('aa4d460a-cf3a-5b6e-8d49-e3d703d7bb22','1bc86e3e-2bed-580c-b005-ec4ef354da9b','233266f6-64a7-54f8-9af9-2e21ad3d1864','设 $F$ 是 $f(x)=\\cos2x$ 在 $\\mathbb R$ 上的一个原函数，且 $F(\\pi/4)=3$，则 $F(0)=$','["$3$","$\\\\frac72$","$2$","$\\\\frac52$"]',1,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-31 原函数与不定积分',43);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('aa4d460a-cf3a-5b6e-8d49-e3d703d7bb22',3,'$F(x)=\\frac12\\sin2x+C$。由 $F(\\pi/4)=1/2+C=3$，得 $C=5/2$，因此 $F(0)=5/2$。
INSERT INTO question_point (revision_id,point_id) VALUES ('aa4d460a-cf3a-5b6e-8d49-e3d703d7bb22','8b0a4aff-0572-5fa9-a464-d6363c10952b');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('8729e178-dc41-5a81-81f1-169d4b899be2','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-31-03','85add22efff2c564b1a1032eb5fb27bf76d296cd3c432c74574b94bcbe799b6e','00023-P1-31-03','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('c48444ac-0c72-56f8-a850-aeddf7e760b2','1bc86e3e-2bed-580c-b005-ec4ef354da9b','8729e178-dc41-5a81-81f1-169d4b899be2','在区间 $(0,+\\infty)$ 上，不定积分 $\\int\\frac{x^2+1}{x}\\,dx=$','["$\\\\frac{x^2}{2}+\\\\ln x+C$","$\\\\frac{x^2}{2}-\\\\ln x+C$","$x^2+\\\\ln x+C$","$\\\\frac{x^2}{2}+\\\\frac1x+C$"]',2,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-31 原函数与不定积分',44);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('c48444ac-0c72-56f8-a850-aeddf7e760b2',0,'先拆分被积函数：$(x^2+1)/x=x+1/x$。分别积分得 $x^2/2+\\ln x+C$，因 $x>0$，对数可以直接写成 $\\ln x$。
INSERT INTO question_point (revision_id,point_id) VALUES ('c48444ac-0c72-56f8-a850-aeddf7e760b2','8b0a4aff-0572-5fa9-a464-d6363c10952b');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('33b96898-3b8e-53ec-9f3c-27d8e9426424','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-31-04','c1cfcfd9bce774afc8adfc320236dacf1ad716b91d35ceccee4d6e982a6356b6','00023-P1-31-04','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('851be042-1472-5d60-9094-e682d1c42d38','1bc86e3e-2bed-580c-b005-ec4ef354da9b','33b96898-3b8e-53ec-9f3c-27d8e9426424','设 $F''(x)=2x+1$、$F(0)=2$。若 $G$ 是 $F$ 在 $\\mathbb R$ 上的一个原函数，且 $G(0)=-1$，则 $G(1)=$','["$\\\\frac{17}{6}$","$\\\\frac{11}{6}$","$-\\\\frac16$","$\\\\frac52$"]',2,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-31 原函数与不定积分',45);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('851be042-1472-5d60-9094-e682d1c42d38',1,'第一次积分并利用 $F(0)=2$，得 $F=x^2+x+2$。再次积分得 $G=x^3/3+x^2/2+2x+C$。由 $G(0)=-1$ 得 $C=-1$，故 $G(1)=1/3+1/2+2-1=11/6$。
INSERT INTO question_point (revision_id,point_id) VALUES ('851be042-1472-5d60-9094-e682d1c42d38','8b0a4aff-0572-5fa9-a464-d6363c10952b');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('a7c409de-0940-56da-b9fd-2c526a97c9fc','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-31-05','25fb39ebde758ae37c9a9e2d3ac09107a9f93ad105407116e87145c1270c7df2','00023-P1-31-05','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('869d5915-464d-5b6b-b3f1-d7b9bc3912c6','1bc86e3e-2bed-580c-b005-ec4ef354da9b','a7c409de-0940-56da-b9fd-2c526a97c9fc','设 $F''(x)=2x$、$F(1)=3$。若 $R$ 是函数 $[F(x)]^2$ 在 $\\mathbb R$ 上的一个原函数，且 $R(0)=0$，则 $R(1)=$','["$\\\\frac{23}{15}$","$\\\\frac{21}{5}$","$\\\\frac{83}{15}$","$\\\\frac{73}{15}$"]',3,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-31 原函数与不定积分',46);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('869d5915-464d-5b6b-b3f1-d7b9bc3912c6',2,'先得 $F=x^2+C$，由 $F(1)=3$ 得 $C=2$。因此 $R''=(x^2+2)^2=x^4+4x^2+4$，积分并用 $R(0)=0$ 得 $R=x^5/5+4x^3/3+4x$。故 $R(1)=1/5+4/3+4=83/15$。
INSERT INTO question_point (revision_id,point_id) VALUES ('869d5915-464d-5b6b-b3f1-d7b9bc3912c6','8b0a4aff-0572-5fa9-a464-d6363c10952b');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('53217add-f581-5613-80f2-4c87d77af916','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-31-06','5dbd64df2510828c03ebea7b7f2aaa1450a79da2dedf495caecb240da1728ce8','00023-P1-31-06','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('923e4e20-5999-5e60-853d-4bbba0e3dd2a','1bc86e3e-2bed-580c-b005-ec4ef354da9b','53217add-f581-5613-80f2-4c87d77af916','设 $f$ 在 $\\mathbb R$ 上连续，$F$ 是它的一个原函数，且对任意实数 $x$ 均有 $F(x)+F(-x)=2x^2+6$。若 $G$ 是 $[f(x)-f(-x)]^2$ 的一个原函数，且 $G(0)=1$，则 $G(1)=$','["$\\\\frac{16}{3}$","$\\\\frac73$","$9$","$\\\\frac{19}{3}$"]',3,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-31 原函数与不定积分',47);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('923e4e20-5999-5e60-853d-4bbba0e3dd2a',3,'对恒等式求导，注意 $F(-x)$ 的导数为 $-f(-x)$，得 $f(x)-f(-x)=4x$。因此 $G''=16x^2$，积分得 $G=16x^3/3+C$。由 $G(0)=1$ 得 $C=1$，故 $G(1)=19/3$。
INSERT INTO question_point (revision_id,point_id) VALUES ('923e4e20-5999-5e60-853d-4bbba0e3dd2a','8b0a4aff-0572-5fa9-a464-d6363c10952b');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('234a6069-2bb6-5a87-a328-d5f8a8bd24ca','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-32-01','461c3d69b5e770727c859980e9abe9dc9796b06a497b8d0c101077cdbd25ed1c','00023-P1-32-01','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('a3f7bb6d-c11f-50b4-a221-c7501fc3bbf1','1bc86e3e-2bed-580c-b005-ec4ef354da9b','234a6069-2bb6-5a87-a328-d5f8a8bd24ca','不定积分 $\\int4x(x^2+1)^3\\,dx=$','["$\\\\frac12(x^2+1)^4+C$","$\\\\frac14(x^2+1)^4+C$","$(x^2+1)^4+C$","$2(x^2+1)^4+C$"]',1,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-32 不定积分—换元法',48);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('a3f7bb6d-c11f-50b4-a221-c7501fc3bbf1',0,'令 $u=x^2+1$，则 $du=2x\\,dx$，所以原式为 $2\\int u^3\\,du=\\frac12u^4+C$，代回即可。
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('71de9847-19ef-5a2c-a8d6-f65458ae20c0','1da6de03-1c89-524f-824a-35bc7bb191ca','P1-32 不定积分—换元法','P1-32 不定积分—换元法');
INSERT INTO release_point (release_id,chapter_id,point_id,title_snapshot) VALUES ('1bc86e3e-2bed-580c-b005-ec4ef354da9b','1da6de03-1c89-524f-824a-35bc7bb191ca','71de9847-19ef-5a2c-a8d6-f65458ae20c0','P1-32 不定积分—换元法');
INSERT INTO question_point (revision_id,point_id) VALUES ('a3f7bb6d-c11f-50b4-a221-c7501fc3bbf1','71de9847-19ef-5a2c-a8d6-f65458ae20c0');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('e3409a93-7f19-55da-a963-36769226b9f6','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-32-02','879f899202308f1c23c6fc7b39dd2dd15dcba2b8691860508c86ecd414cdaf52','00023-P1-32-02','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('214836c1-3d30-55ba-9182-7fe6f5e91edb','1bc86e3e-2bed-580c-b005-ec4ef354da9b','e3409a93-7f19-55da-a963-36769226b9f6','不定积分 $\\int\\frac{\\cos x}{2+\\sin x}\\,dx=$','["$\\\\frac1{2+\\\\sin x}+C$","$\\\\ln|2+\\\\sin x|+C$","$-\\\\ln|2+\\\\sin x|+C$","$\\\\frac12\\\\ln|2+\\\\sin x|+C$"]',1,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-32 不定积分—换元法',49);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('214836c1-3d30-55ba-9182-7fe6f5e91edb',1,'令 $u=2+\\sin x$，则 $du=\\cos x\\,dx$，原式为 $\\int du/u=\\ln|u|+C$。又 $2+\\sin x>0$，结果中的绝对值也可省略。
INSERT INTO question_point (revision_id,point_id) VALUES ('214836c1-3d30-55ba-9182-7fe6f5e91edb','71de9847-19ef-5a2c-a8d6-f65458ae20c0');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('419699d5-fe44-569b-af0a-58cec11f4b0a','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-32-03','209f8bf0c4de81cbda69bf11e9443eda1518adbc1cfe38772d6fbbc2928a9370','00023-P1-32-03','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('21fa74c9-bace-563d-8a3b-37722fcdc042','1bc86e3e-2bed-580c-b005-ec4ef354da9b','419699d5-fe44-569b-af0a-58cec11f4b0a','在区间 $(-2,2)$ 上，不定积分 $\\int\\frac{x}{\\sqrt{4-x^2}}\\,dx=$','["$\\\\sqrt{4-x^2}+C$","$-2\\\\sqrt{4-x^2}+C$","$-\\\\sqrt{4-x^2}+C$","$-\\\\frac12\\\\sqrt{4-x^2}+C$"]',2,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-32 不定积分—换元法',50);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('21fa74c9-bace-563d-8a3b-37722fcdc042',2,'令 $u=4-x^2$，则 $du=-2x\\,dx$。原式为 $-\\frac12\\int u^{-1/2}\\,du=-\\sqrt u+C$，故结果为 $-\\sqrt{4-x^2}+C$。
INSERT INTO question_point (revision_id,point_id) VALUES ('21fa74c9-bace-563d-8a3b-37722fcdc042','71de9847-19ef-5a2c-a8d6-f65458ae20c0');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('2ece3d48-794e-5cea-8d40-6125949b3178','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-32-04','0177bb83dc2dbaa6dffaf2119f2077c11813901837ba64c63cea01549fcea08f','00023-P1-32-04','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('70574f4e-b54d-546c-ae1e-3e6635277740','1bc86e3e-2bed-580c-b005-ec4ef354da9b','2ece3d48-794e-5cea-8d40-6125949b3178','不定积分 $\\int\\frac{e^{2x}}{1+e^{2x}}\\,dx=$','["$\\\\ln(1+e^{2x})+C$","$\\\\frac12\\\\ln(e^{2x})+C$","$-\\\\frac12\\\\ln(1+e^{2x})+C$","$\\\\frac12\\\\ln(1+e^{2x})+C$"]',2,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-32 不定积分—换元法',51);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('70574f4e-b54d-546c-ae1e-3e6635277740',3,'令 $u=1+e^{2x}$，则 $du=2e^{2x}\\,dx$。原式为 $\\frac12\\int du/u=\\frac12\\ln u+C$，且 $u>0$。
INSERT INTO question_point (revision_id,point_id) VALUES ('70574f4e-b54d-546c-ae1e-3e6635277740','71de9847-19ef-5a2c-a8d6-f65458ae20c0');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('7195ee47-b979-54eb-b132-4cbd9bc1944c','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-32-05','0440cf1a69c972fa2f8c8dcacf4bbbc12fdf83f408c1e5f2a70b1d5f421f4c19','00023-P1-32-05','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('44a5a824-8dfd-5f9f-a25f-b8d468cbc49d','1bc86e3e-2bed-580c-b005-ec4ef354da9b','7195ee47-b979-54eb-b132-4cbd9bc1944c','不定积分 $\\int\\left[\\frac{x\\ln(1+x^2)}{1+x^2}+\\frac{2x}{(1+x^2)^2}\\right]dx=$','["$\\\\frac14[\\\\ln(1+x^2)]^2-\\\\frac1{1+x^2}+C$","$\\\\frac12[\\\\ln(1+x^2)]^2-\\\\frac1{1+x^2}+C$","$\\\\frac14[\\\\ln(1+x^2)]^2+\\\\frac1{1+x^2}+C$","$\\\\frac14[\\\\ln(1+x^2)]^2-\\\\frac2{1+x^2}+C$"]',3,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-32 不定积分—换元法',52);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('44a5a824-8dfd-5f9f-a25f-b8d468cbc49d',0,'令 $u=1+x^2$，则 $du=2x\\,dx$。原式化为 $\\frac12\\int\\frac{\\ln u}{u}\\,du+\\int u^{-2}\\,du$。第一项再令 $v=\\ln u$，得 $v^2/4$；第二项为 $-1/u$。代回得到所选结果。
INSERT INTO question_point (revision_id,point_id) VALUES ('44a5a824-8dfd-5f9f-a25f-b8d468cbc49d','71de9847-19ef-5a2c-a8d6-f65458ae20c0');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('70ab7052-9c57-5a7c-aa70-fb77f40bac03','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-32-06','877ad2559a1ebc75801c73f83b46b0c869e921439a7a6cfb8a4aca6da6b4ca80','00023-P1-32-06','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('eb1ae972-f693-5107-ab79-5249d1a18963','1bc86e3e-2bed-580c-b005-ec4ef354da9b','70ab7052-9c57-5a7c-aa70-fb77f40bac03','不定积分 $\\int\\frac{x^3}{(1+x^2)^2}\\,dx=$','["$\\\\frac12\\\\ln(1+x^2)-\\\\frac1{2(1+x^2)}+C$","$\\\\frac12\\\\ln(1+x^2)+\\\\frac1{2(1+x^2)}+C$","$\\\\ln(1+x^2)+\\\\frac1{1+x^2}+C$","$\\\\frac12\\\\ln(1+x^2)+C$"]',3,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-32 不定积分—换元法',53);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('eb1ae972-f693-5107-ab79-5249d1a18963',1,'令 $u=1+x^2$，则 $x^3\\,dx=x^2(x\\,dx)=\\frac12(u-1)du$。原式为 $\\frac12\\int(u^{-1}-u^{-2})du=\\frac12\\ln u+\\frac1{2u}+C$，代回即可。
INSERT INTO question_point (revision_id,point_id) VALUES ('eb1ae972-f693-5107-ab79-5249d1a18963','71de9847-19ef-5a2c-a8d6-f65458ae20c0');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('36ef419c-0d8d-5667-916d-d37b45933127','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-33-01','c5d5341acc38267495afe21a87bfb9d8d0bfca2cc28f59441ee143b88c156ab2','00023-P1-33-01','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('4abf35f8-dc40-570e-9f0a-dc6c01eae662','1bc86e3e-2bed-580c-b005-ec4ef354da9b','36ef419c-0d8d-5667-916d-d37b45933127','不定积分 $\\int xe^{3x}\\,dx=$','["$\\\\frac{e^{3x}}9(3x-1)+C$","$\\\\frac{e^{3x}}9(3x+1)+C$","$\\\\frac{x e^{3x}}3+C$","$\\\\frac{e^{3x}}3(x-1)+C$"]',1,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-33 不定积分—分部积分法',54);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('4abf35f8-dc40-570e-9f0a-dc6c01eae662',0,'取 $u=x$、$dv=e^{3x}dx$，则 $du=dx$、$v=e^{3x}/3$。分部积分得 $xe^{3x}/3-\\frac13\\int e^{3x}dx=xe^{3x}/3-e^{3x}/9+C$。
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('9ae65766-8279-5165-98a4-e9276e744c82','1da6de03-1c89-524f-824a-35bc7bb191ca','P1-33 不定积分—分部积分法','P1-33 不定积分—分部积分法');
INSERT INTO release_point (release_id,chapter_id,point_id,title_snapshot) VALUES ('1bc86e3e-2bed-580c-b005-ec4ef354da9b','1da6de03-1c89-524f-824a-35bc7bb191ca','9ae65766-8279-5165-98a4-e9276e744c82','P1-33 不定积分—分部积分法');
INSERT INTO question_point (revision_id,point_id) VALUES ('4abf35f8-dc40-570e-9f0a-dc6c01eae662','9ae65766-8279-5165-98a4-e9276e744c82');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('6677e189-3d92-55e8-8d1a-570e935f425b','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-33-02','d5b91bf8f765312f1461a15769d6fdf1fc9d6a3d867a9103dc57627bc70e74bf','00023-P1-33-02','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('277495d3-a4bd-56b9-9dbd-12cb2606c594','1bc86e3e-2bed-580c-b005-ec4ef354da9b','6677e189-3d92-55e8-8d1a-570e935f425b','在区间 $(0,+\\infty)$ 上，不定积分 $\\int\\ln x\\,dx=$','["$x\\\\ln x+C$","$x\\\\ln x-x+C$","$x\\\\ln x+x+C$","$x\\\\ln x-\\\\ln x+C$"]',1,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-33 不定积分—分部积分法',55);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('277495d3-a4bd-56b9-9dbd-12cb2606c594',1,'取 $u=\\ln x$、$dv=dx$，有 $du=dx/x$、$v=x$。故原式为 $x\\ln x-\\int1\\,dx=x\\ln x-x+C$。
INSERT INTO question_point (revision_id,point_id) VALUES ('277495d3-a4bd-56b9-9dbd-12cb2606c594','9ae65766-8279-5165-98a4-e9276e744c82');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('2ea33c27-c2ba-5f47-9eca-9f18ec9cf012','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-33-03','5608ccb31dcd42e904a245478d546e71a87dd98aa6cbbb874c7b0e219c85735a','00023-P1-33-03','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('3410209f-16fd-5d63-b595-38f263ea7637','1bc86e3e-2bed-580c-b005-ec4ef354da9b','2ea33c27-c2ba-5f47-9eca-9f18ec9cf012','不定积分 $\\int x\\cos2x\\,dx=$','["$\\\\frac{x\\\\sin2x}2-\\\\frac{\\\\cos2x}4+C$","$\\\\frac{x\\\\sin2x}2+\\\\frac{\\\\cos2x}2+C$","$\\\\frac{x\\\\sin2x}2+\\\\frac{\\\\cos2x}4+C$","$\\\\frac{x\\\\sin2x}2+\\\\frac{\\\\cos2x}8+C$"]',2,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-33 不定积分—分部积分法',56);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('3410209f-16fd-5d63-b595-38f263ea7637',2,'取 $u=x$、$dv=\\cos2x\\,dx$，则 $v=\\sin2x/2$。原式为 $x\\sin2x/2-\\frac12\\int\\sin2x\\,dx$。由于 $\\int\\sin2x\\,dx=-\\cos2x/2$，故结果为 $x\\sin2x/2+\\cos2x/4+C$。
INSERT INTO question_point (revision_id,point_id) VALUES ('3410209f-16fd-5d63-b595-38f263ea7637','9ae65766-8279-5165-98a4-e9276e744c82');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('8937bf96-5d31-5f61-b3fa-f08aa43c8578','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-33-04','42ca34bf146c0d81d6b258b1001c2b84a231bac9f1d8765b1a13b1a8ab1fdc2d','00023-P1-33-04','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('fa7a7104-f05f-55fc-839d-3feab79b6aaa','1bc86e3e-2bed-580c-b005-ec4ef354da9b','8937bf96-5d31-5f61-b3fa-f08aa43c8578','不定积分 $\\int x^2e^x\\,dx=$','["$e^x(x^2-2x)+C$","$e^x(x^2+2x-2)+C$","$e^x(x^2-2x+1)+C$","$e^x(x^2-2x+2)+C$"]',2,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-33 不定积分—分部积分法',57);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('fa7a7104-f05f-55fc-839d-3feab79b6aaa',3,'第一次分部积分得 $x^2e^x-2\\int xe^x dx$。再用 $\\int xe^x dx=xe^x-e^x+C$，得 $e^x(x^2-2x+2)+C$。
INSERT INTO question_point (revision_id,point_id) VALUES ('fa7a7104-f05f-55fc-839d-3feab79b6aaa','9ae65766-8279-5165-98a4-e9276e744c82');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('4f4eea88-57d6-500f-9dab-476ef129a8af','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-33-05','a85cb579c2b53724ad9b4dbd610a466e0e0901e3f7b1bc39f73550f177b5beab','00023-P1-33-05','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('b76ffcc0-6ca3-5065-8dcc-bc7db83bb4a7','1bc86e3e-2bed-580c-b005-ec4ef354da9b','4f4eea88-57d6-500f-9dab-476ef129a8af','在区间 $(0,+\\infty)$ 上，不定积分 $\\int x(\\ln x)^2\\,dx=$','["$\\\\frac{x^2}2(\\\\ln x)^2-\\\\frac{x^2}2\\\\ln x+\\\\frac{x^2}4+C$","$\\\\frac{x^2}2(\\\\ln x)^2-x^2\\\\ln x+\\\\frac{x^2}2+C$","$\\\\frac{x^2}2(\\\\ln x)^2-\\\\frac{x^2}2\\\\ln x+C$","$\\\\frac{x^2}2(\\\\ln x)^2+\\\\frac{x^2}2\\\\ln x-\\\\frac{x^2}4+C$"]',3,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-33 不定积分—分部积分法',58);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('b76ffcc0-6ca3-5065-8dcc-bc7db83bb4a7',0,'取 $u=(\\ln x)^2$、$dv=x\\,dx$，得原式为 $\\frac{x^2}2(\\ln x)^2-\\int x\\ln x\\,dx$。余项再分部积分：$\\int x\\ln x\\,dx=\\frac{x^2}2\\ln x-\\frac{x^2}4+C$。代回得到所选结果。
INSERT INTO question_point (revision_id,point_id) VALUES ('b76ffcc0-6ca3-5065-8dcc-bc7db83bb4a7','9ae65766-8279-5165-98a4-e9276e744c82');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('f51a3cbc-bb81-5aed-814b-a45734cdc272','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-33-06','cebbf6ae12bf7f9ff966ca48dac0782b972943fa810178911d08af8aef5a3c52','00023-P1-33-06','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('07bc6a27-3676-5d74-9f61-0406640537a1','1bc86e3e-2bed-580c-b005-ec4ef354da9b','f51a3cbc-bb81-5aed-814b-a45734cdc272','不定积分 $\\int xe^x\\cos x\\,dx=$','["$\\\\frac{e^x}2[x\\\\cos x+(x+1)\\\\sin x]+C$","$\\\\frac{e^x}2[x\\\\cos x+(x-1)\\\\sin x]+C$","$e^x[x\\\\cos x+(x-1)\\\\sin x]+C$","$\\\\frac{xe^x}2(\\\\sin x+\\\\cos x)+C$"]',3,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-33 不定积分—分部积分法',59);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('07bc6a27-3676-5d74-9f61-0406640537a1',1,'先对 $\\int e^x\\cos x\\,dx$ 连续分部积分并解循环关系，得 $V=\\frac{e^x}2(\\sin x+\\cos x)$。再取 $u=x$、$dv=e^x\\cos x\\,dx$，原式为 $xV-\\int Vdx$。由于 $\\int Vdx=\\frac{e^x}2\\sin x$，故结果为 $\\frac{e^x}2[x\\cos x+(x-1)\\sin x]+C$。
INSERT INTO question_point (revision_id,point_id) VALUES ('07bc6a27-3676-5d74-9f61-0406640537a1','9ae65766-8279-5165-98a4-e9276e744c82');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('7e78f186-cadc-58c7-95b1-9b999ae502f8','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-34-01','c21bc19cd9fbdf563857bcce904a5ceae45483f8bf4314445e7d8839a9c66701','00023-P1-34-01','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('3b7ae58c-7c86-54ae-aa97-ee62047d689e','1bc86e3e-2bed-580c-b005-ec4ef354da9b','7e78f186-cadc-58c7-95b1-9b999ae502f8','由定积分的几何意义，$\\int_0^2(x-1)\\,dx=$','["$-1$","$1$","$0$","$2$"]',1,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-34 定积分的几何意义',60);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('3b7ae58c-7c86-54ae-aa97-ee62047d689e',2,'直线在 $[0,1]$ 上位于横轴下方、在 $[1,2]$ 上位于横轴上方。两段三角形面积均为 $1/2$，带符号相加得 $-1/2+1/2=0$。
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('3709d441-7cb2-55bb-ba7d-f18752e64898','1da6de03-1c89-524f-824a-35bc7bb191ca','P1-34 定积分的几何意义','P1-34 定积分的几何意义');
INSERT INTO release_point (release_id,chapter_id,point_id,title_snapshot) VALUES ('1bc86e3e-2bed-580c-b005-ec4ef354da9b','1da6de03-1c89-524f-824a-35bc7bb191ca','3709d441-7cb2-55bb-ba7d-f18752e64898','P1-34 定积分的几何意义');
INSERT INTO question_point (revision_id,point_id) VALUES ('3b7ae58c-7c86-54ae-aa97-ee62047d689e','3709d441-7cb2-55bb-ba7d-f18752e64898');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('89f52b2a-0de1-5fd8-a154-69965cc97a01','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-34-02','279b1640cc6fdf123bdda2ae5430eeabbe1b482434b681cecfdc68c12b8544d1','00023-P1-34-02','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('92e4aca6-6390-575c-8f17-0ec3eb3f258d','1bc86e3e-2bed-580c-b005-ec4ef354da9b','89f52b2a-0de1-5fd8-a154-69965cc97a01','曲线 $y=x^2$、横轴及直线 $x=0$、$x=3$ 所围成图形的面积为','["$3$","$27$","$-9$","$9$"]',1,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-34 定积分的几何意义',61);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('92e4aca6-6390-575c-8f17-0ec3eb3f258d',3,'函数在该区间非负，面积等于 $\\int_0^3x^2dx=[x^3/3]_0^3=9$。
INSERT INTO question_point (revision_id,point_id) VALUES ('92e4aca6-6390-575c-8f17-0ec3eb3f258d','3709d441-7cb2-55bb-ba7d-f18752e64898');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('79f75b32-1d19-5482-b06a-309201f3a321','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-34-03','22d1c026a33cfeadb0df9d13e018c89a477abcae1ed9d3b5570e093ba7eb92dc','00023-P1-34-03','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('cfbc65ea-b7db-560f-a3f2-988dd3a66c20','1bc86e3e-2bed-580c-b005-ec4ef354da9b','79f75b32-1d19-5482-b06a-309201f3a321','曲线 $y=x^2-1$、横轴及直线 $x=-2$、$x=2$ 所围成图形的总面积为','["$4$","$\\\\frac43$","$\\\\frac83$","$2$"]',2,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-34 定积分的几何意义',62);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('cfbc65ea-b7db-560f-a3f2-988dd3a66c20',0,'零点为 $\\pm1$，在中间区间函数为负。利用对称性，面积为 $2[\\int_0^1(1-x^2)dx+\\int_1^2(x^2-1)dx]=2(2/3+4/3)=4$。
INSERT INTO question_point (revision_id,point_id) VALUES ('cfbc65ea-b7db-560f-a3f2-988dd3a66c20','3709d441-7cb2-55bb-ba7d-f18752e64898');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('4fcdbc73-021a-5873-98fb-af925b79b8a6','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-34-04','8263f48fe8c02d8f6fdec501586684b28aaaaa71d572e998947254f3fe306d94','00023-P1-34-04','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('4d38e341-b6a7-5467-a8d3-4223b4312a87','1bc86e3e-2bed-580c-b005-ec4ef354da9b','4fcdbc73-021a-5873-98fb-af925b79b8a6','曲线 $y=2x-x^2$、横轴及直线 $x=-1$、$x=3$ 所围成图形的总面积为','["$-\\\\frac43$","$4$","$\\\\frac83$","$\\\\frac43$"]',2,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-34 定积分的几何意义',63);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('4d38e341-b6a7-5467-a8d3-4223b4312a87',1,'零点为 $0,2$。在 $[-1,0]$ 和 $[2,3]$ 上函数为负，在 $[0,2]$ 上为正。三段几何面积各为 $4/3$，故总面积为 $4$。
INSERT INTO question_point (revision_id,point_id) VALUES ('4d38e341-b6a7-5467-a8d3-4223b4312a87','3709d441-7cb2-55bb-ba7d-f18752e64898');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('2788462c-f8ac-5dd3-aa72-33f33253fc2c','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-34-05','86a3767c51610d35756b27ece80d6b9aa674f1b09fb4e56b88e2cac02740c0de','00023-P1-34-05','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('12f947ee-4938-5baf-b728-76ba2446163c','1bc86e3e-2bed-580c-b005-ec4ef354da9b','2788462c-f8ac-5dd3-aa72-33f33253fc2c','设 $f$ 在 $[-2,3]$ 上连续，在 $[-2,0]$ 上非正、在 $[0,3]$ 上非负，且 $\\int_{-2}^3 f(x)dx=2$、$\\int_{-2}^3|f(x)|dx=8$。则 $\\int_3^0f(x)dx+2\\int_{-2}^0f(x)dx=$','["$1$","$-1$","$-11$","$-8$"]',3,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-34 定积分的几何意义',64);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('12f947ee-4938-5baf-b728-76ba2446163c',2,'记上方几何面积为 $P$、下方几何面积为 $N$，则 $P-N=2$、$P+N=8$，解得 $P=5,N=3$。因此 $\\int_3^0f=-5$、$\\int_{-2}^0f=-3$，所求为 $-5+2(-3)=-11$。
INSERT INTO question_point (revision_id,point_id) VALUES ('12f947ee-4938-5baf-b728-76ba2446163c','3709d441-7cb2-55bb-ba7d-f18752e64898');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('ecd5d721-9da0-5052-bdc9-e720cda4877b','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-34-06','0d31db6dfddc98d7f6d7fbb50dd6a45e1b9e73dcf062b61c66bff06b3fded0da','00023-P1-34-06','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('c10fb749-096d-5450-9554-d3ef28318b24','1bc86e3e-2bed-580c-b005-ec4ef354da9b','ecd5d721-9da0-5052-bdc9-e720cda4877b','设 $h>0$，连续函数 $f$ 在 $[0,5]$ 上的图像由依次连接 $(0,0)$、$(1,2)$、$(2,0)$、$(4,-h)$、$(5,0)$ 的直线段组成。已知 $\\frac15\\int_0^5f(x)dx=-1$，则 $\\int_0^5|f(x)|dx=$','["$-5$","$7$","$5$","$9$"]',3,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-34 定积分的几何意义',65);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('c10fb749-096d-5450-9554-d3ef28318b24',3,'横轴上方是底为 $2$、高为 $2$ 的三角形，面积为 $2$；下方是底为 $3$、高为 $h$ 的三角形，面积为 $3h/2$。由平均值条件得 $2-3h/2=-5$，故下方面积为 $7$，总面积为 $2+7=9$。
INSERT INTO question_point (revision_id,point_id) VALUES ('c10fb749-096d-5450-9554-d3ef28318b24','3709d441-7cb2-55bb-ba7d-f18752e64898');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('2f42e47d-64fd-5699-95a6-9c967e03c6c3','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-35-01','62a70c687238337b265a4058a6e54a26577d0281a14e232bda8626ce072ba677','00023-P1-35-01','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('aabf2323-7e2d-5ee2-b060-f4012a7e6a44','1bc86e3e-2bed-580c-b005-ec4ef354da9b','2f42e47d-64fd-5699-95a6-9c967e03c6c3','设 $f,g$ 在 $[1,3]$ 上连续，$\\int_1^3f(x)dx=4$、$\\int_1^3g(x)dx=-1$，则 $\\int_3^1[2f(x)-3g(x)]dx=$','["$-11$","$11$","$-5$","$-7$"]',1,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-35 定积分的性质',66);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('aabf2323-7e2d-5ee2-b060-f4012a7e6a44',0,'先用线性性质，正向积分为 $2\\cdot4-3(-1)=11$。再交换上下限，得所求为 $-11$。
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('194eb774-694c-54ad-9d33-77269071e147','1da6de03-1c89-524f-824a-35bc7bb191ca','P1-35 定积分的性质','P1-35 定积分的性质');
INSERT INTO release_point (release_id,chapter_id,point_id,title_snapshot) VALUES ('1bc86e3e-2bed-580c-b005-ec4ef354da9b','1da6de03-1c89-524f-824a-35bc7bb191ca','194eb774-694c-54ad-9d33-77269071e147','P1-35 定积分的性质');
INSERT INTO question_point (revision_id,point_id) VALUES ('aabf2323-7e2d-5ee2-b060-f4012a7e6a44','194eb774-694c-54ad-9d33-77269071e147');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('ee26d821-7d63-57c6-a12b-aa5017f8955e','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-35-02','50ba995cac346cfbf49d46c555b413014774c31d92723be716a2d53432160c8e','00023-P1-35-02','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('b89af763-a63c-5aa2-a297-0023f5f8a331','1bc86e3e-2bed-580c-b005-ec4ef354da9b','ee26d821-7d63-57c6-a12b-aa5017f8955e','定积分 $\\int_{-2}^2(x^3+2x^2+1)dx=$','["$\\\\frac{22}{3}$","$\\\\frac{44}{3}$","$\\\\frac{32}{3}$","$4$"]',1,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-35 定积分的性质',67);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('b89af763-a63c-5aa2-a297-0023f5f8a331',1,'奇函数项 $x^3$ 在对称区间积分为零。其余两项给出 $2\\int_{-2}^2x^2dx+\\int_{-2}^21dx=32/3+4=44/3$。
INSERT INTO question_point (revision_id,point_id) VALUES ('b89af763-a63c-5aa2-a297-0023f5f8a331','194eb774-694c-54ad-9d33-77269071e147');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('663e8a56-6bac-58d6-ad9e-0d5a549ef9d2','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-35-03','bf5c99c74ba3c49c05fcdcd26858ef8343ef146842bdb3633502070c35b5ae11','00023-P1-35-03','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('9ee29a60-2bf0-5278-b26c-68f8989baea1','1bc86e3e-2bed-580c-b005-ec4ef354da9b','663e8a56-6bac-58d6-ad9e-0d5a549ef9d2','设 $f$ 在 $[0,3]$ 上连续，且 $\\int_0^1f(x)dx=2$、$\\int_0^3f(x)dx=-1$，则 $\\int_3^1[2f(x)+1]dx=$','["$-4$","$8$","$4$","$1$"]',2,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-35 定积分的性质',68);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('9ee29a60-2bf0-5278-b26c-68f8989baea1',2,'区间可加性给出 $\\int_1^3f=-1-2=-3$，所以 $\\int_3^1f=3$。所求为 $2\\cdot3+(1-3)=4$。
INSERT INTO question_point (revision_id,point_id) VALUES ('9ee29a60-2bf0-5278-b26c-68f8989baea1','194eb774-694c-54ad-9d33-77269071e147');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('948a10fc-ffd6-5c2c-8c80-d7f1b6af919e','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-35-04','c05b1d25727e29d4e86b79733007b545f20b5da37a22a920a59205bc0c6f324e','00023-P1-35-04','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('4bf2f064-db93-52e2-b7c1-9c1e41eeb4df','1bc86e3e-2bed-580c-b005-ec4ef354da9b','948a10fc-ffd6-5c2c-8c80-d7f1b6af919e','设 $f$ 在 $[-1,1]$ 上连续，且 $f(x)+f(-x)=2x^2+4$，则 $\\int_{-1}^1f(x)dx=$','["$\\\\frac{28}{3}$","$\\\\frac73$","$4$","$\\\\frac{14}{3}$"]',2,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-35 定积分的性质',69);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('4bf2f064-db93-52e2-b7c1-9c1e41eeb4df',3,'记所求为 $I$。对称区间上 $\\int_{-1}^1f(-x)dx=I$，故 $2I=\\int_{-1}^1(2x^2+4)dx=28/3$，得 $I=14/3$。
INSERT INTO question_point (revision_id,point_id) VALUES ('4bf2f064-db93-52e2-b7c1-9c1e41eeb4df','194eb774-694c-54ad-9d33-77269071e147');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('ce39448d-ef87-5b30-a259-ba75121053af','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-35-05','3aa1adb6f92f18f38946db8f55f047695cd874e12e8daca010a98054fb455173','00023-P1-35-05','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('ffb91ec1-7078-556e-ade1-aeee555c4760','1bc86e3e-2bed-580c-b005-ec4ef354da9b','ce39448d-ef87-5b30-a259-ba75121053af','设 $f$ 在 $[-1,1]$ 上连续，且 $f(x)+f(-x)=2x^2+2$、$\\int_0^1xf(x)dx=1$。则 $\\int_{-1}^1xf(x)dx=$','["$\\\\frac12$","$\\\\frac32$","$-\\\\frac12$","$-\\\\frac32$"]',3,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-35 定积分的性质',70);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('ffb91ec1-7078-556e-ade1-aeee555c4760',0,'左半区间令 $x=-t$，有 $\\int_{-1}^0xf(x)dx=-\\int_0^1t f(-t)dt$。因此所求为 $\\int_0^1x[f(x)-f(-x)]dx$。由恒等式，差为 $2f(x)-2x^2-2$，故结果为 $2\\cdot1-\\int_0^1(2x^3+2x)dx=2-3/2=1/2$。
INSERT INTO question_point (revision_id,point_id) VALUES ('ffb91ec1-7078-556e-ade1-aeee555c4760','194eb774-694c-54ad-9d33-77269071e147');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('4086ba73-500f-59e2-8760-32e2d48d30a0','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-35-06','a0c2c79e001516094ce013ef3c12cf24fe82e92304d1ba42491ac73383f6542e','00023-P1-35-06','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('67d3683a-3ad4-5074-a65f-19c1abeebb6f','1bc86e3e-2bed-580c-b005-ec4ef354da9b','4086ba73-500f-59e2-8760-32e2d48d30a0','设 $f$ 在 $[-1,1]$ 上连续，且 $f(x)+f(-x)=4$、$\\int_{-1}^1[f(x)]^2dx=10$。则 $\\int_{-1}^1f(x)f(-x)dx=$','["$16$","$6$","$-2$","$10$"]',3,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-35 定积分的性质',71);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('67d3683a-3ad4-5074-a65f-19c1abeebb6f',1,'记 $I=\\int_{-1}^1f$，对恒等式积分得 $2I=\\int_{-1}^14dx=8$，故 $I=4$。再由 $f(-x)=4-f(x)$，所求为 $4I-\\int_{-1}^1f^2=16-10=6$。
INSERT INTO question_point (revision_id,point_id) VALUES ('67d3683a-3ad4-5074-a65f-19c1abeebb6f','194eb774-694c-54ad-9d33-77269071e147');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('9f84b121-ed5f-559b-96a5-6fa9b7b86e24','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-36-01','775b6695caa5424b74d1a162f5381207571dadb5d2de7cbc4d2e4843326208fa','00023-P1-36-01','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('d4fa621c-1085-5270-ac14-abf30c4165ed','1bc86e3e-2bed-580c-b005-ec4ef354da9b','9f84b121-ed5f-559b-96a5-6fa9b7b86e24','设 $F(x)=\\int_1^x(t^3+2t)dt$，则 $F''(2)=$','["$12$","$\\\\frac{27}{4}$","$14$","$-12$"]',1,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-36 微积分基本定理',72);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('d4fa621c-1085-5270-ac14-abf30c4165ed',0,'由微积分基本定理，$F''(x)=x^3+2x$，故 $F''(2)=8+4=12$。
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('d64b25c2-836c-5b28-8c5c-b8267802619e','1da6de03-1c89-524f-824a-35bc7bb191ca','P1-36 微积分基本定理','P1-36 微积分基本定理');
INSERT INTO release_point (release_id,chapter_id,point_id,title_snapshot) VALUES ('1bc86e3e-2bed-580c-b005-ec4ef354da9b','1da6de03-1c89-524f-824a-35bc7bb191ca','d64b25c2-836c-5b28-8c5c-b8267802619e','P1-36 微积分基本定理');
INSERT INTO question_point (revision_id,point_id) VALUES ('d4fa621c-1085-5270-ac14-abf30c4165ed','d64b25c2-836c-5b28-8c5c-b8267802619e');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('ddc38cee-9814-542a-88de-db43f0899623','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-36-02','eb13e81bc3b11daf67eb5cf54629c5c318bf1da0d7024ca1267cf385878a6a01','00023-P1-36-02','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('c6d4e29b-18e2-55c3-8d79-3bd5132101d8','1bc86e3e-2bed-580c-b005-ec4ef354da9b','ddc38cee-9814-542a-88de-db43f0899623','设 $F(x)=\\int_0^{x^2}(1+t^2)dt$，则 $F''(1)=$','["$2$","$4$","$\\\\frac43$","$-4$"]',1,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-36 微积分基本定理',73);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('c6d4e29b-18e2-55c3-8d79-3bd5132101d8',1,'上限为复合函数，故 $F''(x)=(1+x^4)\\cdot2x$。代入 $x=1$ 得 $4$。
INSERT INTO question_point (revision_id,point_id) VALUES ('c6d4e29b-18e2-55c3-8d79-3bd5132101d8','d64b25c2-836c-5b28-8c5c-b8267802619e');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('fe95e156-4737-5bc0-9bb4-6033e9b3a240','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-36-03','2ead9ae8a30ed068cb7813e47c91058b53b248c6d341c80b4657cf2668cf6865','00023-P1-36-03','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('1a925539-a1a0-5673-9018-f237ce52f623','1bc86e3e-2bed-580c-b005-ec4ef354da9b','fe95e156-4737-5bc0-9bb4-6033e9b3a240','设 $F(x)=\\int_x^{2x}(t^2+1)dt$，则 $F''(1)=$','["$10$","$3$","$8$","$12$"]',2,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-36 微积分基本定理',74);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('1a925539-a1a0-5673-9018-f237ce52f623',2,'上下限均变动，$F''(x)=[(2x)^2+1]\\cdot2-(x^2+1)$。代入 $x=1$ 得 $10-2=8$。
INSERT INTO question_point (revision_id,point_id) VALUES ('1a925539-a1a0-5673-9018-f237ce52f623','d64b25c2-836c-5b28-8c5c-b8267802619e');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('61bae0fd-ced9-547c-9e7b-fe33548d9742','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-36-04','769afd6dad3f213551813997bf6736ef2309a0c85efbc72b74a21b78e02a8ce2','00023-P1-36-04','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('d57e7e85-64f3-5daa-95dc-69c00a198592','1bc86e3e-2bed-580c-b005-ec4ef354da9b','61bae0fd-ced9-547c-9e7b-fe33548d9742','设 $F(x)=\\int_0^x\\ln(1+t^2)dt$，则 $F''''(1)=$','["$\\\\ln2$","$2$","$\\\\frac12$","$1$"]',2,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-36 微积分基本定理',75);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('d57e7e85-64f3-5daa-95dc-69c00a198592',3,'先用基本定理得 $F''(x)=\\ln(1+x^2)$，再用链式法则得 $F''''(x)=2x/(1+x^2)$，故 $F''''(1)=1$。
INSERT INTO question_point (revision_id,point_id) VALUES ('d57e7e85-64f3-5daa-95dc-69c00a198592','d64b25c2-836c-5b28-8c5c-b8267802619e');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('549805e1-b74d-5f8c-9bf7-2403b40b319e','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-36-05','45a43725ef9b54bcf61386f988f023d547119ce1b39b251dd97adb3610d10a2c','00023-P1-36-05','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('a14277eb-f2f1-5b76-b05f-0792da634623','1bc86e3e-2bed-580c-b005-ec4ef354da9b','549805e1-b74d-5f8c-9bf7-2403b40b319e','设 $F(x)=\\int_{x^2}^{2x}(t^2+1)dt$，则 $F''''(1)=$','["$4$","$8$","$-4$","$28$"]',3,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-36 微积分基本定理',76);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('a14277eb-f2f1-5b76-b05f-0792da634623',0,'第一次求导得 $F''=2(4x^2+1)-2x(x^4+1)$。再求导得 $F''''=16x-[2(x^4+1)+8x^4]$。代入 $x=1$ 得 $16-12=4$。
INSERT INTO question_point (revision_id,point_id) VALUES ('a14277eb-f2f1-5b76-b05f-0792da634623','d64b25c2-836c-5b28-8c5c-b8267802619e');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('6413cad0-3ffa-5676-bdb9-5c8d7dbf166b','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-36-06','01ac50205753347aa18e69e13b000c5558eb9d288c70a2e681e8072bdff50807','00023-P1-36-06','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('092f9422-d319-5d2b-99c1-be281321c9c8','1bc86e3e-2bed-580c-b005-ec4ef354da9b','6413cad0-3ffa-5676-bdb9-5c8d7dbf166b','设 $g(x)=\\int_0^x(2t+1)dt$，$H(x)=\\int_0^{g(x)}(1+u^2)du$，则 $H''''(1)=$','["$36$","$46$","$22$","$10$"]',3,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-36 微积分基本定理',77);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('092f9422-d319-5d2b-99c1-be281321c9c8',1,'有 $g=x^2+x$、$g''=2x+1$、$g''''=2$。由基本定理及链式法则，$H''=(1+g^2)g''$，故 $H''''=2g(g'')^2+(1+g^2)g''''$。在 $x=1$ 处，$g=2,g''=3$，得 $H''''(1)=2\\cdot2\\cdot9+5\\cdot2=46$。
INSERT INTO question_point (revision_id,point_id) VALUES ('092f9422-d319-5d2b-99c1-be281321c9c8','d64b25c2-836c-5b28-8c5c-b8267802619e');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('18509b2a-5f7c-5d7f-937a-89b9aac8351a','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-37-01','a5873de4c75515f1542b798791bd16bac9b42c11dde7811e866af237c9ba8000','00023-P1-37-01','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('3e28cc85-443a-5d94-a685-56f9e3c5f422','1bc86e3e-2bed-580c-b005-ec4ef354da9b','18509b2a-5f7c-5d7f-937a-89b9aac8351a','定积分 $\\int_0^1 6x(1+x^2)^2dx=$','["$8$","$\\\\frac73$","$7$","$14$"]',1,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-37 定积分的换元法和分部积分法',78);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('3e28cc85-443a-5d94-a685-56f9e3c5f422',2,'令 $u=1+x^2$，则 $du=2x\\,dx$，上下限由 $0,1$ 变为 $1,2$。原式为 $3\\int_1^2u^2du=[u^3]_1^2=7$。
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('a72f1ad3-a7bd-5350-9732-a9c61f15c02f','1da6de03-1c89-524f-824a-35bc7bb191ca','P1-37 定积分的换元法和分部积分法','P1-37 定积分的换元法和分部积分法');
INSERT INTO release_point (release_id,chapter_id,point_id,title_snapshot) VALUES ('1bc86e3e-2bed-580c-b005-ec4ef354da9b','1da6de03-1c89-524f-824a-35bc7bb191ca','a72f1ad3-a7bd-5350-9732-a9c61f15c02f','P1-37 定积分的换元法和分部积分法');
INSERT INTO question_point (revision_id,point_id) VALUES ('3e28cc85-443a-5d94-a685-56f9e3c5f422','a72f1ad3-a7bd-5350-9732-a9c61f15c02f');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('f92aae47-b750-5685-8eaa-f8db849c11e2','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-37-02','bb2ebc2597e7bbb741e64e132c8e4aa848433286872a4ed65069e55ec2e2b64a','00023-P1-37-02','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('8a18cfbe-c9cc-5efa-a774-47d25ebc4526','1bc86e3e-2bed-580c-b005-ec4ef354da9b','f92aae47-b750-5685-8eaa-f8db849c11e2','定积分 $\\int_0^1xe^{2x}dx=$','["$\\\\frac{e^2-1}{4}$","$\\\\frac{e^2}{4}$","$\\\\frac{e^2+1}{2}$","$\\\\frac{e^2+1}{4}$"]',1,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-37 定积分的换元法和分部积分法',79);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('8a18cfbe-c9cc-5efa-a774-47d25ebc4526',3,'分部积分得原函数 $xe^{2x}/2-e^{2x}/4$。在 $1$ 处为 $e^2/4$，在 $0$ 处为 $-1/4$，相减得到 $(e^2+1)/4$。
INSERT INTO question_point (revision_id,point_id) VALUES ('8a18cfbe-c9cc-5efa-a774-47d25ebc4526','a72f1ad3-a7bd-5350-9732-a9c61f15c02f');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('308e60c7-39ac-58b9-9743-017d044ed892','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-37-03','7a69bdefb83232260749e4a1298fb814d97eebf6c951ece40c20ab7d208b562b','00023-P1-37-03','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('4890c71f-2acc-5a13-9eaa-e0c300ffe14f','1bc86e3e-2bed-580c-b005-ec4ef354da9b','308e60c7-39ac-58b9-9743-017d044ed892','定积分 $\\int_1^{e^2}\\frac{\\ln x}{x}dx=$','["$2$","$\\\\frac12$","$4$","$-2$"]',2,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-37 定积分的换元法和分部积分法',80);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('4890c71f-2acc-5a13-9eaa-e0c300ffe14f',0,'令 $u=\\ln x$，则 $du=dx/x$，下限变为 $0$、上限变为 $2$。原式为 $\\int_0^2u\\,du=[u^2/2]_0^2=2$。
INSERT INTO question_point (revision_id,point_id) VALUES ('4890c71f-2acc-5a13-9eaa-e0c300ffe14f','a72f1ad3-a7bd-5350-9732-a9c61f15c02f');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('91a97025-4d3b-5132-8ee5-d3d6133a9e82','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-37-04','23d382f5b8da3d144de5b647f1b310ee978ba6c9340cf8d239a1ba1757ff9684','00023-P1-37-04','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('0c06fae6-00ee-5047-9f5b-38716ce46c72','1bc86e3e-2bed-580c-b005-ec4ef354da9b','91a97025-4d3b-5132-8ee5-d3d6133a9e82','定积分 $\\int_0^1x\\ln(1+x)dx=$','["$\\\\frac{\\\\ln2}{2}$","$\\\\frac14$","$\\\\ln2-\\\\frac14$","$\\\\frac{\\\\ln2}{2}+\\\\frac14$"]',2,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-37 定积分的换元法和分部积分法',81);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('0c06fae6-00ee-5047-9f5b-38716ce46c72',1,'分部积分得 $I=[\\frac{x^2}{2}\\ln(1+x)]_0^1-\\frac12\\int_0^1\\frac{x^2}{1+x}dx$。用 $x^2/(1+x)=x-1+1/(1+x)$，余下积分为 $-1/2+\\ln2$，所以 $I=\\ln2/2-(-1/2+\\ln2)/2=1/4$。
INSERT INTO question_point (revision_id,point_id) VALUES ('0c06fae6-00ee-5047-9f5b-38716ce46c72','a72f1ad3-a7bd-5350-9732-a9c61f15c02f');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('8626284c-3ac0-5a59-8ecc-472ddbcda3de','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-37-05','d82abdc32f9adf7bb52732cbe7f541b0bd8d92f001f239851932946bc9e205f6','00023-P1-37-05','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('c54fa219-9e1b-5932-a484-35d5da45e6ce','1bc86e3e-2bed-580c-b005-ec4ef354da9b','8626284c-3ac0-5a59-8ecc-472ddbcda3de','定积分 $\\int_0^1\\frac{2x\\ln(1+x^2)}{(1+x^2)^2}dx=$','["$\\\\frac{1+\\\\ln2}{2}$","$-\\\\frac{\\\\ln2}{2}$","$\\\\frac{1-\\\\ln2}{2}$","$1-\\\\ln2$"]',3,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-37 定积分的换元法和分部积分法',82);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('c54fa219-9e1b-5932-a484-35d5da45e6ce',2,'先令 $u=1+x^2$，得 $\\int_1^2(\\ln u)/u^2\\,du$。再分部积分，取 $v=-1/u$，结果为 $[-\\ln u/u]_1^2+\\int_1^2u^{-2}du=-\\ln2/2+1/2=(1-\\ln2)/2$。
INSERT INTO question_point (revision_id,point_id) VALUES ('c54fa219-9e1b-5932-a484-35d5da45e6ce','a72f1ad3-a7bd-5350-9732-a9c61f15c02f');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('9b761eee-17a2-5a00-92f2-027b4cd098c3','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-37-06','b1a04e813bde589826a333f8c9826cc8400c1e26026687caa1be7748b770c0a2','00023-P1-37-06','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('56719dd1-f99d-5368-915e-9927f407bea0','1bc86e3e-2bed-580c-b005-ec4ef354da9b','9b761eee-17a2-5a00-92f2-027b4cd098c3','定积分 $\\int_0^{\\pi/2}x^2\\sin2x\\,dx=$','["$\\\\frac{\\\\pi^2}{8}$","$\\\\frac{\\\\pi^2+4}{8}$","$\\\\frac{\\\\pi^2-4}{4}$","$\\\\frac{\\\\pi^2-4}{8}$"]',3,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-37 定积分的换元法和分部积分法',83);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('56719dd1-f99d-5368-915e-9927f407bea0',3,'第一次分部积分得 $I=[-\\frac{x^2}{2}\\cos2x]_0^{\\pi/2}+\\int_0^{\\pi/2}x\\cos2x\\,dx$。边界项为 $\\pi^2/8$。余项再分部积分，其原函数为 $x\\sin2x/2+\\cos2x/4$，端点相减为 $-1/2$。故 $I=(\\pi^2-4)/8$。
INSERT INTO question_point (revision_id,point_id) VALUES ('56719dd1-f99d-5368-915e-9927f407bea0','a72f1ad3-a7bd-5350-9732-a9c61f15c02f');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('f4a2fcd6-17b2-5947-a1c5-a850c56430a6','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-38-01','48b1c39c26a646b62e4762a5cc73dfcb32e3ee40f696d88feb5b7a65eeca419f','00023-P1-38-01','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('2e19d883-b5f4-54d6-8437-e6d27c1e9ae4','1bc86e3e-2bed-580c-b005-ec4ef354da9b','f4a2fcd6-17b2-5947-a1c5-a850c56430a6','反常积分 $\\int_1^{+\\infty}\\frac{dx}{x^3}$ 的结果为','["$\\\\frac12$","$1$","$-\\\\frac12$","发散"]',1,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-38 反常积分',84);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('2e19d883-b5f4-54d6-8437-e6d27c1e9ae4',0,'按定义取上限 $R$，有 $\\int_1^R x^{-3}dx=[-1/(2x^2)]_1^R=1/2-1/(2R^2)$。令 $R\\to+\\infty$，得积分收敛且等于 $1/2$。
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('31ee17a8-2018-547a-ac6b-759c03b9fd23','1da6de03-1c89-524f-824a-35bc7bb191ca','P1-38 反常积分','P1-38 反常积分');
INSERT INTO release_point (release_id,chapter_id,point_id,title_snapshot) VALUES ('1bc86e3e-2bed-580c-b005-ec4ef354da9b','1da6de03-1c89-524f-824a-35bc7bb191ca','31ee17a8-2018-547a-ac6b-759c03b9fd23','P1-38 反常积分');
INSERT INTO question_point (revision_id,point_id) VALUES ('2e19d883-b5f4-54d6-8437-e6d27c1e9ae4','31ee17a8-2018-547a-ac6b-759c03b9fd23');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('797336a9-496d-5f7b-b3f2-23e470f0581c','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-38-02','7d0f7f1ba483385b66e108c5a9cecc98d6001c9b171e28faf8031f17a87a02b4','00023-P1-38-02','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('1a2054eb-3f35-5dd6-9b46-1daa443fb4c0','1bc86e3e-2bed-580c-b005-ec4ef354da9b','797336a9-496d-5f7b-b3f2-23e470f0581c','反常积分 $\\int_0^1\\frac{dx}{\\sqrt x}$ 的结果为','["$1$","$2$","$\\\\frac12$","发散"]',1,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-38 反常积分',85);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('1a2054eb-3f35-5dd6-9b46-1daa443fb4c0',1,'以 $\\varepsilon>0$ 代替下限，$\\int_\\varepsilon^1x^{-1/2}dx=[2\\sqrt x]_\\varepsilon^1=2-2\\sqrt\\varepsilon$。令 $\\varepsilon\\to0^+$，得积分收敛且等于 $2$。
INSERT INTO question_point (revision_id,point_id) VALUES ('1a2054eb-3f35-5dd6-9b46-1daa443fb4c0','31ee17a8-2018-547a-ac6b-759c03b9fd23');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('51cff1af-1624-5329-b497-548774017683','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-38-03','b33f803d61a7ea23729362aa5d10c84b25f105dea09a5b3583ff4bfa838d3244','00023-P1-38-03','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('6ac09149-7b37-5e67-9562-1ea73dd85e4b','1bc86e3e-2bed-580c-b005-ec4ef354da9b','51cff1af-1624-5329-b497-548774017683','设 $p$ 为实数。反常积分 $\\int_0^{+\\infty}\\frac{dx}{x^p(1+x)}$ 收敛的充要条件是','["$p>0$","$p<1$","$0<p<1$","$0\\\\le p\\\\le1$"]',2,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-38 反常积分',86);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('6ac09149-7b37-5e67-9562-1ea73dd85e4b',2,'在 $x\\to0^+$ 时，被积函数与 $x^{-p}$ 等价，零端收敛要求 $p<1$；在 $x\\to+\\infty$ 时，与 $x^{-(p+1)}$ 等价，无穷端收敛要求 $p+1>1$，即 $p>0$。两条件取交集得到 $0<p<1$。
INSERT INTO question_point (revision_id,point_id) VALUES ('6ac09149-7b37-5e67-9562-1ea73dd85e4b','31ee17a8-2018-547a-ac6b-759c03b9fd23');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('8102aacd-983d-5073-bd06-a8eabab7946a','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-38-04','3cb2953da12972c7c51fe505fad498e50f86c42dff424b7b756d7bc17c513309','00023-P1-38-04','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('622bb0c9-bacb-5fa1-b89b-c5b99e6d4c3a','1bc86e3e-2bed-580c-b005-ec4ef354da9b','8102aacd-983d-5073-bd06-a8eabab7946a','反常积分 $\\int_{-1}^1\\frac{dx}{x^2}$ 的结果为','["$2$","$-2$","$0$","发散至 $+\\\\infty$"]',2,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-38 反常积分',87);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('622bb0c9-bacb-5fa1-b89b-c5b99e6d4c3a',3,'内部奇点为 $x=0$，必须拆为两侧积分。右侧 $\\int_\\varepsilon^1x^{-2}dx=1/\\varepsilon-1\\to+\\infty$，左侧同样发散，因此原积分发散至 $+\\infty$。
INSERT INTO question_point (revision_id,point_id) VALUES ('622bb0c9-bacb-5fa1-b89b-c5b99e6d4c3a','31ee17a8-2018-547a-ac6b-759c03b9fd23');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('67c01620-0d84-546a-b19e-2c4af54e653c','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-38-05','1cf7b6517c7e7b7aa596597b802c166697f04d2df0794de81f4adaed65a83ce6','00023-P1-38-05','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('19f0843e-449f-5b03-98ec-a33899e89b7d','1bc86e3e-2bed-580c-b005-ec4ef354da9b','67c01620-0d84-546a-b19e-2c4af54e653c','反常积分 $\\int_0^{+\\infty}\\frac{x}{(x+1)(x+2)(x+3)}dx=$','["$\\\\frac12\\\\ln\\\\frac{27}{16}$","$\\\\frac12\\\\ln\\\\frac{16}{27}$","$\\\\frac32\\\\ln3$","发散"]',3,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-38 反常积分',88);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('19f0843e-449f-5b03-98ec-a33899e89b7d',0,'部分分式分解为 $-\\frac1{2(x+1)}+\\frac2{x+2}-\\frac3{2(x+3)}$。取统一上限 $R$ 后积分，原函数为 $Q=-\\frac12\\ln(x+1)+2\\ln(x+2)-\\frac32\\ln(x+3)$。因对数系数之和为零，$Q(R)\\to0$；又 $Q(0)=2\\ln2-\\frac32\\ln3$，故结果为 $\\frac32\\ln3-2\\ln2=\\frac12\\ln(27/16)$。
INSERT INTO question_point (revision_id,point_id) VALUES ('19f0843e-449f-5b03-98ec-a33899e89b7d','31ee17a8-2018-547a-ac6b-759c03b9fd23');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('93ef21ac-c5bc-5076-a900-a47c709a0884','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-38-06','1da002e9d9d5a78196bc8eecd616976523ea38b1caa58172f3a65125481a564d','00023-P1-38-06','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('fe03541b-ce0d-5fc0-a01a-913661e658fd','1bc86e3e-2bed-580c-b005-ec4ef354da9b','93ef21ac-c5bc-5076-a900-a47c709a0884','设 $p$ 为实数，反常积分 $I(p)=\\int_0^1x^{p-1}dx+\\int_1^{+\\infty}x^{-2p-1}dx$ 收敛且 $I(p)=3$，则 $p=$','["$\\\\frac13$","$\\\\frac12$","$-\\\\frac12$","$2$"]',3,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-38 反常积分',89);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('fe03541b-ce0d-5fc0-a01a-913661e658fd',1,'零端积分收敛要求 $p>0$，无穷端积分也要求 $2p>0$。在 $p>0$ 时，两项分别为 $1/p$、$1/(2p)$，故 $I(p)=3/(2p)$。由 $3/(2p)=3$ 得 $p=1/2$，满足收敛条件。
INSERT INTO question_point (revision_id,point_id) VALUES ('fe03541b-ce0d-5fc0-a01a-913661e658fd','31ee17a8-2018-547a-ac6b-759c03b9fd23');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('e10b3283-4a29-5403-a985-2cc3c5eb1151','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-39-01','70dc7a9046b5b923bf5b8e540f728ee174e1ab9697ac8056fa2a42df2371b5fc','00023-P1-39-01','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('c5891f74-65e8-5047-9986-fbbe267f55ba','1bc86e3e-2bed-580c-b005-ec4ef354da9b','e10b3283-4a29-5403-a985-2cc3c5eb1151','曲线 $y=x^2$ 与直线 $y=2x$ 所围成图形的面积为','["$\\\\frac43$","$\\\\frac83$","$-\\\\frac43$","$2$"]',1,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-39 定积分的几何运用',90);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('c5891f74-65e8-5047-9986-fbbe267f55ba',0,'联立得交点横坐标为 $0,2$，该区间内直线在上、抛物线在下。面积为 $\\int_0^2(2x-x^2)dx=[x^2-x^3/3]_0^2=4/3$。
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('2426e084-e388-5eff-85de-3aeb2969d4cd','1da6de03-1c89-524f-824a-35bc7bb191ca','P1-39 定积分的几何运用','P1-39 定积分的几何运用');
INSERT INTO release_point (release_id,chapter_id,point_id,title_snapshot) VALUES ('1bc86e3e-2bed-580c-b005-ec4ef354da9b','1da6de03-1c89-524f-824a-35bc7bb191ca','2426e084-e388-5eff-85de-3aeb2969d4cd','P1-39 定积分的几何运用');
INSERT INTO question_point (revision_id,point_id) VALUES ('c5891f74-65e8-5047-9986-fbbe267f55ba','2426e084-e388-5eff-85de-3aeb2969d4cd');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('32616ca7-24bc-5430-983b-f92ccd423eb3','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-39-02','383c8fb62f1502863dbbbbf2092fac7eff82cc90ce9dffc205ac4e2ba00dfea3','00023-P1-39-02','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('f69f67cd-5409-59f7-82a9-2370712fb7b6','1bc86e3e-2bed-580c-b005-ec4ef354da9b','32616ca7-24bc-5430-983b-f92ccd423eb3','由曲线 $y=\\sqrt x$、横轴及直线 $x=0$、$x=4$ 围成的图形绕横轴旋转一周，所得旋转体体积为','["$16\\\\pi$","$8\\\\pi$","$\\\\frac{16\\\\pi}{3}$","$4\\\\pi$"]',1,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-39 定积分的几何运用',91);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('f69f67cd-5409-59f7-82a9-2370712fb7b6',1,'垂直于横轴的截面是半径为 $\\sqrt x$ 的圆盘，体积为 $\\pi\\int_0^4(\\sqrt x)^2dx=\\pi[x^2/2]_0^4=8\\pi$。
INSERT INTO question_point (revision_id,point_id) VALUES ('f69f67cd-5409-59f7-82a9-2370712fb7b6','2426e084-e388-5eff-85de-3aeb2969d4cd');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('4a8bd90a-6996-5428-a635-0895fa849037','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-39-03','5c6d11249034393bf7b860e78cfb7cc1156101ce6e622e3c2adb6a2749970088','00023-P1-39-03','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('5173606b-5296-55d5-943d-59b0fdf31b65','1bc86e3e-2bed-580c-b005-ec4ef354da9b','4a8bd90a-6996-5428-a635-0895fa849037','曲线 $y=x$ 与 $y=x^2$ 所围成的图形绕纵轴旋转一周，所得旋转体体积为','["$\\\\frac{\\\\pi}{12}$","$\\\\frac{\\\\pi}{2}$","$\\\\frac{\\\\pi}{6}$","$-\\\\frac{\\\\pi}{6}$"]',2,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-39 定积分的几何运用',92);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('5173606b-5296-55d5-943d-59b0fdf31b65',2,'交点为 $(0,0)$、$(1,1)$。按 $y$ 积分时，右边界为 $x=\\sqrt y$、左边界为 $x=y$，圆环外半径为 $\\sqrt y$、内半径为 $y$。体积为 $\\pi\\int_0^1(y-y^2)dy=\\pi(1/2-1/3)=\\pi/6$。
INSERT INTO question_point (revision_id,point_id) VALUES ('5173606b-5296-55d5-943d-59b0fdf31b65','2426e084-e388-5eff-85de-3aeb2969d4cd');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('3e0a80c3-8e9c-5628-83fd-f19ea76486a3','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-39-04','d10e268e892a4ff3ca35fbfa9a1c809115fb9afd399581eaf3cb9882f072c732','00023-P1-39-04','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('6fd86568-1877-5fa9-a63a-614e3e9043cb','1bc86e3e-2bed-580c-b005-ec4ef354da9b','3e0a80c3-8e9c-5628-83fd-f19ea76486a3','由曲线 $y=x^2$、横轴及直线 $x=1$、$x=2$ 围成的图形绕直线 $y=-1$ 旋转一周，所得体积为','["$\\\\frac{178\\\\pi}{15}$","$\\\\frac{31\\\\pi}{5}$","$\\\\frac{128\\\\pi}{15}$","$\\\\frac{163\\\\pi}{15}$"]',2,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-39 定积分的几何运用',93);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('6fd86568-1877-5fa9-a63a-614e3e9043cb',3,'外半径为 $x^2+1$，内半径为 $1$。体积为 $\\pi\\int_1^2[(x^2+1)^2-1]dx=\\pi\\int_1^2(x^4+2x^2)dx=\\pi(31/5+14/3)=163\\pi/15$。
INSERT INTO question_point (revision_id,point_id) VALUES ('6fd86568-1877-5fa9-a63a-614e3e9043cb','2426e084-e388-5eff-85de-3aeb2969d4cd');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('b01eba97-b2f2-5abd-b933-93558734d636','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-39-05','516f38ed2441329e9348817ecff8dacf1b4c3aaef3c5c0de970e3575e52257de','00023-P1-39-05','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('f816a60a-fb66-5c65-8d26-c9210ff80d9b','1bc86e3e-2bed-580c-b005-ec4ef354da9b','b01eba97-b2f2-5abd-b933-93558734d636','由直线 $y=x$、$y=2$ 和 $x=0$ 围成的三角形绕直线 $y=1$ 旋转一周，所得体积为','["$\\\\frac{5\\\\pi}{3}$","$\\\\frac{4\\\\pi}{3}$","$2\\\\pi$","$\\\\frac{16\\\\pi}{3}$"]',3,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-39 定积分的几何运用',94);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('f816a60a-fb66-5c65-8d26-c9210ff80d9b',0,'横坐标范围为 $[0,2]$。在 $0\\le x\\le1$ 时，截线跨过旋转轴，旋转后为半径 $1$ 的圆盘；在 $1<x\\le2$ 时，为外半径 $1$、内半径 $x-1$ 的圆环。故体积为 $\\pi\\int_0^1 1dx+\\pi\\int_1^2[1-(x-1)^2]dx=\\pi+2\\pi/3=5\\pi/3$。
INSERT INTO question_point (revision_id,point_id) VALUES ('f816a60a-fb66-5c65-8d26-c9210ff80d9b','2426e084-e388-5eff-85de-3aeb2969d4cd');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('96d0ee99-54b7-5722-9305-973b3ba5fa21','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-39-06','9002f03f287bc6f85aadb261c0710325e52b4eb2289d3c49e097948bd36cc285','00023-P1-39-06','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('5cfc1c46-75cb-5ec4-9173-9b2569a0087c','1bc86e3e-2bed-580c-b005-ec4ef354da9b','96d0ee99-54b7-5722-9305-973b3ba5fa21','由曲线 $y=2x-x^2$ 与横轴围成的图形绕直线 $x=3$ 旋转一周，所得体积为','["$\\\\frac{8\\\\pi}{3}$","$\\\\frac{16\\\\pi}{3}$","$8\\\\pi$","$-\\\\frac{16\\\\pi}{3}$"]',3,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-39 定积分的几何运用',95);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('5cfc1c46-75cb-5ec4-9173-9b2569a0087c',1,'图形横坐标范围为 $[0,2]$。取竖向薄条，圆柱壳半径为 $3-x$、高度为 $2x-x^2$。体积为 $2\\pi\\int_0^2(3-x)(2x-x^2)dx=2\\pi\\int_0^2(6x-5x^2+x^3)dx=2\\pi(12-40/3+4)=16\\pi/3$。
INSERT INTO question_point (revision_id,point_id) VALUES ('5cfc1c46-75cb-5ec4-9173-9b2569a0087c','2426e084-e388-5eff-85de-3aeb2969d4cd');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('f52a4797-a3c7-5a32-9d34-4042eace4a8f','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-40-01','d646f6410cb2dda02ea9b76a8a2dbcdac5ebe8b2d332fdf33ee16e890f6ad9e2','00023-P1-40-01','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('20d0a69d-e808-5aea-93be-41f1913d3d02','1bc86e3e-2bed-580c-b005-ec4ef354da9b','f52a4797-a3c7-5a32-9d34-4042eace4a8f','二阶行列式 $\\begin{vmatrix}3&-2\\\\1&4\\end{vmatrix}=$','["$10$","$12$","$14$","$-14$"]',1,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-40 二、三阶行列式',96);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('20d0a69d-e808-5aea-93be-41f1913d3d02',2,'由二阶行列式公式，结果为 $3\\cdot4-(-2)\\cdot1=12+2=14$。
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('211b679d-efa6-53ff-89de-ddd815424681','1da6de03-1c89-524f-824a-35bc7bb191ca','P1-40 二、三阶行列式','P1-40 二、三阶行列式');
INSERT INTO release_point (release_id,chapter_id,point_id,title_snapshot) VALUES ('1bc86e3e-2bed-580c-b005-ec4ef354da9b','1da6de03-1c89-524f-824a-35bc7bb191ca','211b679d-efa6-53ff-89de-ddd815424681','P1-40 二、三阶行列式');
