INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('7ec82b23-f788-54a9-b87b-3032826f3bd2','1bc86e3e-2bed-580c-b005-ec4ef354da9b','f81ef02f-ec64-56c2-8638-63c538e64774','三阶行列式 $\\begin{vmatrix}2&1&-1\\\\0&-3&2\\\\0&0&4\\end{vmatrix}=$','["$3$","$24$","$0$","$-24$"]',1,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-40 二、三阶行列式',97);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('7ec82b23-f788-54a9-b87b-3032826f3bd2',3,'这是上三角行列式，值为主对角线元素的乘积：$2\\cdot(-3)\\cdot4=-24$。
INSERT INTO question_point (revision_id,point_id) VALUES ('7ec82b23-f788-54a9-b87b-3032826f3bd2','211b679d-efa6-53ff-89de-ddd815424681');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('89441961-f2fe-55e1-a429-38d4ba1d1661','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-40-03','92ff67cd0b76633a89645bdf7e6a3b63b2ea089458503120fb222b54a09b6468','00023-P1-40-03','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('cfb5177e-35ce-518a-aba6-97bad70ab240','1bc86e3e-2bed-580c-b005-ec4ef354da9b','89441961-f2fe-55e1-a429-38d4ba1d1661','三阶行列式 $\\begin{vmatrix}1&2&0\\\\2&1&3\\\\0&-1&2\\end{vmatrix}=$','["$-3$","$13$","$-9$","$1$"]',2,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-40 二、三阶行列式',98);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('cfb5177e-35ce-518a-aba6-97bad70ab240',0,'按第一行展开：$1[1\\cdot2-3(-1)]-2[2\\cdot2-3\\cdot0]=5-8=-3$。
