INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('436f8fbf-16c0-5c36-b2a0-c2f371ff814e','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-40-04','07bf23fb8955f1bf7b367da56c0af8a90d2496157d00547d5b7b5df5e1dd5b3d','00023-P1-40-04','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('bf43df22-36a3-55af-873a-8332dcaa5d16','1bc86e3e-2bed-580c-b005-ec4ef354da9b','436f8fbf-16c0-5c36-b2a0-c2f371ff814e','使行列式 $\\begin{vmatrix}a&1&1\\\\1&a&1\\\\1&1&a\\end{vmatrix}$ 等于零的全部实数 $a$ 为','["$a=1$","$a=1$ 或 $a=-2$","$a=1$ 或 $a=-1$","$a=-2$"]',2,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-40 二、三阶行列式',99);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('bf43df22-36a3-55af-873a-8332dcaa5d16',1,'展开行列式得 $a^3-3a+2$，分解为 $(a-1)^2(a+2)$。因此全部实数解为 $a=1$ 或 $a=-2$。
INSERT INTO question_point (revision_id,point_id) VALUES ('bf43df22-36a3-55af-873a-8332dcaa5d16','211b679d-efa6-53ff-89de-ddd815424681');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('41ed1a24-e5b6-518c-9287-78386678b16c','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-40-05','97ccf781d6fd0d8f64d770ae5827b0ca32e67dd766eaab5406355f5c51bd669a','00023-P1-40-05','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('10d056e3-21aa-53b6-811e-a3687f97be6f','1bc86e3e-2bed-580c-b005-ec4ef354da9b','41ed1a24-e5b6-518c-9287-78386678b16c','设 $a>0$，且 $\\begin{vmatrix}1&1&1\\\\1&a&2\\\\1&2&a\\end{vmatrix}=3$，则 $\\begin{vmatrix}a&2&0\\\\1&a&1\\\\0&1&a\\end{vmatrix}=$','["$0$","$2$","$18$","$24$"]',3,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-40 二、三阶行列式',100);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('10d056e3-21aa-53b6-811e-a3687f97be6f',2,'将第一个行列式的第二、三行分别减去第一行，得 $(a-1)^2-1=a(a-2)$。由 $a(a-2)=3$ 得 $a=3$ 或 $a=-1$，结合 $a>0$ 取 $a=3$。第二个行列式为 $a(a^2-1)-2a=a^3-3a$，代入得 $18$。
INSERT INTO question_point (revision_id,point_id) VALUES ('10d056e3-21aa-53b6-811e-a3687f97be6f','211b679d-efa6-53ff-89de-ddd815424681');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('0ff0e934-2880-56b1-abb9-5031f9c14212','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:00023-P1-40-06','aa085f58d6c80f91b79fea3dd88cad45bbf48582ad3ef8be975a4252c28c0521','00023-P1-40-06','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('7100f38a-3db8-5ae4-97cd-627a70d259ea','1bc86e3e-2bed-580c-b005-ec4ef354da9b','0ff0e934-2880-56b1-abb9-5031f9c14212','设实数 $k$ 满足 $\\begin{vmatrix}1&2&3\\\\2&5&8\\\\3&8&k\\end{vmatrix}=2$，则 $\\begin{vmatrix}k&1&2\\\\1&2&0\\\\2&0&1\\end{vmatrix}=$','["$13$","$17$","$37$","$21$"]',3,'工专基础补充 · 第 24–40 集 · 原创章节刷题 · P1-40 二、三阶行列式',101);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('7100f38a-3db8-5ae4-97cd-627a70d259ea',3,'第一个行列式作 $R_2\\leftarrow R_2-2R_1$、$R_3\\leftarrow R_3-3R_1$，化为 $\\begin{vmatrix}1&2&3\\\\0&1&2\\\\0&2&k-9\\end{vmatrix}=k-13$。因此 $k=15$。第二个行列式按第一行展开得 $2k-1-8=2k-9=21$。
INSERT INTO question_point (revision_id,point_id) VALUES ('7100f38a-3db8-5ae4-97cd-627a70d259ea','211b679d-efa6-53ff-89de-ddd815424681');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('753d430f-dfc0-5fd5-8211-f167df8c58b9','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-double-fifth-20261001-foundation-p24-1','fc62376833289805ce4f41b83218ab20da3eb1dd36684ac112fca25a76797e34','calculus-double-fifth-20261001-foundation-p24-1','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('079dbfc8-8de9-527e-8e9c-c764aa3b3579','1bc86e3e-2bed-580c-b005-ec4ef354da9b','753d430f-dfc0-5fd5-8211-f167df8c58b9','y=x e^(2x)，则y′为','["xe^(2x)","(1+x)e^(2x)","(1+2x)e^(2x)","2e^(2x)"]',3,'目录专项 · 真题难度新题 · 导数的运算',102);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('079dbfc8-8de9-527e-8e9c-c764aa3b3579',2,'乘积求导为e^(2x)+2xe^(2x)。');
