INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('6a3b83ea-9ce8-5833-bfd7-f164ff29e767','1bc86e3e-2bed-580c-b005-ec4ef354da9b','f1cad878-95c4-570c-ab4d-6a1efcce92b5','若f(x)=|x-2|，则在x=2处','["可导且导数1","不可导但连续","可导且导数0","不连续"]',3,'目录专项 · 真题难度新题 · 一元导数基础知识',355);
