INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('6e5ba269-398f-52a6-bb21-036ff98ae344','afdac469-0fe4-5007-833c-51a71333967b','32ec87c0-2e8e-5a8e-b45f-8bcf5ac63f59','legacy:00023:calculus-double-second-20260930-exam-2-2-1','f0cade902238616d7b3f736f71c7e98f764947fe7013c1fa7149b40bae0e319a','calculus-double-second-20260930-exam-2-2-1','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('c0c9d0a8-3d7f-5cbc-8d7e-87b0e9a6d744','1bc86e3e-2bed-580c-b005-ec4ef354da9b','6e5ba269-398f-52a6-bb21-036ff98ae344','函数 z=√(4−x²−y²) 的定义域是','["x²+y²≥4","所有实数对","x²+y²≤4","x²+y²<4"]',3,'目录专项 · 真题难度新题 · 二元函数的构造',698);
