INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('52052fa9-02c6-54bd-857b-8fdea5df65c2','afdac469-0fe4-5007-833c-51a71333967b','32ec87c0-2e8e-5a8e-b45f-8bcf5ac63f59','legacy:00023:calculus-double-second-20260930-exam-2-4-2','092cf5288ddd939c209198a214587e0a313db48d763b2d6f9a370f0eafd640f8','calculus-double-second-20260930-exam-2-4-2','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('0c6c708d-7bfd-51bd-8463-05a46ac01c13','1bc86e3e-2bed-580c-b005-ec4ef354da9b','52052fa9-02c6-54bd-857b-8fdea5df65c2','f(x)=e^(−2x)，则 f′(0)=','["−1","1","2","−2"]',3,'目录专项 · 真题难度新题 · 一元导数基础知识',703);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('0c6c708d-7bfd-51bd-8463-05a46ac01c13',3,'链式法则得 f′=-2e^(-2x)，代入 0 为 -2。');
