INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('9d0d2103-007d-590a-8a57-eda29d861a75','1bc86e3e-2bed-580c-b005-ec4ef354da9b','f11aec87-73d0-5125-98d0-b0d9876cbdb9','z=x²y+xy³，则 zₓ(1,2)=','["8","10","12","14"]',3,'目录专项 · 真题难度新题 · 显函数求偏导',704);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('9d0d2103-007d-590a-8a57-eda29d861a75',2,'zₓ=2xy+y³，代入为 4+8=12。');
