INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('a25564a1-d9f4-5b6b-9ce8-21045da6fb95','afdac469-0fe4-5007-833c-51a71333967b','32ec87c0-2e8e-5a8e-b45f-8bcf5ac63f59','legacy:00023:calculus-double-second-20260930-exam-2-6-1','c80577dd209ded14c552cfa5e35ff9817441e0b2e904c02aa1f6f8ef7d8e173f','calculus-double-second-20260930-exam-2-6-1','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('3631595d-3332-5fb3-a55d-e0b47f9ae98c','1bc86e3e-2bed-580c-b005-ec4ef354da9b','a25564a1-d9f4-5b6b-9ce8-21045da6fb95','若 F(x,y,z)=x²+y²+z²−9=0，z 为 x,y 的函数，则 zₓ 在 (1,2,2) 处为','["1/2","1","−1/2","−1"]',4,'目录专项 · 真题难度新题 · 隐函数求偏导之公式法',706);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('3631595d-3332-5fb3-a55d-e0b47f9ae98c',2,'zₓ=-Fₓ/F_z=-x/z，在该点为 -1/2。');
