INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('b1e13db7-ed00-53b8-aa4f-4fddc2fa0952','afdac469-0fe4-5007-833c-51a71333967b','32ec87c0-2e8e-5a8e-b45f-8bcf5ac63f59','legacy:00023:calculus-double-second-20260930-exam-2-6-2','6d161ba8e5ac8d4fe0987b4e46302a9a82da1b785df3972ec37f667d1e6f6e75','calculus-double-second-20260930-exam-2-6-2','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('0a07471a-00f5-501c-b61d-b89b3f1b4cb9','1bc86e3e-2bed-580c-b005-ec4ef354da9b','b1e13db7-ed00-53b8-aa4f-4fddc2fa0952','由 x+y+z+xyz=4 确定 z(x,y)，则 zᵧ 在 (1,1,1) 为','["0","1","2","−1"]',4,'目录专项 · 真题难度新题 · 隐函数求偏导之公式法',707);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('0a07471a-00f5-501c-b61d-b89b3f1b4cb9',3,'Fᵧ=1+xz=2，F_z=1+xy=2，故 zᵧ=-1。');
