INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('ffb59ffd-cdf6-54a1-9bae-9359d2115de6','afdac469-0fe4-5007-833c-51a71333967b','32ec87c0-2e8e-5a8e-b45f-8bcf5ac63f59','legacy:00023:calculus-double-second-20260930-exam-2-7-1','5a399dcb0a4a8369c692639ecbed962c1bab396539f002b6eef35f8296e87b99','calculus-double-second-20260930-exam-2-7-1','CHAPTER',0);
