INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('9aa7df37-8cf3-53dd-af1c-f4f1bfed0f1c',0,'复合求导 2zzₓ+y=0，故 zₓ=-y/(2z)=-1/4。');
