INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('b565c38a-af1f-502e-8511-37cd2f9ffbf3','1bc86e3e-2bed-580c-b005-ec4ef354da9b','ca623102-c287-5a64-8a27-89d5813ba119','方程 e^z+x²+y²=2 在 (0,1,0) 处确定 z(x,y)，则 zᵧ=','["2","−2","−1","1"]',4,'目录专项 · 真题难度新题 · 隐函数求偏导之复合法',709);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('b565c38a-af1f-502e-8511-37cd2f9ffbf3',1,'链式求导 e^z zᵧ+2y=0，该点 zᵧ=-2。');
