INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('eaeccccf-6492-5691-a568-28dfe6790056','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-double-20260930-foundation-p24-1','8594292b9d8564b6e38d157146f05855a20e48cf70093cf138c1b53fbd6345ed','calculus-double-20260930-foundation-p24-1','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('d6360547-ad27-5652-925d-c2cdbe0b586a','1bc86e3e-2bed-580c-b005-ec4ef354da9b','eaeccccf-6492-5691-a568-28dfe6790056','设 f(x)=x²sin x，则 f′(π)=','["-π²","0","π²","-2π"]',3,'目录专项 · 真题难度新题 · 导数的运算',798);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('d6360547-ad27-5652-925d-c2cdbe0b586a',0,'用乘积法则得 f′=2xsin x+x²cos x，代入 π 得 -π²。');
INSERT INTO question_point (revision_id,point_id) VALUES ('d6360547-ad27-5652-925d-c2cdbe0b586a','ba6767ba-f756-53a6-a602-9262156b904b');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('3a307bed-9bfd-53ec-a509-10abeaa5ef46','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-double-20260930-foundation-p24-2','cc39717c3d089ef3a8c04975278f76b49f8c0f6b09ca54cd7ab8264de5d122c9','calculus-double-20260930-foundation-p24-2','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('7f3f6bee-15e5-5986-9b4d-e68ba86e5612','1bc86e3e-2bed-580c-b005-ec4ef354da9b','3a307bed-9bfd-53ec-a509-10abeaa5ef46','设 f(x)=(x²+1)/(x-1)，则 f′(2)=','["-2","-1","1","3"]',4,'目录专项 · 真题难度新题 · 导数的运算',799);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('7f3f6bee-15e5-5986-9b4d-e68ba86e5612',1,'商法则给出 f′=[2x(x-1)-(x²+1)]/(x-1)²，代入 2 得 -1。');
INSERT INTO question_point (revision_id,point_id) VALUES ('7f3f6bee-15e5-5986-9b4d-e68ba86e5612','ba6767ba-f756-53a6-a602-9262156b904b');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('5c46468f-ee1b-5a43-80b7-81843c4df297','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-double-20260930-foundation-p25-1','2846a31c012c58c0d59e007cd30d9f1f4836c843b1a7784088f9a641061c425a','calculus-double-20260930-foundation-p25-1','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('64c178bb-2f1d-5e39-9725-9e9174c0efc9','1bc86e3e-2bed-580c-b005-ec4ef354da9b','5c46468f-ee1b-5a43-80b7-81843c4df297','设 y=arctan(2x)，则 y′ 在 x=1 处等于','["1/5","2/5","1/2","2"]',3,'目录专项 · 真题难度新题 · 三类特殊函授求导',800);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('64c178bb-2f1d-5e39-9725-9e9174c0efc9',1,'链式法则得 y′=2/(1+4x²)，代入 x=1 得 2/5。');
INSERT INTO question_point (revision_id,point_id) VALUES ('64c178bb-2f1d-5e39-9725-9e9174c0efc9','d55c0c4e-16c0-5f82-a8b1-2e802079cbb4');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('fe92156e-6f3a-558a-aac1-2528e0ba2081','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-double-20260930-foundation-p25-2','37fed7125529fac093537f2bff9c33680e73ad771e4234550e527a820576f4d8','calculus-double-20260930-foundation-p25-2','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('a3e974b7-be82-5bed-a541-4d718d3d5323','1bc86e3e-2bed-580c-b005-ec4ef354da9b','fe92156e-6f3a-558a-aac1-2528e0ba2081','设 y=ln(cos x)，0<x<π/2，则 y′=','["tan x","-tan x","cot x","-cot x"]',3,'目录专项 · 真题难度新题 · 三类特殊函授求导',801);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('a3e974b7-be82-5bed-a541-4d718d3d5323',1,'对数求导后为 (cos x)′/cos x=-sin x/cos x=-tan x。');
INSERT INTO question_point (revision_id,point_id) VALUES ('a3e974b7-be82-5bed-a541-4d718d3d5323','d55c0c4e-16c0-5f82-a8b1-2e802079cbb4');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('f2a5ca31-7685-593d-9a2b-e96754e87713','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-double-20260930-foundation-p26-1','18f9a3bb7830c08190845d1c4afd8baddc28a2f790dd72e5087f116736b14437','calculus-double-20260930-foundation-p26-1','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('2bceff1e-3ca3-567a-8305-39a56d0ef892','1bc86e3e-2bed-580c-b005-ec4ef354da9b','f2a5ca31-7685-593d-9a2b-e96754e87713','设 f(x)=x³eˣ，则 f″(0)=','["0","3","6","12"]',4,'目录专项 · 真题难度新题 · 高阶导数',802);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('2bceff1e-3ca3-567a-8305-39a56d0ef892',0,'两次求导得 f″=eˣ(x³+6x²+6x)，代入 0 为 0。');
INSERT INTO question_point (revision_id,point_id) VALUES ('2bceff1e-3ca3-567a-8305-39a56d0ef892','ed0aae71-bc31-5fdd-a8fa-5aabd03c1c37');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('7f67ac13-448a-5872-bc13-8685330cc9f8','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-double-20260930-foundation-p26-2','857bc2738ef5a7da4605ed9dcf467ac9e52e027034aba474bd5ad3ca7a0d9e50','calculus-double-20260930-foundation-p26-2','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('c6765c23-065e-5e8e-9766-df2da8339aca','1bc86e3e-2bed-580c-b005-ec4ef354da9b','7f67ac13-448a-5872-bc13-8685330cc9f8','设 f(x)=sin(2x)，则 f⁽⁴⁾(π/4)=','["-16","0","8","16"]',3,'目录专项 · 真题难度新题 · 高阶导数',803);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('c6765c23-065e-5e8e-9766-df2da8339aca',3,'每求导四次恢复原函数并乘 2⁴，故 f⁽⁴⁾(x)=16sin(2x)，代入 π/4 得 16。');
INSERT INTO question_point (revision_id,point_id) VALUES ('c6765c23-065e-5e8e-9766-df2da8339aca','ed0aae71-bc31-5fdd-a8fa-5aabd03c1c37');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('44ea6d44-95f2-5cb1-872f-b3454ba9eb37','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-double-20260930-foundation-p27-1','b1195521b66fe69b6110c8ea185e279facb6055dc602cdb57770c4594e323c1a','calculus-double-20260930-foundation-p27-1','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('15976b1a-77f3-552b-ad94-dae8a5761f17','1bc86e3e-2bed-580c-b005-ec4ef354da9b','44ea6d44-95f2-5cb1-872f-b3454ba9eb37','设 y=x²eˣ，则在 x=0 处的微分 dy 为','["0","dx","2dx","e·dx"]',3,'目录专项 · 真题难度新题 · 微分及其运算',804);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('15976b1a-77f3-552b-ad94-dae8a5761f17',0,'y′=eˣ(x²+2x)，在 0 处为 0，因此 dy=0。');
INSERT INTO question_point (revision_id,point_id) VALUES ('15976b1a-77f3-552b-ad94-dae8a5761f17','0e39226c-22ca-5b07-a316-66fbfa2e8782');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('65229ce9-721c-59b0-8745-aec3d89fe646','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-double-20260930-foundation-p27-2','aa6c3ded6457557f6c15c08af5d65e3749504edb7857944d9c5bed19aa631087','calculus-double-20260930-foundation-p27-2','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('23ee2dfd-a2a2-5fcc-a550-cd93b07c3e6e','1bc86e3e-2bed-580c-b005-ec4ef354da9b','65229ce9-721c-59b0-8745-aec3d89fe646','设 y=√(1+x²)，则在 x=1 处 dy=','["dx/√2","√2dx","dx/2","2dx"]',3,'目录专项 · 真题难度新题 · 微分及其运算',805);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('23ee2dfd-a2a2-5fcc-a550-cd93b07c3e6e',0,'y′=x/√(1+x²)，在 x=1 处为 1/√2。');
