INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('b4ee7b1e-d9c7-5567-b737-cac696eeb903','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-double-20260930-foundation-p28-1','7cbca782448a44bb7f588b0366692d6a4c147288c810335042d11258cbed7945','calculus-double-20260930-foundation-p28-1','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('d94b52e7-ab08-5824-8e06-f308c4fe707f','1bc86e3e-2bed-580c-b005-ec4ef354da9b','b4ee7b1e-d9c7-5567-b737-cac696eeb903','极限 lim(x→0)(sin x-x)/x³ 等于','["-1/6","0","1/6","1/3"]',4,'目录专项 · 真题难度新题 · 洛必达法则',806);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('d94b52e7-ab08-5824-8e06-f308c4fe707f',0,'三次使用洛必达法则，或展开 sin x=x-x³/6+o(x³)，得 -1/6。');
INSERT INTO question_point (revision_id,point_id) VALUES ('d94b52e7-ab08-5824-8e06-f308c4fe707f','98be520a-2040-52c6-8a01-74e6cd389875');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('e682d722-73e4-56b1-9d1e-23b294647f56','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-double-20260930-foundation-p28-2','88028b53b6f9f56938d0499e299cc34e4e05b352c747aa5a1da8f885929ea24f','calculus-double-20260930-foundation-p28-2','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('c2a836ca-9ee1-5a67-a154-069e4aebb522','1bc86e3e-2bed-580c-b005-ec4ef354da9b','e682d722-73e4-56b1-9d1e-23b294647f56','极限 lim(x→0)(ln(1+x)-x)/x² 等于','["-1","-1/2","0","1/2"]',4,'目录专项 · 真题难度新题 · 洛必达法则',807);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('c2a836ca-9ee1-5a67-a154-069e4aebb522',1,'两次使用洛必达法则，或用 ln(1+x)=x-x²/2+o(x²)。');
INSERT INTO question_point (revision_id,point_id) VALUES ('c2a836ca-9ee1-5a67-a154-069e4aebb522','98be520a-2040-52c6-8a01-74e6cd389875');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('7106f88d-97b3-56ef-aa20-806e1332fd1c','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-double-20260930-foundation-p29-1','34ce1234dabd5d4090e2f1163323b20413607ed6f66a30ff06a1f10f7e84dd00','calculus-double-20260930-foundation-p29-1','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('eab7f8c0-8bd7-55b8-a99c-4c9f0e2201c2','1bc86e3e-2bed-580c-b005-ec4ef354da9b','7106f88d-97b3-56ef-aa20-806e1332fd1c','函数 f(x)=x³-6x²+9x 在 (0,4) 内的单调递增区间为','["(0,1) 与 (3,4)","(1,3)","(0,4)","(0,3)"]',4,'目录专项 · 真题难度新题 · 函数的单调性',808);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('eab7f8c0-8bd7-55b8-a99c-4c9f0e2201c2',0,'f′=3(x-1)(x-3)，在 x<1 或 x>3 时为正。');
INSERT INTO question_point (revision_id,point_id) VALUES ('eab7f8c0-8bd7-55b8-a99c-4c9f0e2201c2','d2ce333d-ed03-54f0-b8fa-d9aedc660ffa');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('7bc5a10c-f002-5fb4-b14b-832d31b1eaa3','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-double-20260930-foundation-p29-2','7c824e070b14e63b9bd1b6472761528f97e8d8b3082f9ca58204e70c3f223f33','calculus-double-20260930-foundation-p29-2','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('62106931-754d-556f-92ee-9d55bcf0b0c7','1bc86e3e-2bed-580c-b005-ec4ef354da9b','7bc5a10c-f002-5fb4-b14b-832d31b1eaa3','函数 f(x)=ln x-x/2 在 (0,+∞) 上的单调递减区间为','["(0,2)","(2,+∞)","(0,+∞)","不存在"]',3,'目录专项 · 真题难度新题 · 函数的单调性',809);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('62106931-754d-556f-92ee-9d55bcf0b0c7',1,'f′=1/x-1/2；当 x>2 时为负。');
INSERT INTO question_point (revision_id,point_id) VALUES ('62106931-754d-556f-92ee-9d55bcf0b0c7','d2ce333d-ed03-54f0-b8fa-d9aedc660ffa');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('ff1588b2-a7ac-519d-a209-5112236e7edb','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-double-20260930-foundation-p30-1','2f4708db8e982289f6866e417305938c954e4637d44e896c918e7f313c03214d','calculus-double-20260930-foundation-p30-1','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('5d60e6fb-bb4c-50de-bd3c-10ea78e87768','1bc86e3e-2bed-580c-b005-ec4ef354da9b','ff1588b2-a7ac-519d-a209-5112236e7edb','函数 f(x)=x²e⁻ˣ 在 [0,4] 上的最大值为','["0","4e⁻²","16e⁻⁴","4"]',4,'目录专项 · 真题难度新题 · 函数的极值与最值',810);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('5d60e6fb-bb4c-50de-bd3c-10ea78e87768',1,'f′=xe⁻ˣ(2-x)，比较 x=0、2、4 处函数值，最大值为 4e⁻²。');
INSERT INTO question_point (revision_id,point_id) VALUES ('5d60e6fb-bb4c-50de-bd3c-10ea78e87768','a40a916f-9913-50f1-9256-9b51d5d950da');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('885563cc-eb23-5d9a-ac77-8a52977446a7','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-double-20260930-foundation-p30-2','770c2215dc1fd2f03a02f7aac1f286953ff36fec6e7e8d46cc83c69d890f1193','calculus-double-20260930-foundation-p30-2','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('f6e94d32-285a-5c51-ba76-1a7a27047110','1bc86e3e-2bed-580c-b005-ec4ef354da9b','885563cc-eb23-5d9a-ac77-8a52977446a7','函数 f(x)=x³-3x 在 [-2,1] 上的最小值为','["-2","0","2","4"]',4,'目录专项 · 真题难度新题 · 函数的极值与最值',811);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('f6e94d32-285a-5c51-ba76-1a7a27047110',0,'驻点为 ±1，连同端点比较，f(-2)=-2、f(-1)=2、f(1)=-2，最小值 -2。');
INSERT INTO question_point (revision_id,point_id) VALUES ('f6e94d32-285a-5c51-ba76-1a7a27047110','a40a916f-9913-50f1-9256-9b51d5d950da');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('3ab1be1d-3595-54c6-a59f-9710da29d633','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-double-20260930-foundation-p31-1','a91752a77a181016bd15220eac9c32757b8cb9415a0f02f6e99c9f57bf11b580','calculus-double-20260930-foundation-p31-1','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('5169ec4d-8267-5f06-9c92-1e02b07d8d14','1bc86e3e-2bed-580c-b005-ec4ef354da9b','3ab1be1d-3595-54c6-a59f-9710da29d633','若 F′(x)=1/(1+x²)，且 F(0)=2，则 F(1)=','["2","2+π/4","2+π/2","3"]',3,'目录专项 · 真题难度新题 · 原函数与不定积分',812);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('5169ec4d-8267-5f06-9c92-1e02b07d8d14',1,'F(x)=arctan x+C，初值给出 C=2，故 F(1)=2+π/4。');
INSERT INTO question_point (revision_id,point_id) VALUES ('5169ec4d-8267-5f06-9c92-1e02b07d8d14','8744fadd-fcb1-5683-b2f6-d855b870076a');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('8b1a85f0-4c85-5554-9501-6c1cf7033573','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-double-20260930-foundation-p31-2','2cf569ba1dced47943bafb5acd08ed9ecf3fca6ba9698af6bce2483ccc0847a4','calculus-double-20260930-foundation-p31-2','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('3efa502e-1c34-5bae-ac91-6940b2f7c7b8','1bc86e3e-2bed-580c-b005-ec4ef354da9b','8b1a85f0-4c85-5554-9501-6c1cf7033573','若 F′(x)=e²ˣ，且 F(0)=0，则 F(x)=','["e²ˣ-1","(e²ˣ-1)/2","2e²ˣ-2","e²ˣ/2"]',3,'目录专项 · 真题难度新题 · 原函数与不定积分',813);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('3efa502e-1c34-5bae-ac91-6940b2f7c7b8',1,'对 e²ˣ 积分得 e²ˣ/2+C；初值使 C=-1/2。');
INSERT INTO question_point (revision_id,point_id) VALUES ('3efa502e-1c34-5bae-ac91-6940b2f7c7b8','8744fadd-fcb1-5683-b2f6-d855b870076a');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('592d96dd-a5c4-51c1-84bb-8f4e247e466d','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-double-20260930-foundation-p32-1','62f453ec6cbe045c2b5fd15139b02f48ae23184150db08f6a3f3c09b891814a8','calculus-double-20260930-foundation-p32-1','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('6b1858ed-92e0-5f22-b9ac-ea1a19349163','1bc86e3e-2bed-580c-b005-ec4ef354da9b','592d96dd-a5c4-51c1-84bb-8f4e247e466d','不定积分 ∫x/(1+x²) dx 等于','["ln(1+x²)+C","(1/2)ln(1+x²)+C","arctan x+C","x²/(1+x²)+C"]',3,'目录专项 · 真题难度新题 · 不定积分—换元法',814);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('6b1858ed-92e0-5f22-b9ac-ea1a19349163',1,'令 u=1+x²，则 du=2x dx，积分为 (1/2)ln u+C。');
INSERT INTO question_point (revision_id,point_id) VALUES ('6b1858ed-92e0-5f22-b9ac-ea1a19349163','198c8a2e-d4e2-5434-a019-f7bfc2bfc39c');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('ecf20df8-9b51-5cb4-81c9-04827bf1e3bc','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-double-20260930-foundation-p32-2','dc782da0de639209fa20a969691f7b1a1723099e60e3b9463498fa2edb6d6407','calculus-double-20260930-foundation-p32-2','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('f539ad75-3c6a-59dc-8e78-78a33577c71c','1bc86e3e-2bed-580c-b005-ec4ef354da9b','ecf20df8-9b51-5cb4-81c9-04827bf1e3bc','不定积分 ∫cos x·e^sin x dx 等于','["e^sin x+C","e^cos x+C","sin x·e^sin x+C","-e^sin x+C"]',3,'目录专项 · 真题难度新题 · 不定积分—换元法',815);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('f539ad75-3c6a-59dc-8e78-78a33577c71c',0,'令 u=sin x，du=cos x dx，积分为 eᵘ+C。');
