INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('d6804040-53e5-5b5a-b934-8c3ccddbaaf6','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-double-20260930-foundation-p33-1','d793e9214b68da6121a287679859d23514d290fd3e61bc277a1a353f220ccc41','calculus-double-20260930-foundation-p33-1','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('3bf98e8a-12aa-5ce3-a7b4-4e93733ca819','1bc86e3e-2bed-580c-b005-ec4ef354da9b','d6804040-53e5-5b5a-b934-8c3ccddbaaf6','不定积分 ∫x sin x dx 等于','["x cos x+sin x+C","-x cos x+sin x+C","x sin x+cos x+C","-x sin x+cos x+C"]',3,'目录专项 · 真题难度新题 · 不定积分—分部积分法',816);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('3bf98e8a-12aa-5ce3-a7b4-4e93733ca819',1,'取 u=x、dv=sin x dx，得 -x cos x+∫cos x dx。');
INSERT INTO question_point (revision_id,point_id) VALUES ('3bf98e8a-12aa-5ce3-a7b4-4e93733ca819','0d93ac1f-d820-5087-b9e7-941d561835e1');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('2205caa9-2263-582d-a118-903bbac1013e','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-double-20260930-foundation-p33-2','069d872e797d4828142731bba5d0d8dc1888d6193264f8f4b0af0a6c45a7c5ef','calculus-double-20260930-foundation-p33-2','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('e0fbd58c-0f42-5c84-967d-c03a87d89564','1bc86e3e-2bed-580c-b005-ec4ef354da9b','2205caa9-2263-582d-a118-903bbac1013e','定积分 ∫₀¹x ln(1+x) dx 等于','["1/4","1/2","ln2-1/4","2ln2-1"]',4,'目录专项 · 真题难度新题 · 不定积分—分部积分法',817);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('e0fbd58c-0f42-5c84-967d-c03a87d89564',0,'分部积分：边界项为 (1/2)ln2，剩余 (1/2)∫₀¹x²/(1+x)dx=(1/2)(ln2-1/2)，相减得 1/4。');
INSERT INTO question_point (revision_id,point_id) VALUES ('e0fbd58c-0f42-5c84-967d-c03a87d89564','0d93ac1f-d820-5087-b9e7-941d561835e1');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('9341c01e-d2bd-5bd2-8b72-f9752cf52c7a','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-double-20260930-foundation-p34-1','56d5124ac95bc880665705978b43a54759fd3d400a11ed0fdce9850489596386','calculus-double-20260930-foundation-p34-1','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('b45c876d-ab2c-5a71-a5fe-008a385636d1','1bc86e3e-2bed-580c-b005-ec4ef354da9b','9341c01e-d2bd-5bd2-8b72-f9752cf52c7a','定积分 ∫₋₂²|x| dx 的几何意义对应的面积为','["2","4","6","8"]',3,'目录专项 · 真题难度新题 · 定积分的几何意义',818);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('b45c876d-ab2c-5a71-a5fe-008a385636d1',1,'图形关于原点对称，面积为 2×(底 2、高 2 的三角形面积)=4。');
