INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('e4215ead-1bf9-5434-bfee-e396e574ccd0','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-double-20260930-foundation-p34-2','37ce878e14431ac01f7aea8eeba3bb9294999ac2dd0b084c3aaf006414c7ffec','calculus-double-20260930-foundation-p34-2','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('319b0ec3-31e7-57bf-8731-2c8ec7fd3742','1bc86e3e-2bed-580c-b005-ec4ef354da9b','e4215ead-1bf9-5434-bfee-e396e574ccd0','∫₀²(4-x²)dx 表示 y=4-x² 与 x 轴之间的面积，其值为','["8/3","16/3","20/3","8"]',3,'目录专项 · 真题难度新题 · 定积分的几何意义',819);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('319b0ec3-31e7-57bf-8731-2c8ec7fd3742',1,'积分为 [4x-x³/3]₀²=8-8/3=16/3。');
