INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('0ac91462-5839-53d3-bb2d-b2a9fac2ed07','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-double-20260930-foundation-p35-1','712c8207b7a7d2b5d53d58acffa078994534187757bd073cdd6ba4ccec3f3d5a','calculus-double-20260930-foundation-p35-1','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('8e8a79fc-030e-5620-b20c-774de7890f51','1bc86e3e-2bed-580c-b005-ec4ef354da9b','0ac91462-5839-53d3-bb2d-b2a9fac2ed07','若 f 在 [0,1] 上满足 1≤f(x)≤3，则 ∫₀¹f(x)dx 必属于','["[0,1]","[1,3]","[3,4]","[0,3)"]',3,'目录专项 · 真题难度新题 · 定积分的性质',820);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('8e8a79fc-030e-5620-b20c-774de7890f51',1,'由定积分保序性，积分值介于 ∫₀¹1dx=1 与 ∫₀¹3dx=3 之间。');
INSERT INTO question_point (revision_id,point_id) VALUES ('8e8a79fc-030e-5620-b20c-774de7890f51','6aaba867-0db0-58b1-8205-6ec0ce42804f');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('11705e4f-2403-5516-bd84-729866fe6d81','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-double-20260930-foundation-p35-2','0fd292ce8fe1a6238d969a3a74eafa40d8a11ed1ded1322fa39321587a3d52e9','calculus-double-20260930-foundation-p35-2','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('589e1fb8-2142-53fe-a917-0c1cc0de37af','1bc86e3e-2bed-580c-b005-ec4ef354da9b','11705e4f-2403-5516-bd84-729866fe6d81','若 f 为奇函数且在 [-2,2] 可积，则 ∫₋₂²[f(x)+x²]dx=','["0","4/3","8/3","16/3"]',4,'目录专项 · 真题难度新题 · 定积分的性质',821);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('589e1fb8-2142-53fe-a917-0c1cc0de37af',3,'奇函数部分积分为 0，而 ∫₋₂²x²dx=16/3。');
INSERT INTO question_point (revision_id,point_id) VALUES ('589e1fb8-2142-53fe-a917-0c1cc0de37af','6aaba867-0db0-58b1-8205-6ec0ce42804f');
