INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('3bbc7d0d-b134-572a-a916-b8cf3b821321',1,'微积分基本定理与链式法则结合：F′=sin(x²)·2x。');
INSERT INTO question_point (revision_id,point_id) VALUES ('3bbc7d0d-b134-572a-a916-b8cf3b821321','e33e3950-2807-5142-adc3-7df48e2960bd');
