INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('89685704-f871-503a-b4e4-6b9fcc638616','1bc86e3e-2bed-580c-b005-ec4ef354da9b','b85c3372-5ce8-5c77-beb5-f66b737f8d66','定积分 ∫₀¹2x/(1+x²)dx 等于','["ln2","2ln2","1/2","1"]',3,'目录专项 · 真题难度新题 · 定积分的换元法和分部积分法',824);
