INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('8ade37c8-21f9-5010-9dc0-728597df7bf8','1bc86e3e-2bed-580c-b005-ec4ef354da9b','aebd3579-5b85-5448-82a7-b5e831778070','定积分 ∫₀¹x e²ˣ dx 等于','["(e²+1)/4","(e²-1)/2","e²/2","(e²-1)/4"]',4,'目录专项 · 真题难度新题 · 定积分的换元法和分部积分法',825);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('8ade37c8-21f9-5010-9dc0-728597df7bf8',0,'分部积分得 [xe²ˣ/2-e²ˣ/4]₀¹=(e²+1)/4。');
