INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('9d00b032-fbb2-5235-8c9e-e3f032b3633d','1bc86e3e-2bed-580c-b005-ec4ef354da9b','0296bd08-2587-563c-a578-5752dcd344b0','反常积分 ∫₁^∞1/x^(3/2) dx 等于','["1","2","3","发散"]',3,'目录专项 · 真题难度新题 · 反常积分',826);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('9d00b032-fbb2-5235-8c9e-e3f032b3633d',1,'原函数为 -2/√x，取上限趋于无穷，得到 2。');
