INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('e388aa5e-c2a5-508e-9e2f-3a73da937243','1bc86e3e-2bed-580c-b005-ec4ef354da9b','eae8edab-3487-5b4d-9ba3-5caa1d4e993a','直线 y=x、z=0 绕 x 轴旋转所得曲面方程为','["y²+z²=x²","x²+z²=y²","x²+y²+z²=1","z=x"]',4,'目录专项 · 真题难度新题 · 曲线旋转成曲面',868);
