INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('b54dd16a-678a-54de-a46c-0a6d69249562','1bc86e3e-2bed-580c-b005-ec4ef354da9b','af759b11-ec66-532c-b220-65c5f8a44452','平面曲线 y²=4x、z=0 绕 x 轴旋转所得曲面为','["y²+z²=4x","x²+z²=4y","x²+y²=4z","x²+y²+z²=4"]',4,'目录专项 · 真题难度新题 · 曲线旋转成曲面',869);
