INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('e6af337e-c584-5947-afb1-5a623f6a8550','1bc86e3e-2bed-580c-b005-ec4ef354da9b','68819033-9e55-510a-804a-765116295df0','极限 lim(t→0)(1-cos 2t)/t² 等于','["1","2","4","0"]',3,'目录专项 · 真题难度新题 · 一元极限基础知识',870);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('e6af337e-c584-5947-afb1-5a623f6a8550',1,'1-cos 2t≈(2t)²/2=2t²，故极限为 2。');
INSERT INTO question_point (revision_id,point_id) VALUES ('e6af337e-c584-5947-afb1-5a623f6a8550','8faaf4d8-de5e-58f3-a11f-b5b919b14bab');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('807bd9bf-030f-577f-b75d-b1293dbc9c8a','afdac469-0fe4-5007-833c-51a71333967b','32ec87c0-2e8e-5a8e-b45f-8bcf5ac63f59','legacy:00023:calculus-double-20260930-exam-2-1-2','a1bb1d85eb1420a7bc327e38a756c6f6874d802f748623e332713ed7207a8b19','calculus-double-20260930-exam-2-1-2','CHAPTER',0);
