INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('d88bc8a7-bc0e-5cae-802e-f11a881fbf04','afdac469-0fe4-5007-833c-51a71333967b','32ec87c0-2e8e-5a8e-b45f-8bcf5ac63f59','legacy:00023:calculus-double-20260930-exam-2-2-1','bbadefe61fe43c5572803b5b63d025148696255b44339835ac30cb471dfd9cfe','calculus-double-20260930-exam-2-2-1','CHAPTER',0);
