INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('820242c9-d241-5956-b13b-63fea3d74f18','afdac469-0fe4-5007-833c-51a71333967b','32ec87c0-2e8e-5a8e-b45f-8bcf5ac63f59','legacy:00023:calculus-double-20260930-exam-2-2-2','0172cda3bd23c7cb86c0594b45c4ba0c9a706e4176d8ed5cc8ac0179f7a59ed1','calculus-double-20260930-exam-2-2-2','CHAPTER',0);
