INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('106b35c3-f416-5774-893d-cb21c97a64ce','afdac469-0fe4-5007-833c-51a71333967b','32ec87c0-2e8e-5a8e-b45f-8bcf5ac63f59','legacy:00023:calculus-double-20260930-exam-2-6-1','03f1c8c10351292a928610b599ff8b84708a0431bb188ef0115e1535c01271f6','calculus-double-20260930-exam-2-6-1','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('8ec7b219-93b0-5630-a5ca-fd126ded8829','1bc86e3e-2bed-580c-b005-ec4ef354da9b','106b35c3-f416-5774-893d-cb21c97a64ce','若 x²+xy+y²=7 且 y=y(x)，在 (1,2) 处 y′=','["-4/5","-2/5","2/5","4/5"]',4,'目录专项 · 真题难度新题 · 隐函数求偏导之公式法',880);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('8ec7b219-93b0-5630-a5ca-fd126ded8829',0,'隐式求导得 2x+y+(x+2y)y′=0，代入 (1,2) 得 y′=-4/5。');
