INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('3c536a21-3cf8-5c9e-91cc-3def2379c4c9','afdac469-0fe4-5007-833c-51a71333967b','32ec87c0-2e8e-5a8e-b45f-8bcf5ac63f59','legacy:00023:calculus-double-20260930-exam-2-6-2','e3e52235eee5b800dcdbf793099f828695a3d46db704daa25aa976cff69c04da','calculus-double-20260930-exam-2-6-2','CHAPTER',0);
