INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('99b6bbea-b591-5e46-bfa0-84282f4d2f2c',0,'求偏导：e^(xy+z)(y+zₓ)+zₓ=0；代入点得 1+2zₓ=0。');
