INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('67374dda-3479-56a5-aad5-d8d5276bc9b2','1bc86e3e-2bed-580c-b005-ec4ef354da9b','277a89a8-503d-5391-a1e1-1fe7324aa336','由 z²+xz+y=3 在 (1,1,1) 附近确定 z(x,y)，则 zᵧ=','["-1","-1/3","1/3","1"]',4,'目录专项 · 真题难度新题 · 隐函数求偏导之复合法',883);
