INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('ed0e638d-589d-506a-942e-c9442078b7f3','1bc86e3e-2bed-580c-b005-ec4ef354da9b','23d0e005-ec37-5285-bbe8-d697144044e4','设 f(x,y)=xy/√(x²+y²)（非原点），f(0,0)=0，则原点处','["连续且可微","连续但不可微","不连续","没有偏导数"]',4,'目录专项 · 真题难度新题 · 二元连续和可导',885);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('ed0e638d-589d-506a-942e-c9442078b7f3',1,'|xy|/√(x²+y²)≤√(x²+y²)/2，故连续；两偏导均为 0，但沿 y=x 的商不趋于 0，故不可微。');
INSERT INTO question_point (revision_id,point_id) VALUES ('ed0e638d-589d-506a-942e-c9442078b7f3','31463a7a-07a8-5f3f-8635-ddb078f4aa7b');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('cffc0933-1feb-5ec4-a04a-9a9a07c922ea','afdac469-0fe4-5007-833c-51a71333967b','32ec87c0-2e8e-5a8e-b45f-8bcf5ac63f59','legacy:00023:calculus-double-20260930-exam-2-9-1','77807af18c13572cd25b8057825ff203cd242edb7ec8219c78bef92018e679a5','calculus-double-20260930-exam-2-9-1','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('4a765c59-24cc-5d7b-b453-f6ef8a98f0e5','1bc86e3e-2bed-580c-b005-ec4ef354da9b','cffc0933-1feb-5ec4-a04a-9a9a07c922ea','若 z=x²y+y³，则 dz 在 (1,1) 处为','["2dx+4dy","dx+3dy","2dx+3dy","4dx+2dy"]',3,'目录专项 · 真题难度新题 · 求全微分',886);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('4a765c59-24cc-5d7b-b453-f6ef8a98f0e5',0,'zₓ=2xy=2，zᵧ=x²+3y²=4。');
