INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('be3ac55c-a96f-5ca7-bb4f-8092ad8f3668','afdac469-0fe4-5007-833c-51a71333967b','32ec87c0-2e8e-5a8e-b45f-8bcf5ac63f59','legacy:00023:calculus-double-20260930-exam-2-9-2','10a89ef71d494a8cac6908f5415f24b5d5674d47a6345b9f8d57f192c55c92a4','calculus-double-20260930-exam-2-9-2','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('b2adf4f1-34f3-5687-81bd-fa7714e61f28','1bc86e3e-2bed-580c-b005-ec4ef354da9b','be3ac55c-a96f-5ca7-bb4f-8092ad8f3668','若 z=ln(x+y)，则 dz 在 (1,2) 处为','["dx+dy","(dx+dy)/2","(dx+dy)/3","dx+2dy"]',3,'目录专项 · 真题难度新题 · 求全微分',887);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('b2adf4f1-34f3-5687-81bd-fa7714e61f28',2,'两个偏导均为 1/(x+y)，在 (1,2) 为 1/3。');
