INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('fa2b24d3-f200-56e8-bf91-d98e97fcbc15','afdac469-0fe4-5007-833c-51a71333967b','32ec87c0-2e8e-5a8e-b45f-8bcf5ac63f59','legacy:00023:calculus-double-20260930-exam-2-10-1','8c2c21d62e5a2d4baf8a98994d1777b831aa1e81965314d717909b5f8cb7b413','calculus-double-20260930-exam-2-10-1','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('1f93724b-b495-532f-8187-d337b860a717','1bc86e3e-2bed-580c-b005-ec4ef354da9b','fa2b24d3-f200-56e8-bf91-d98e97fcbc15','若 dz=(2xy+1)dx+(x²+2y)dy，则 z 可取','["x²y+x+y²","2x²y+x+y²","x²y+x+2y²","xy+x+y²"]',4,'目录专项 · 真题难度新题 · 求全微分的原函数',888);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('1f93724b-b495-532f-8187-d337b860a717',0,'对候选函数分别求两偏导，只有 x²y+x+y² 与所给系数一致。');
