INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('8179f544-1a6f-596b-a385-7236b69e3ca3','afdac469-0fe4-5007-833c-51a71333967b','32ec87c0-2e8e-5a8e-b45f-8bcf5ac63f59','legacy:00023:calculus-double-20260930-exam-2-10-2','8032a52473bc7dec25d359038144198fb70b3702e7dff8961a3455dc94b24cea','calculus-double-20260930-exam-2-10-2','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('3466d98a-aad0-553b-98ef-e9d204a90b08','1bc86e3e-2bed-580c-b005-ec4ef354da9b','8179f544-1a6f-596b-a385-7236b69e3ca3','若 dz=3x²dx+2y dy，且 z(0,0)=2，则 z(x,y)=','["x³+y²","x³+y²+2","3x³+2y²+2","x³+2y²+2"]',3,'目录专项 · 真题难度新题 · 求全微分的原函数',889);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('3466d98a-aad0-553b-98ef-e9d204a90b08',1,'分别积分得 z=x³+y²+C，初值使 C=2。');
