INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('a57da71c-60d2-55b2-9d09-a0a80c635002','afdac469-0fe4-5007-833c-51a71333967b','32ec87c0-2e8e-5a8e-b45f-8bcf5ac63f59','legacy:00023:calculus-double-20260930-exam-2-11-1','604db8648d6a69ee87db85b215521998af107c695d07c9660deeb2ed4f0ebbc3','calculus-double-20260930-exam-2-11-1','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('22995bf9-5c56-502d-9291-2c95ed9c9eb2','1bc86e3e-2bed-580c-b005-ec4ef354da9b','a57da71c-60d2-55b2-9d09-a0a80c635002','设 z=e^(xy)，则 zₓᵧ 在 (0,1) 处为','["0","1","2","e"]',4,'目录专项 · 真题难度新题 · 二阶偏导次序无关',890);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('22995bf9-5c56-502d-9291-2c95ed9c9eb2',1,'zₓ=ye^(xy)，再对 y 求偏导为 e^(xy)(1+xy)，代入点为 1。');
