INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('44a9df4c-9ff2-53de-a932-c70ae2f8cfdf','afdac469-0fe4-5007-833c-51a71333967b','e7742ada-e08b-5e92-a4db-cedfa4d5c8c1','legacy:00023:calculus-double-20260930-exam-3-2-2','cc7cecbf87c4a2ba0a8eac78f960093aede836ab478044bb0a7c114ed0bc41ef','calculus-double-20260930-exam-3-2-2','CHAPTER',0);
