INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('78e63e68-e6c0-5159-ae95-6771aa424344','1bc86e3e-2bed-580c-b005-ec4ef354da9b','cc8df13b-5435-58b0-a623-e66f29d1a3be','D={(x,y):0≤x≤2,0≤y≤x}，则 ∬_D y dA=','["2/3","4/3","2","8/3"]',4,'目录专项 · 真题难度新题 · 直角坐标求二重积分',908);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('78e63e68-e6c0-5159-ae95-6771aa424344',1,'先对 y 积分得 x²/2，再对 x 从 0 到 2 积分得 4/3。');
