INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('5b89bc39-28a7-53b2-b428-4b83150320e5','afdac469-0fe4-5007-833c-51a71333967b','e7742ada-e08b-5e92-a4db-cedfa4d5c8c1','legacy:00023:calculus-double-20260930-exam-3-3-2','456b96812dc4da31e8076fcce3f63ff56a904d8ccf5456a9a445be794790b368','calculus-double-20260930-exam-3-3-2','CHAPTER',0);
