INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('b1d3eb98-53b0-5158-a727-4dc1a1dcaf2b',1,'极坐标下面积元 r dr dθ 与被积函数 1/r 抵消，得 2π∫₁²dr=2π。');
