INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('db6c04ee-5c3a-5b95-baf0-653a80eab9a6','afdac469-0fe4-5007-833c-51a71333967b','e7742ada-e08b-5e92-a4db-cedfa4d5c8c1','legacy:00023:calculus-double-20260930-exam-3-6-1','3a17539eb59d13aa22b82c73aec042e344351804c3bec509e20cf430705facf0','calculus-double-20260930-exam-3-6-1','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('97a49728-9b3a-5774-8acc-b37f6a47e41e','1bc86e3e-2bed-580c-b005-ec4ef354da9b','db6c04ee-5c3a-5b95-baf0-653a80eab9a6','底面积为 6、高为 3 的直棱柱 Ω 上，∭_Ω 1 dV=','["9","12","18","36"]',3,'目录专项 · 真题难度新题 · 几何意义求三重积分',914);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('97a49728-9b3a-5774-8acc-b37f6a47e41e',2,'三重积分 1 等于体积，底面积乘高为 18。');
INSERT INTO question_point (revision_id,point_id) VALUES ('97a49728-9b3a-5774-8acc-b37f6a47e41e','26a2d541-a63e-55eb-b10e-a96fdf1fcca4');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('c9794f4e-628a-536c-a5e2-7232a9857021','afdac469-0fe4-5007-833c-51a71333967b','e7742ada-e08b-5e92-a4db-cedfa4d5c8c1','legacy:00023:calculus-double-20260930-exam-3-6-2','d681229f192189bbf89472defd4bf38446f7a61c7dd6b7ecd737c0a3e40a6b2d','calculus-double-20260930-exam-3-6-2','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('6a06e323-9068-5eab-8faa-37c0c81c5548','1bc86e3e-2bed-580c-b005-ec4ef354da9b','c9794f4e-628a-536c-a5e2-7232a9857021','Ω 为半径 3 的上半球体，则 ∭_Ω 1 dV=','["9π","18π","27π","36π"]',3,'目录专项 · 真题难度新题 · 几何意义求三重积分',915);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('6a06e323-9068-5eab-8faa-37c0c81c5548',1,'半球体积为 (1/2)×(4π/3)×3³=18π。');
INSERT INTO question_point (revision_id,point_id) VALUES ('6a06e323-9068-5eab-8faa-37c0c81c5548','26a2d541-a63e-55eb-b10e-a96fdf1fcca4');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('62e0170f-0ec1-5fe3-8358-570786faf08c','afdac469-0fe4-5007-833c-51a71333967b','e7742ada-e08b-5e92-a4db-cedfa4d5c8c1','legacy:00023:calculus-double-20260930-exam-3-7-1','0ba972e2b0d2a3aa1f84b1ffde2be41484e9c2c4503929c22fde75854fa50fe8','calculus-double-20260930-exam-3-7-1','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('fde604a2-a255-56ad-8c78-5ceabce6a88f','1bc86e3e-2bed-580c-b005-ec4ef354da9b','62e0170f-0ec1-5fe3-8358-570786faf08c','Ω=[0,1]×[0,2]×[0,1]，则 ∭_Ω (x+z)dV=','["1","2","3","4"]',3,'目录专项 · 真题难度新题 · 直角坐标求三重积分',916);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('fde604a2-a255-56ad-8c78-5ceabce6a88f',1,'x 项积分为 1，z 项积分为 1，合计 2。');
INSERT INTO question_point (revision_id,point_id) VALUES ('fde604a2-a255-56ad-8c78-5ceabce6a88f','1d087339-38eb-59b1-b6bb-874779fe88f1');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('6184b851-93f7-5e12-9fd6-54b73ebd2001','afdac469-0fe4-5007-833c-51a71333967b','e7742ada-e08b-5e92-a4db-cedfa4d5c8c1','legacy:00023:calculus-double-20260930-exam-3-7-2','cb3c6678b65286d4876f809a4dbba18b36b2d33e48ee11b8ecfd9fa5af2efdfe','calculus-double-20260930-exam-3-7-2','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('29753c7c-4acb-54b8-bd86-89991bd0c3f7','1bc86e3e-2bed-580c-b005-ec4ef354da9b','6184b851-93f7-5e12-9fd6-54b73ebd2001','Ω={0≤x≤1,0≤y≤x,0≤z≤1}，则 ∭_Ω x dV=','["1/6","1/3","1/2","1"]',4,'目录专项 · 真题难度新题 · 直角坐标求三重积分',917);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('29753c7c-4acb-54b8-bd86-89991bd0c3f7',1,'先积 z、y 得 x²，再积 x 得 1/3。');
INSERT INTO question_point (revision_id,point_id) VALUES ('29753c7c-4acb-54b8-bd86-89991bd0c3f7','1d087339-38eb-59b1-b6bb-874779fe88f1');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('d0afacf4-a14f-556e-a48a-d7630eaa2583','afdac469-0fe4-5007-833c-51a71333967b','e7742ada-e08b-5e92-a4db-cedfa4d5c8c1','legacy:00023:calculus-double-20260930-exam-3-8-1','5a4963ef08334b67bba047e96c146ea26b9a8f94f2c9499e54829e927321ff5d','calculus-double-20260930-exam-3-8-1','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('8dd8ec42-0435-500a-ae9a-fb02516bc2a6','1bc86e3e-2bed-580c-b005-ec4ef354da9b','d0afacf4-a14f-556e-a48a-d7630eaa2583','Ω 为单位球体，则 ∭_Ω (x³+yz)dV=','["-1","0","π/2","4π/3"]',3,'目录专项 · 真题难度新题 · 三重积分的对称奇偶性',918);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('8dd8ec42-0435-500a-ae9a-fb02516bc2a6',1,'x³ 关于 x 奇，yz 关于 y 奇；球体对应对称，两项积分都为 0。');
INSERT INTO question_point (revision_id,point_id) VALUES ('8dd8ec42-0435-500a-ae9a-fb02516bc2a6','4aa1da48-4733-524b-9b1f-d5630ff83e7c');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('af765383-1046-562a-ad2e-aee0ba3b6ba0','afdac469-0fe4-5007-833c-51a71333967b','e7742ada-e08b-5e92-a4db-cedfa4d5c8c1','legacy:00023:calculus-double-20260930-exam-3-8-2','1b417b6989bdcaac1840c07d419ce23ebfd3bf5105242e10f271c7cb908b95a3','calculus-double-20260930-exam-3-8-2','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('1b48d94f-0cea-5ab4-b7e8-cb1e3bd4f879','1bc86e3e-2bed-580c-b005-ec4ef354da9b','af765383-1046-562a-ad2e-aee0ba3b6ba0','Ω=[-1,1]³，则 ∭_Ω (x²+y)dV=','["0","4/3","8/3","4"]',4,'目录专项 · 真题难度新题 · 三重积分的对称奇偶性',919);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('1b48d94f-0cea-5ab4-b7e8-cb1e3bd4f879',2,'y 项对称积分为 0，x² 项积分为 (2/3)×2×2=8/3。');
INSERT INTO question_point (revision_id,point_id) VALUES ('1b48d94f-0cea-5ab4-b7e8-cb1e3bd4f879','4aa1da48-4733-524b-9b1f-d5630ff83e7c');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('dfdfe3fd-a9a6-59f1-b854-4cc6039656d9','afdac469-0fe4-5007-833c-51a71333967b','9fc3a71b-4a89-5ce2-b14c-962058f7e5f7','legacy:00023:calculus-double-20260930-exam-4-1-1','bdb18bc89e6719a9f1b0444dc5b3bea4fcad943dccc4158162179925fff64184','calculus-double-20260930-exam-4-1-1','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('88316f27-bbfd-540a-9928-ed21e1b981a8','1bc86e3e-2bed-580c-b005-ec4ef354da9b','dfdfe3fd-a9a6-59f1-b854-4cc6039656d9','L 为从 (0,0) 到 (2,0) 的线段，则 ∫_L x² ds=','["4/3","8/3","4","8"]',3,'目录专项 · 真题难度新题 · 对弧长的曲线积分',920);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('88316f27-bbfd-540a-9928-ed21e1b981a8',1,'沿线段 ds=dx，积分 ∫₀²x²dx=8/3。');
INSERT INTO question_point (revision_id,point_id) VALUES ('88316f27-bbfd-540a-9928-ed21e1b981a8','d0abce7e-1978-5540-b89b-86d9a6176c49');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('53d3a0c5-abf0-5b0f-b299-1d7420b5d97a','afdac469-0fe4-5007-833c-51a71333967b','9fc3a71b-4a89-5ce2-b14c-962058f7e5f7','legacy:00023:calculus-double-20260930-exam-4-1-2','e923fe36c4e695eb90a30d4c16f10e6441b395103b709a6603022c214de9e04d','calculus-double-20260930-exam-4-1-2','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('97f665f1-f44f-59df-b1a6-3fbe7314d9e9','1bc86e3e-2bed-580c-b005-ec4ef354da9b','53d3a0c5-abf0-5b0f-b299-1d7420b5d97a','L 为参数曲线 (x,y)=(t,t)，0≤t≤2，则 ∫_L (x+y)ds=','["2√2","4√2","8√2","4"]',4,'目录专项 · 真题难度新题 · 对弧长的曲线积分',921);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('97f665f1-f44f-59df-b1a6-3fbe7314d9e9',1,'ds=√2dt，x+y=2t，积分 2√2∫₀²t dt=4√2。');
INSERT INTO question_point (revision_id,point_id) VALUES ('97f665f1-f44f-59df-b1a6-3fbe7314d9e9','d0abce7e-1978-5540-b89b-86d9a6176c49');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('0189561b-6e9e-5971-b6cf-49b1ca816044','afdac469-0fe4-5007-833c-51a71333967b','9fc3a71b-4a89-5ce2-b14c-962058f7e5f7','legacy:00023:calculus-double-20260930-exam-4-2-1','0c3d311f42e0e9901d02bd36f6d6254625b429b0ad28879e1b8db0bd7e1e45d9','calculus-double-20260930-exam-4-2-1','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('47a72afc-771f-5a0e-98b1-43657ad69253','1bc86e3e-2bed-580c-b005-ec4ef354da9b','0189561b-6e9e-5971-b6cf-49b1ca816044','L 为半径 2 的上半圆，则 ∫_L 1 ds=','["π","2π","4π","8π"]',3,'目录专项 · 真题难度新题 · 对弧长的曲线积分（特殊情况）',922);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('47a72afc-771f-5a0e-98b1-43657ad69253',1,'第一类曲线积分的被积函数为 1 时等于弧长，半圆弧长为 2π。');
INSERT INTO question_point (revision_id,point_id) VALUES ('47a72afc-771f-5a0e-98b1-43657ad69253','644ef4a2-5765-5e48-bbe0-9c877b1e5abb');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('c8d240d6-24b0-52c4-92c8-98982f1a4084','afdac469-0fe4-5007-833c-51a71333967b','9fc3a71b-4a89-5ce2-b14c-962058f7e5f7','legacy:00023:calculus-double-20260930-exam-4-2-2','9532a6b7a9ae01e55afac1fa5e7de7419845b2f4018a2e95c0f860bb16d523c9','calculus-double-20260930-exam-4-2-2','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('d5986975-7f5a-52cf-99dc-54028cbb0f77','1bc86e3e-2bed-580c-b005-ec4ef354da9b','c8d240d6-24b0-52c4-92c8-98982f1a4084','L 为单位圆周，则 ∮_L x² ds=','["π/2","π","2π","4π"]',4,'目录专项 · 真题难度新题 · 对弧长的曲线积分（特殊情况）',923);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('d5986975-7f5a-52cf-99dc-54028cbb0f77',1,'参数化 x=cos t、ds=dt，积分 ∫₀²πcos²t dt=π。');
INSERT INTO question_point (revision_id,point_id) VALUES ('d5986975-7f5a-52cf-99dc-54028cbb0f77','644ef4a2-5765-5e48-bbe0-9c877b1e5abb');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('c08bd1b7-12b8-52fe-b49c-0f249aad7ab2','afdac469-0fe4-5007-833c-51a71333967b','9fc3a71b-4a89-5ce2-b14c-962058f7e5f7','legacy:00023:calculus-double-20260930-exam-4-3-1','058401d0b17d5b6f914f39c3107f65bb67fd3fd62488dc22e61846e821474afd','calculus-double-20260930-exam-4-3-1','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('c6ae4d75-af09-5523-9910-fadd11ac946a','1bc86e3e-2bed-580c-b005-ec4ef354da9b','c08bd1b7-12b8-52fe-b49c-0f249aad7ab2','L 为线段 (0,0)→(2,1)，则 ∫_L (x dy+y dx)=','["0","1","2","3"]',3,'目录专项 · 真题难度新题 · 对坐标的曲线积分',924);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('c6ae4d75-af09-5523-9910-fadd11ac946a',2,'被积表达式是 d(xy)，故积分为终点 xy 与起点 xy 之差，即 2。');
INSERT INTO question_point (revision_id,point_id) VALUES ('c6ae4d75-af09-5523-9910-fadd11ac946a','e21e2b33-6e49-59a6-a8a2-2e309538a3cd');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('5b3f9e89-ad65-5abc-ae47-30de04afc440','afdac469-0fe4-5007-833c-51a71333967b','9fc3a71b-4a89-5ce2-b14c-962058f7e5f7','legacy:00023:calculus-double-20260930-exam-4-3-2','ab9efdc64d83bc63a3665c25246753c9dd7529b3eb2fa9dc88501513c4fc0ff6','calculus-double-20260930-exam-4-3-2','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('d3fd1a2f-9d9f-5e0c-b69b-b0745c1e641f','1bc86e3e-2bed-580c-b005-ec4ef354da9b','5b3f9e89-ad65-5abc-ae47-30de04afc440','L 为从 (1,0) 沿直线到 (0,1)，则 ∫_L (2x dx+2y dy)=','["-1","0","1","2"]',4,'目录专项 · 真题难度新题 · 对坐标的曲线积分',925);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('d3fd1a2f-9d9f-5e0c-b69b-b0745c1e641f',1,'被积表达式为 d(x²+y²)，两端 x²+y² 均为 1，故积分为 0。');
INSERT INTO question_point (revision_id,point_id) VALUES ('d3fd1a2f-9d9f-5e0c-b69b-b0745c1e641f','e21e2b33-6e49-59a6-a8a2-2e309538a3cd');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('17a80034-cf79-5eaf-9de7-d74562fae5ad','afdac469-0fe4-5007-833c-51a71333967b','9fc3a71b-4a89-5ce2-b14c-962058f7e5f7','legacy:00023:calculus-double-20260930-exam-4-4-1','7898c500a73a6f2083643a4c934b0822b2c20d462b769ea24368042e593f8137','calculus-double-20260930-exam-4-4-1','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('42640ea5-895b-5b2b-8cf7-c8dff2287d4f','1bc86e3e-2bed-580c-b005-ec4ef354da9b','17a80034-cf79-5eaf-9de7-d74562fae5ad','L 为正向围成矩形 [0,2]×[0,3] 的边界，则 ∮_L (-y dx+x dy)=','["6","12","18","24"]',4,'目录专项 · 真题难度新题 · 对坐标的曲线积分之格林公式',926);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('42640ea5-895b-5b2b-8cf7-c8dff2287d4f',1,'格林公式给出 integrand 2，矩形面积为 6，故积分为 12。');
INSERT INTO question_point (revision_id,point_id) VALUES ('42640ea5-895b-5b2b-8cf7-c8dff2287d4f','1275dbf7-cc28-5dfa-8d3e-5dc099b02959');
