INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('0d9b2fc6-82fb-5edb-86a1-c99b4a8701f2',1,'按 b₁=(1/π)∫₋π^πsin²x dx=1。');
INSERT INTO question_point (revision_id,point_id) VALUES ('0d9b2fc6-82fb-5edb-86a1-c99b4a8701f2','f0531ec3-fd88-5f6e-8f69-9f74029a2d0c');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('95b0ff50-62a3-5e6d-a0bd-4db24c8aa038','afdac469-0fe4-5007-833c-51a71333967b','8c772590-817b-5b20-a874-31fff00ed3e5','legacy:00023:calculus-double-20260930-exam-6-14-1','b1fc3fa14d57a53ddcaa5ebee3d5110c646fc85032b83c57fbd279961c04a883','calculus-double-20260930-exam-6-14-1','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('3df56083-7075-577e-8715-fb569a354861','1bc86e3e-2bed-580c-b005-ec4ef354da9b','95b0ff50-62a3-5e6d-a0bd-4db24c8aa038','若正项级数满足 limsup(aₙ)^(1/n)=2，则级数','["收敛","发散","条件收敛","无法判定"]',3,'目录专项 · 真题难度新题 · 根值审敛法',970);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('3df56083-7075-577e-8715-fb569a354861',1,'根值大于 1，通项不趋于 0，故发散。');
