INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('c4c29e39-b54b-5859-9b2f-ef09b9d218b3','afdac469-0fe4-5007-833c-51a71333967b','8c772590-817b-5b20-a874-31fff00ed3e5','legacy:00023:calculus-double-20260930-exam-6-14-2','a2fc43842cec1dd513f1d5f7376266a64ee3d40d011ea9e60beebe45aa386b24','calculus-double-20260930-exam-6-14-2','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('16c3117d-6d0d-58a7-957d-b5d5a660d94d','1bc86e3e-2bed-580c-b005-ec4ef354da9b','c4c29e39-b54b-5859-9b2f-ef09b9d218b3','若 limsup(aₙ)^(1/n)=1，根值判别法对正项级数的结论是','["一定收敛","一定发散","不能判定","条件收敛"]',4,'目录专项 · 真题难度新题 · 根值审敛法',971);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('16c3117d-6d0d-58a7-957d-b5d5a660d94d',2,'根值等于 1 时判别法失效，调和级数和平方倒数级数都可作为例子。');
INSERT INTO question_point (revision_id,point_id) VALUES ('16c3117d-6d0d-58a7-957d-b5d5a660d94d','c7f3ebb7-0c24-544b-8054-fb321822722d');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('a416c090-d48d-5fed-a53d-cb746ad06c59','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-fresh-20260929-1','4a0f7947b424ea302f8716e1afd8c515bc5152d9f3d9e6182e3411c047efc9f2','calculus-fresh-20260929-1','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('382fcea6-bd3a-50b3-b1e5-21c74bdd9e36','1bc86e3e-2bed-580c-b005-ec4ef354da9b','a416c090-d48d-5fed-a53d-cb746ad06c59','反常积分 $\\int_1^{+\\infty}\\frac{\\ln x}{x^p}\\,dx$ 收敛的充要条件是','["$p>1$","$p\\\\ge1$","$p>0$","$p\\\\ge0$"]',4,'章节刷题 · 真题难度新题 · 反常积分的敛散性',972);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('382fcea6-bd3a-50b3-b1e5-21c74bdd9e36',0,'令 $t=\\ln x$，积分化为 $\\int_0^{+\\infty}te^{-(p-1)t}dt$；当且仅当 $p>1$ 收敛。');
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('e4bc662a-0177-5134-92ee-710db3734281','1da6de03-1c89-524f-824a-35bc7bb191ca','反常积分的敛散性','反常积分的敛散性');
INSERT INTO release_point (release_id,chapter_id,point_id,title_snapshot) VALUES ('1bc86e3e-2bed-580c-b005-ec4ef354da9b','1da6de03-1c89-524f-824a-35bc7bb191ca','e4bc662a-0177-5134-92ee-710db3734281','反常积分的敛散性');
INSERT INTO question_point (revision_id,point_id) VALUES ('382fcea6-bd3a-50b3-b1e5-21c74bdd9e36','e4bc662a-0177-5134-92ee-710db3734281');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('2301fca1-656b-583a-9fd0-fc48e78b2e27','afdac469-0fe4-5007-833c-51a71333967b','9f58c98e-82a0-51b9-8946-a297b17b7840','legacy:00023:calculus-fresh-20260929-2','600322c074679130ef5f09184492b766ad43616bd1f1cdaff655ae38a9e6cc75','calculus-fresh-20260929-2','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('00cc0bca-9ae2-5e88-a344-ef8c1d8257ed','1bc86e3e-2bed-580c-b005-ec4ef354da9b','2301fca1-656b-583a-9fd0-fc48e78b2e27','直线的方向向量为 $(1,2,2)$，平面的法向量为 $(2,0,1)$，则直线与平面的夹角的正弦值为','["$\\\\frac49$","$\\\\frac4{3\\\\sqrt5}$","$\\\\frac23$","$\\\\frac{\\\\sqrt5}3$"]',4,'章节刷题 · 真题难度新题 · 直线与平面的夹角',973);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('00cc0bca-9ae2-5e88-a344-ef8c1d8257ed',1,'方向向量与法向量的点积为 4，模分别为 3、$\\sqrt5$，故直线与平面夹角的正弦为 $4/(3\\sqrt5)$。');
INSERT INTO question_point (revision_id,point_id) VALUES ('00cc0bca-9ae2-5e88-a344-ef8c1d8257ed','ebdff95a-4d80-5c09-8a6c-e8bfba2d1d55');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('24a68f3b-4e18-55cb-a16e-9843ae568d55','afdac469-0fe4-5007-833c-51a71333967b','32ec87c0-2e8e-5a8e-b45f-8bcf5ac63f59','legacy:00023:calculus-fresh-20260929-3','ec7a5ec93d3eeaa8b72ab5b21c768e017ea00f87bc532fa319c917956254613a','calculus-fresh-20260929-3','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('a58e45fd-51ec-52fa-9e6f-f07527c00165','1bc86e3e-2bed-580c-b005-ec4ef354da9b','24a68f3b-4e18-55cb-a16e-9843ae568d55','设 $f(x,y)=\\frac{x^2y}{x^2+y^2}$（$(x,y)\\ne(0,0)$），且 $f(0,0)=0$。在原点处该函数','["连续且可微","连续但不可微","不连续但两个偏导数存在","既不连续也无偏导数"]',4,'章节刷题 · 真题难度新题 · 二元函数的连续与可导',974);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('a58e45fd-51ec-52fa-9e6f-f07527c00165',1,'由 $|f(x,y)|\\le |y|$ 知连续；两偏导均为 0，但沿 $y=x$ 有 $f(x,x)=x/2$，不满足可微所需的 $o(\\sqrt{x^2+y^2})$ 条件。');
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('d6f4312d-9335-5057-900e-a25f684581c7','32ec87c0-2e8e-5a8e-b45f-8bcf5ac63f59','二元函数的连续与可导','二元函数的连续与可导');
INSERT INTO release_point (release_id,chapter_id,point_id,title_snapshot) VALUES ('1bc86e3e-2bed-580c-b005-ec4ef354da9b','32ec87c0-2e8e-5a8e-b45f-8bcf5ac63f59','d6f4312d-9335-5057-900e-a25f684581c7','二元函数的连续与可导');
INSERT INTO question_point (revision_id,point_id) VALUES ('a58e45fd-51ec-52fa-9e6f-f07527c00165','d6f4312d-9335-5057-900e-a25f684581c7');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('8c823309-a591-52d8-907a-e99b750105db','afdac469-0fe4-5007-833c-51a71333967b','e7742ada-e08b-5e92-a4db-cedfa4d5c8c1','legacy:00023:calculus-fresh-20260929-4','e419d8633c36d7ec7d34bc334a709e38c4f4cda3c6efec2a2de1b8394f8d507b','calculus-fresh-20260929-4','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('29b5b1e1-ed2a-5fc7-953b-03536b32eeb8','1bc86e3e-2bed-580c-b005-ec4ef354da9b','8c823309-a591-52d8-907a-e99b750105db','区域 $D$ 为 $x^2+y^2\\le4$，则 $\\iint_D\\sqrt{x^2+y^2}\\,dxdy=$','["$\\\\frac{8\\\\pi}3$","$\\\\frac{16\\\\pi}3$","$4\\\\pi$","$8\\\\pi$"]',4,'章节刷题 · 真题难度新题 · 极坐标下的二重积分',975);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('29b5b1e1-ed2a-5fc7-953b-03536b32eeb8',1,'极坐标下面积元为 $rdrd\\theta$，故积分为 $2\\pi\\int_0^2r^2dr=16\\pi/3$。');
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('34d8a17a-8e85-5ca4-9534-0df5e0e13c32','e7742ada-e08b-5e92-a4db-cedfa4d5c8c1','极坐标下的二重积分','极坐标下的二重积分');
INSERT INTO release_point (release_id,chapter_id,point_id,title_snapshot) VALUES ('1bc86e3e-2bed-580c-b005-ec4ef354da9b','e7742ada-e08b-5e92-a4db-cedfa4d5c8c1','34d8a17a-8e85-5ca4-9534-0df5e0e13c32','极坐标下的二重积分');
INSERT INTO question_point (revision_id,point_id) VALUES ('29b5b1e1-ed2a-5fc7-953b-03536b32eeb8','34d8a17a-8e85-5ca4-9534-0df5e0e13c32');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('ef8cb76a-e628-5991-8e34-40d9513a0a46','afdac469-0fe4-5007-833c-51a71333967b','9fc3a71b-4a89-5ce2-b14c-962058f7e5f7','legacy:00023:calculus-fresh-20260929-5','e5f908811acc258b7313836719db4b7438eb9627d72747344c18d02299aeb304','calculus-fresh-20260929-5','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('6b969393-2eba-59a5-bae6-7da461064de2','1bc86e3e-2bed-580c-b005-ec4ef354da9b','ef8cb76a-e628-5991-8e34-40d9513a0a46','$L$ 为正向围成三角形 $(0,0),(2,0),(0,1)$ 的边界，则 $\\oint_L (x-y)\\,dx+(x+y)\\,dy=$','["$0$","$1$","$2$","$4$"]',4,'章节刷题 · 真题难度新题 · 格林公式与曲线积分',976);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('6b969393-2eba-59a5-bae6-7da461064de2',2,'格林公式的被积函数为 $\\partial Q/\\partial x-\\partial P/\\partial y=1-(-1)=2$；三角形面积为 1，积分为 2。');
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('58e51315-71c6-50c0-82c9-0ea244bf7612','9fc3a71b-4a89-5ce2-b14c-962058f7e5f7','格林公式与曲线积分','格林公式与曲线积分');
INSERT INTO release_point (release_id,chapter_id,point_id,title_snapshot) VALUES ('1bc86e3e-2bed-580c-b005-ec4ef354da9b','9fc3a71b-4a89-5ce2-b14c-962058f7e5f7','58e51315-71c6-50c0-82c9-0ea244bf7612','格林公式与曲线积分');
INSERT INTO question_point (revision_id,point_id) VALUES ('6b969393-2eba-59a5-bae6-7da461064de2','58e51315-71c6-50c0-82c9-0ea244bf7612');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('e3074349-91f8-5c44-b8a9-21ebf862b710','afdac469-0fe4-5007-833c-51a71333967b','7f2ef968-dd1d-56f8-ac00-158b51f9ac0a','legacy:00023:calculus-fresh-20260929-6','c1f5c25ea0ec3d2817d9c65fb045d6ff1bc025d69ebbe17c92ec506b9fcd1d6d','calculus-fresh-20260929-6','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('108bfe71-914e-5c63-9a71-33b2e0512496','1bc86e3e-2bed-580c-b005-ec4ef354da9b','e3074349-91f8-5c44-b8a9-21ebf862b710','满足 $y\\prime\\prime=2y\\prime$ 且 $y(0)=0,\\;y\\prime(0)=2$ 的解为','["$e^{2x}-1$","$2e^{2x}-2$","$e^{2x}+1$","$2xe^{2x}$"]',4,'章节刷题 · 真题难度新题 · 可降阶的二阶微分方程',977);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('108bfe71-914e-5c63-9a71-33b2e0512496',0,'令 $v=y\\prime$，则 $v\\prime=2v$ 且 $v(0)=2$，得到 $v=2e^{2x}$；积分并用 $y(0)=0$ 得 $y=e^{2x}-1$。');
INSERT INTO question_point (revision_id,point_id) VALUES ('108bfe71-914e-5c63-9a71-33b2e0512496','43bd3197-7fc7-5153-9a6e-129e39bac68b');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('85d1f25e-1ba6-5175-8ebe-d3d5d3528c17','afdac469-0fe4-5007-833c-51a71333967b','8c772590-817b-5b20-a874-31fff00ed3e5','legacy:00023:calculus-fresh-20260929-7','381f0f32560e80078e5935827e93ae73e12f1aa3c422bd08260cc5236ba7902a','calculus-fresh-20260929-7','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('af0b01cf-1209-5045-bc82-b69f77041010','1bc86e3e-2bed-580c-b005-ec4ef354da9b','85d1f25e-1ba6-5175-8ebe-d3d5d3528c17','级数 $\\sum_{n=1}^{\\infty}\\frac{(-1)^{n-1}}{n^p}$ 在何种条件下条件收敛？','["$p>1$","$0<p\\\\le1$","$p\\\\ge0$","$p\\\\le0$"]',4,'章节刷题 · 真题难度新题 · 绝对收敛与条件收敛',978);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('af0b01cf-1209-5045-bc82-b69f77041010',1,'交错级数在 $p>0$ 时由莱布尼兹判别法收敛；其绝对值级数仅在 $p>1$ 时收敛。');
INSERT INTO question_point (revision_id,point_id) VALUES ('af0b01cf-1209-5045-bc82-b69f77041010','a92060f3-ae88-5f78-bd15-22da8d3289b8');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('213688b4-c4f5-5b28-a632-5cf7bfb2a9e6','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-catalog-202609-0-1','83c67dfe74df46e47ca543a1600f9de0e1d334ec0f9b23b64b62fcdc06f18670','calculus-catalog-202609-0-1','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('aaa4206f-f388-5678-a32d-8b2866c7692e','1bc86e3e-2bed-580c-b005-ec4ef354da9b','213688b4-c4f5-5b28-a632-5cf7bfb2a9e6','设 f(x)=x³-3x²+2，则 f′(2) 为','["0","2","3","6"]',2,'目录考点新题 · 导数的运算',979);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('aaa4206f-f388-5678-a32d-8b2866c7692e',0,'f′(x)=3x²-6x，代入 x=2 得 0。');
INSERT INTO question_point (revision_id,point_id) VALUES ('aaa4206f-f388-5678-a32d-8b2866c7692e','ba6767ba-f756-53a6-a602-9262156b904b');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('d782cc3a-5e46-5592-9331-e78224a01ae5','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-catalog-202609-0-2','ae42683d3ebb3067a21a0bfa089323279ada0f0b447acd1c2e84198b3106947f','calculus-catalog-202609-0-2','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('e13aee81-eb2f-5faf-aba5-e23d0969d437','1bc86e3e-2bed-580c-b005-ec4ef354da9b','d782cc3a-5e46-5592-9331-e78224a01ae5','设 y=ln(1+x²)，则 y′(1) 为','["1/2","1","2","ln2"]',3,'目录考点新题 · 三类特殊函授求导',980);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('e13aee81-eb2f-5faf-aba5-e23d0969d437',1,'链式法则给出 y′=2x/(1+x²)，代入 1 得 1。');
INSERT INTO question_point (revision_id,point_id) VALUES ('e13aee81-eb2f-5faf-aba5-e23d0969d437','d55c0c4e-16c0-5f82-a8b1-2e802079cbb4');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('d1c7980f-6063-5e52-9fc1-47b6884e1a09','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-catalog-202609-0-3','dc4e3173608d83e6df5a75d801e13578456e19c679677ae06e10570ab1d4f726','calculus-catalog-202609-0-3','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('f9003941-0e40-51f9-8f05-b5edae9750a1','1bc86e3e-2bed-580c-b005-ec4ef354da9b','d1c7980f-6063-5e52-9fc1-47b6884e1a09','设 f(x)=x²eˣ，则 f″(0) 为','["1","2","3","4"]',3,'目录考点新题 · 高阶导数',981);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('f9003941-0e40-51f9-8f05-b5edae9750a1',1,'f′=eˣ(x²+2x)，f″=eˣ(x²+4x+2)，故 f″(0)=2。');
INSERT INTO question_point (revision_id,point_id) VALUES ('f9003941-0e40-51f9-8f05-b5edae9750a1','ed0aae71-bc31-5fdd-a8fa-5aabd03c1c37');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('5c6a95dc-b413-5972-9934-a4e6aa677769','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-catalog-202609-0-4','fdcae88dd99e48388f76d375405db1d4370aeccb0456f8981f9a0478162bb411','calculus-catalog-202609-0-4','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('75ac78f9-d84b-52ae-bca4-11d70e3c3a16','1bc86e3e-2bed-580c-b005-ec4ef354da9b','5c6a95dc-b413-5972-9934-a4e6aa677769','函数 y=x·ln x 在 x=1 处的微分 dy 为','["dx","2dx","0","ln x·dx"]',2,'目录考点新题 · 微分及其运算',982);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('75ac78f9-d84b-52ae-bca4-11d70e3c3a16',0,'dy=y′dx=(ln x+1)dx，x=1 时为 dx。');
INSERT INTO question_point (revision_id,point_id) VALUES ('75ac78f9-d84b-52ae-bca4-11d70e3c3a16','0e39226c-22ca-5b07-a316-66fbfa2e8782');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('cbf4fa48-11c7-5177-ae85-6542dd4cde71','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-catalog-202609-0-5','b7dd02aee20f458ba83802c5628b27fcdc078e5430b73cbc47bdc9069850a17d','calculus-catalog-202609-0-5','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('13050017-e057-5270-b233-22862a06e6a7','1bc86e3e-2bed-580c-b005-ec4ef354da9b','cbf4fa48-11c7-5177-ae85-6542dd4cde71','极限 lim(x→0)(eˣ-1-x)/x² 为','["0","1/2","1","2"]',3,'目录考点新题 · 洛必达法则',983);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('13050017-e057-5270-b233-22862a06e6a7',1,'两次应用洛必达法则，或用 eˣ 的展开式，极限为 1/2。');
