INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('8a2e4273-d3c8-5fc3-a58a-67b6767ecca1','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-catalog-202609-0-6','2e867bfd8803cae63f0e515c0eebcf52792137f026963e1cb1deadf4d314a929','calculus-catalog-202609-0-6','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('fec043e5-37bf-59d5-a9d6-332ceeb0a4ff','1bc86e3e-2bed-580c-b005-ec4ef354da9b','8a2e4273-d3c8-5fc3-a58a-67b6767ecca1','函数 f(x)=x³-3x 在区间 (0,2) 上的单调递减区间为','["(0,1)","(1,2)","(0,2)","不存在"]',3,'目录考点新题 · 函数的单调性',984);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('fec043e5-37bf-59d5-a9d6-332ceeb0a4ff',0,'f′(x)=3(x²-1)，在 0<x<1 时为负。');
INSERT INTO question_point (revision_id,point_id) VALUES ('fec043e5-37bf-59d5-a9d6-332ceeb0a4ff','d2ce333d-ed03-54f0-b8fa-d9aedc660ffa');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('6a1c5ce4-aafd-57b8-a12f-e964905a0e48','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-catalog-202609-0-7','8b57f47cd47b7ee09cdf4d62f93d4f957c00bc72f17bedb18a65700be9cce816','calculus-catalog-202609-0-7','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('3d7d6289-cf37-5c51-987d-d98e555c9872','1bc86e3e-2bed-580c-b005-ec4ef354da9b','6a1c5ce4-aafd-57b8-a12f-e964905a0e48','f(x)=x³-3x 在区间 [-2,2] 上的最大值为','["-2","0","2","4"]',3,'目录考点新题 · 函数的极值与最值',985);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('3d7d6289-cf37-5c51-987d-d98e555c9872',2,'比较端点与驻点：f(-2)=-2，f(-1)=2，f(1)=-2，f(2)=2。');
INSERT INTO question_point (revision_id,point_id) VALUES ('3d7d6289-cf37-5c51-987d-d98e555c9872','a40a916f-9913-50f1-9256-9b51d5d950da');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('176f9250-1cf8-5228-95c8-bd8966b727ea','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-catalog-202609-0-8','8938f6b16eb3735e3aa1856355c3447f2f8aa9c569fe701813b173bfe9fc8b23','calculus-catalog-202609-0-8','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('ecbf1da5-4211-5ee3-8dc7-75e0b396c569','1bc86e3e-2bed-580c-b005-ec4ef354da9b','176f9250-1cf8-5228-95c8-bd8966b727ea','若 F′(x)=2x/(1+x²)，则 F(x) 可取','["ln(1+x²)","(1+x²)²","arctan x","1/(1+x²)"]',2,'目录考点新题 · 原函数与不定积分',986);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('ecbf1da5-4211-5ee3-8dc7-75e0b396c569',0,'ln(1+x²) 的导数正好为 2x/(1+x²)。');
INSERT INTO question_point (revision_id,point_id) VALUES ('ecbf1da5-4211-5ee3-8dc7-75e0b396c569','8744fadd-fcb1-5683-b2f6-d855b870076a');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('f2e40ed5-155b-5e41-8e72-7a23ef116a5c','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-catalog-202609-0-9','dcfda4f77840f7ffbd5cccd368f1185df13defaf4b1220569f9859a192df772d','calculus-catalog-202609-0-9','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('1a71df73-8209-5a8f-8c47-45758f880623','1bc86e3e-2bed-580c-b005-ec4ef354da9b','f2e40ed5-155b-5e41-8e72-7a23ef116a5c','不定积分 ∫2x·cos(x²)dx 为','["sin(x²)+C","2sin(x²)+C","cos(x²)+C","x²sin(x²)+C"]',3,'目录考点新题 · 不定积分—换元法',987);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('1a71df73-8209-5a8f-8c47-45758f880623',0,'令 u=x²，du=2x dx，则积分为 ∫cos u du=sin u+C。');
