INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('5ed1ccd4-70cb-52d2-bd63-0879022760a7','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-catalog-202609-0-10','ea1b855158ad74c7ad98f628018095ebc245b50e0fdec414748bef0d035ab0cf','calculus-catalog-202609-0-10','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('548709ad-ba00-50b8-a9d9-16e6e2505767','1bc86e3e-2bed-580c-b005-ec4ef354da9b','5ed1ccd4-70cb-52d2-bd63-0879022760a7','不定积分 ∫x eˣ dx 为','["xeˣ+C","(x-1)eˣ+C","(x+1)eˣ+C","eˣ/x+C"]',3,'目录考点新题 · 不定积分—分部积分法',988);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('548709ad-ba00-50b8-a9d9-16e6e2505767',1,'分部积分：∫x eˣ dx=xeˣ-∫eˣdx=(x-1)eˣ+C。');
