INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('a5e0a25d-684b-5d20-a73a-5461c014b54a','1bc86e3e-2bed-580c-b005-ec4ef354da9b','8dbf19a9-0962-5a0d-b7fb-d413702e2db5','曲线 y=x² 与 x 轴在 0≤x≤2 间围成的面积为','["4/3","2","8/3","4"]',2,'目录考点新题 · 定积分的几何意义',989);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('a5e0a25d-684b-5d20-a73a-5461c014b54a',2,'面积是 ∫₀²x²dx=[x³/3]₀²=8/3。');
INSERT INTO question_point (revision_id,point_id) VALUES ('a5e0a25d-684b-5d20-a73a-5461c014b54a','08f61c06-b11a-59ed-a6d8-e2d8441bacc1');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('8740e247-cbeb-5042-8638-23d3402c52bb','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-catalog-202609-0-12','e15af6570118dba694679fb2297d4645e62d588c70a176179a6e614b126348d9','calculus-catalog-202609-0-12','CHAPTER',0);
