INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('3c9ddd2f-1455-5c8e-9b93-982ef74fc27f',0,'由定积分保序性，0≤∫₀²f(x)dx≤∫₀²1dx=2。');
INSERT INTO question_point (revision_id,point_id) VALUES ('3c9ddd2f-1455-5c8e-9b93-982ef74fc27f','6aaba867-0db0-58b1-8205-6ec0ce42804f');
