INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('2efa21e8-d60e-5439-b979-65f16341771c','1bc86e3e-2bed-580c-b005-ec4ef354da9b','4b521aa9-c59b-5f26-ad2a-f2213ab2247e','设 F(x)=∫₁ˣ(t²+1)dt，则 F′(2) 为','["3","4","5","8"]',3,'目录考点新题 · 微积分基本定理',991);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('2efa21e8-d60e-5439-b979-65f16341771c',2,'微积分基本定理得 F′(x)=x²+1，故 F′(2)=5。');
