INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('3496896d-9d07-59db-b874-4647887e6fb2','1bc86e3e-2bed-580c-b005-ec4ef354da9b','4bde3623-2a04-5e42-918c-e586df329fb0','法向量分别为 (1,0,0) 与 (1,1,0) 的两平面所成锐角为','["30°","45°","60°","90°"]',3,'目录考点新题 · 平面与平面的夹角',1012);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('3496896d-9d07-59db-b874-4647887e6fb2',1,'两法向量夹角余弦为 1/√2，故锐二面角为 45°。');
INSERT INTO question_point (revision_id,point_id) VALUES ('3496896d-9d07-59db-b874-4647887e6fb2','a051f99e-0d39-501c-bc72-e98416367ecb');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('4ea724e9-dbf7-586a-9083-e19c88c794c4','afdac469-0fe4-5007-833c-51a71333967b','9f58c98e-82a0-51b9-8946-a297b17b7840','legacy:00023:calculus-catalog-202609-1-18','d36d4f8fab9a8479e17b3648277baf1da95218d53beb66d9da2f82a80a6fa90a','calculus-catalog-202609-1-18','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('c0dedefb-653a-5180-8b15-ab83ccf7b2ac','1bc86e3e-2bed-580c-b005-ec4ef354da9b','4ea724e9-dbf7-586a-9083-e19c88c794c4','平面 x-2y+z=1 与 2x-4y+2z=5 的关系为','["重合","平行不重合","垂直","斜交"]',3,'目录考点新题 · 平面与平面平行',1013);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('c0dedefb-653a-5180-8b15-ab83ccf7b2ac',1,'法向量成比例，但常数项不按相同比例，故平行而不重合。');
INSERT INTO question_point (revision_id,point_id) VALUES ('c0dedefb-653a-5180-8b15-ab83ccf7b2ac','4d491d53-515a-5737-99c6-3816c47f43a1');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('36f9ef06-bff4-520c-a0f0-050c4168c393','afdac469-0fe4-5007-833c-51a71333967b','9f58c98e-82a0-51b9-8946-a297b17b7840','legacy:00023:calculus-catalog-202609-1-19','d52819747b6802a3115be9aa0708c3fce9157c24b1e36ce3aed8367eeb20e853','calculus-catalog-202609-1-19','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('4d5aa74f-b059-5384-8eb7-2095d282ad72','1bc86e3e-2bed-580c-b005-ec4ef354da9b','36f9ef06-bff4-520c-a0f0-050c4168c393','曲线 x²+y²=4、z=0 绕 x 轴旋转一周所得曲面方程为','["x²+y²+z²=4","x²+z²=4","y²+z²=4","x²-y²-z²=4"]',4,'目录考点新题 · 曲线旋转成曲面',1014);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('4d5aa74f-b059-5384-8eb7-2095d282ad72',0,'旋转保留 x，原来的 y² 替换为 y²+z²，得到半径为 2 的球面。');
INSERT INTO question_point (revision_id,point_id) VALUES ('4d5aa74f-b059-5384-8eb7-2095d282ad72','5e691723-ff73-548e-973c-3823e2ffd29b');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('f6b450c3-9f7d-5bd8-994e-3840bba1413e','afdac469-0fe4-5007-833c-51a71333967b','32ec87c0-2e8e-5a8e-b45f-8bcf5ac63f59','legacy:00023:calculus-catalog-202609-2-1','6b652e610774f25dd4b9072656ec979426031d0bd4254c7a3b94c88129ba50e0','calculus-catalog-202609-2-1','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('0ebab1cf-1c14-522b-8cdd-d5190d901a7e','1bc86e3e-2bed-580c-b005-ec4ef354da9b','f6b450c3-9f7d-5bd8-994e-3840bba1413e','一元极限 lim(t→0)sin(3t)/t 为','["0","1","2","3"]',2,'目录考点新题 · 一元极限基础知识',1015);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('0ebab1cf-1c14-522b-8cdd-d5190d901a7e',3,'sin(3t)/(3t)→1，因此极限为 3。');
INSERT INTO question_point (revision_id,point_id) VALUES ('0ebab1cf-1c14-522b-8cdd-d5190d901a7e','8faaf4d8-de5e-58f3-a11f-b5b919b14bab');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('ded90e41-5fd3-5d08-a49f-2a6c086854d8','afdac469-0fe4-5007-833c-51a71333967b','32ec87c0-2e8e-5a8e-b45f-8bcf5ac63f59','legacy:00023:calculus-catalog-202609-2-2','01fdfabffeb27c927773f03f42c1dff7218be916c33521615eb9f1f3d6722def','calculus-catalog-202609-2-2','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('dc1dfb02-0731-5269-9e07-d72610d981d3','1bc86e3e-2bed-580c-b005-ec4ef354da9b','ded90e41-5fd3-5d08-a49f-2a6c086854d8','函数 z=ln(4-x²-y²) 的定义域为','["x²+y²<4","x²+y²≤4","x²+y²>4","所有实数点"]',3,'目录考点新题 · 二元函数的构造',1016);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('dc1dfb02-0731-5269-9e07-d72610d981d3',0,'对数真数必须大于 0，即 x²+y²<4。');
INSERT INTO question_point (revision_id,point_id) VALUES ('dc1dfb02-0731-5269-9e07-d72610d981d3','77d9e2ed-c3a6-52de-8da2-4b6d09ba6348');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('c96b31f2-6e23-57e6-af4e-58787f7b3e99','afdac469-0fe4-5007-833c-51a71333967b','32ec87c0-2e8e-5a8e-b45f-8bcf5ac63f59','legacy:00023:calculus-catalog-202609-2-3','ca3654970e52d0448eaea388bf648649204277ac32e5f831102a2abd7ea9e525','calculus-catalog-202609-2-3','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('85f491d6-465c-5564-b0cb-ed53e69157c8','1bc86e3e-2bed-580c-b005-ec4ef354da9b','c96b31f2-6e23-57e6-af4e-58787f7b3e99','极限 lim((x,y)→(0,0)) xy/(x²+y²)','["等于 0","等于 1/2","等于 1","不存在"]',4,'目录考点新题 · 二元求极限',1017);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('85f491d6-465c-5564-b0cb-ed53e69157c8',3,'沿 y=x 时值为 1/2，沿 y=-x 时为 -1/2，路径不同故不存在。');
INSERT INTO question_point (revision_id,point_id) VALUES ('85f491d6-465c-5564-b0cb-ed53e69157c8','756eb13b-24d3-5def-8397-66e1574e8e6c');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('a86ad388-fc9d-5430-bd71-77865c498548','afdac469-0fe4-5007-833c-51a71333967b','32ec87c0-2e8e-5a8e-b45f-8bcf5ac63f59','legacy:00023:calculus-catalog-202609-2-4','e2163d725ccbd63db101502d399ab198aa1826f4ba80ab2ca92b8f2432c6ecb8','calculus-catalog-202609-2-4','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('6bf9c238-a2a4-5b2c-9925-ffbfdeb65212','1bc86e3e-2bed-580c-b005-ec4ef354da9b','a86ad388-fc9d-5430-bd71-77865c498548','设 g(t)=t²eᵗ，则 g′(0) 为','["0","1","2","e"]',2,'目录考点新题 · 一元导数基础知识',1018);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('6bf9c238-a2a4-5b2c-9925-ffbfdeb65212',0,'g′(t)=eᵗ(2t+t²)，代入 0 为 0。');
INSERT INTO question_point (revision_id,point_id) VALUES ('6bf9c238-a2a4-5b2c-9925-ffbfdeb65212','0e155512-a991-5d2d-8759-a21ac5ccf22d');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('10461ee5-89b3-5a65-97ca-c44a1f44141f','afdac469-0fe4-5007-833c-51a71333967b','32ec87c0-2e8e-5a8e-b45f-8bcf5ac63f59','legacy:00023:calculus-catalog-202609-2-5','4250ed474e28c09fc6bfa51d5bbb75d545ffc67ffbaf3364121d36293a063533','calculus-catalog-202609-2-5','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('c1bdd303-6a94-5625-92b5-abbe962de6a9','1bc86e3e-2bed-580c-b005-ec4ef354da9b','10461ee5-89b3-5a65-97ca-c44a1f44141f','若 z=x²y+xy²，则 ∂z/∂x 在 (1,2) 处为','["4","6","8","10"]',3,'目录考点新题 · 显函数求偏导',1019);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('c1bdd303-6a94-5625-92b5-abbe962de6a9',2,'zₓ=2xy+y²，在 (1,2) 处为 4+4=8。');
INSERT INTO question_point (revision_id,point_id) VALUES ('c1bdd303-6a94-5625-92b5-abbe962de6a9','33a5e46c-ac34-569d-94b9-1055c0d93ccd');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('22114925-45ff-56e2-bdc3-28d6f65fb970','afdac469-0fe4-5007-833c-51a71333967b','32ec87c0-2e8e-5a8e-b45f-8bcf5ac63f59','legacy:00023:calculus-catalog-202609-2-6','dcbefdfbaf926eb434a617dab33613603897fd0c5de2a27117593fb2cdbdfeea','calculus-catalog-202609-2-6','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('17ddbaac-a174-5a2c-8f19-b7d66e831225','1bc86e3e-2bed-580c-b005-ec4ef354da9b','22114925-45ff-56e2-bdc3-28d6f65fb970','若 x²+y²+z²=6，则 ∂z/∂x 在 (1,1,2) 处为','["-1","-1/2","1/2","1"]',3,'目录考点新题 · 隐函数求偏导之公式法',1020);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('17ddbaac-a174-5a2c-8f19-b7d66e831225',1,'对 x 求偏导得 2x+2z zₓ=0，故 zₓ=-x/z=-1/2。');
INSERT INTO question_point (revision_id,point_id) VALUES ('17ddbaac-a174-5a2c-8f19-b7d66e831225','2a303894-0722-55e0-90d7-644b2acc0f88');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('14dbe4d0-22ad-59d6-856c-0e4045350875','afdac469-0fe4-5007-833c-51a71333967b','32ec87c0-2e8e-5a8e-b45f-8bcf5ac63f59','legacy:00023:calculus-catalog-202609-2-7','9e32d38e59a1dea4efbdb1a7d87d900040dc0a5cfa7b0c19ffd1c2082a453779','calculus-catalog-202609-2-7','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('95ba9fd2-6f58-5d54-b858-a97f92c26a33','1bc86e3e-2bed-580c-b005-ec4ef354da9b','14dbe4d0-22ad-59d6-856c-0e4045350875','由 e^(z+xy)+z²=e 在点 (1,1,0) 附近确定 z=z(x,y)，则 zₓ 在该点为','["-1","0","1","-e"]',4,'目录考点新题 · 隐函数求偏导之复合法',1021);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('95ba9fd2-6f58-5d54-b858-a97f92c26a33',0,'对 x 隐式求导：e^(z+xy)(zₓ+y)+2zzₓ=0；代入 (1,1,0) 得 e(zₓ+1)=0，故 zₓ=-1。');
INSERT INTO question_point (revision_id,point_id) VALUES ('95ba9fd2-6f58-5d54-b858-a97f92c26a33','1484e9ad-64aa-509e-84d6-23a5b470e5f3');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('e2dd412a-f60e-5cd8-95f5-572eb4a5e476','afdac469-0fe4-5007-833c-51a71333967b','32ec87c0-2e8e-5a8e-b45f-8bcf5ac63f59','legacy:00023:calculus-catalog-202609-2-8','e326ffacfcfea05755bd04d5752eb61ad4dfe5791192d98373b45e8e872bb039','calculus-catalog-202609-2-8','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('a0b23a64-9b7c-54b9-8ac4-6437dfdf9caa','1bc86e3e-2bed-580c-b005-ec4ef354da9b','e2dd412a-f60e-5cd8-95f5-572eb4a5e476','函数 f(x,y)=x²y/(x²+y²)（原点定义为 0）在原点','["连续但不可微","不连续","极限为 1","只有沿 x 轴连续"]',4,'目录考点新题 · 二元连续和可导',1022);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('a0b23a64-9b7c-54b9-8ac4-6437dfdf9caa',0,'|f(x,y)|≤|y|，故连续；两个偏导均为 0，但沿 y=x 有 f(t,t)=t/2，故不可微。');
INSERT INTO question_point (revision_id,point_id) VALUES ('a0b23a64-9b7c-54b9-8ac4-6437dfdf9caa','31463a7a-07a8-5f3f-8635-ddb078f4aa7b');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('84cc099f-5d5a-5a1a-bfdf-db7110b4e82b','afdac469-0fe4-5007-833c-51a71333967b','32ec87c0-2e8e-5a8e-b45f-8bcf5ac63f59','legacy:00023:calculus-catalog-202609-2-9','403fd1f1f72b16a3ab81d7fac2b9471a7ec1d50f86b4f901902af975f62938a4','calculus-catalog-202609-2-9','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('b2619c50-d4c5-5099-84e9-c61d7c5a6851','1bc86e3e-2bed-580c-b005-ec4ef354da9b','84cc099f-5d5a-5a1a-bfdf-db7110b4e82b','若 z=x²y+eʸ，则 dz 在 (1,0) 处为','["dx+dy","2dy","2dx+dy","2dx+2dy"]',3,'目录考点新题 · 求全微分',1023);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('b2619c50-d4c5-5099-84e9-c61d7c5a6851',1,'zₓ=2xy=0，zᵧ=x²+eʸ=2，因此 dz=2dy。');
INSERT INTO question_point (revision_id,point_id) VALUES ('b2619c50-d4c5-5099-84e9-c61d7c5a6851','3418de8b-3f56-5e56-9b99-6a1e00789319');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('4edb9350-cfd2-53d2-9f6b-1f4ca2b684d1','afdac469-0fe4-5007-833c-51a71333967b','32ec87c0-2e8e-5a8e-b45f-8bcf5ac63f59','legacy:00023:calculus-catalog-202609-2-10','78a1d417bc51006564753d6b911096dfdf839fe60744333ddfa4bd8f0b1848ac','calculus-catalog-202609-2-10','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('dbfef8f5-98b2-514f-b407-2c119f83f588','1bc86e3e-2bed-580c-b005-ec4ef354da9b','4edb9350-cfd2-53d2-9f6b-1f4ca2b684d1','若 dz=(2x+y)dx+(x+2y)dy，则 z 可取','["x²+xy+y²","2x²+xy+2y²","x²+y²","xy"]',3,'目录考点新题 · 求全微分的原函数',1024);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('dbfef8f5-98b2-514f-b407-2c119f83f588',0,'分别对 x、y 求偏导，x²+xy+y² 与给定全微分一致。');
INSERT INTO question_point (revision_id,point_id) VALUES ('dbfef8f5-98b2-514f-b407-2c119f83f588','4249c7ec-574a-5b22-96d8-ac081265ae68');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('9e77b02e-2580-5cb3-8393-14dd39b976b4','afdac469-0fe4-5007-833c-51a71333967b','32ec87c0-2e8e-5a8e-b45f-8bcf5ac63f59','legacy:00023:calculus-catalog-202609-2-11','1f14d7613ff7486249e8159a05b203cdf0d839cba3c4e088dde44fe6ce87a4c1','calculus-catalog-202609-2-11','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('9fcc09ae-eac1-5405-aeed-50823a78a87b','1bc86e3e-2bed-580c-b005-ec4ef354da9b','9e77b02e-2580-5cb3-8393-14dd39b976b4','函数 z=x²y³ 的两个混合偏导 zₓᵧ 与 zᵧₓ 均为','["3xy²","6xy²","6x²y","2xy³"]',3,'目录考点新题 · 二阶偏导次序无关',1025);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('9fcc09ae-eac1-5405-aeed-50823a78a87b',1,'先对 x 再对 y 或反序求导，均得到 6xy²。');
INSERT INTO question_point (revision_id,point_id) VALUES ('9fcc09ae-eac1-5405-aeed-50823a78a87b','8e5c7bb8-5dc6-55af-9c6f-7864c994bc41');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('288b36cb-7aa4-573b-b2a9-c5608813ae34','afdac469-0fe4-5007-833c-51a71333967b','32ec87c0-2e8e-5a8e-b45f-8bcf5ac63f59','legacy:00023:calculus-catalog-202609-2-12','2a69f5f0b12ac9efe7f4dad523c8f7093d61fcd6b37fc89de8d2ab56d23bdd72','calculus-catalog-202609-2-12','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('429810be-5b42-583c-9689-631f38cd9cd7','1bc86e3e-2bed-580c-b005-ec4ef354da9b','288b36cb-7aa4-573b-b2a9-c5608813ae34','函数 f(x,y)=x²+y²-2x+4y 的唯一极小值点为','["(1,-2)","(-1,2)","(1,2)","(-1,-2)"]',3,'目录考点新题 · 二元函数的极值',1026);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('429810be-5b42-583c-9689-631f38cd9cd7',0,'配方 f=(x-1)²+(y+2)²-5，极小值点为 (1,-2)。');
INSERT INTO question_point (revision_id,point_id) VALUES ('429810be-5b42-583c-9689-631f38cd9cd7','da611562-600d-56a1-867b-df66fcec291b');
