INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('0473e4e3-9126-5376-972d-baf9a59e8e4b','afdac469-0fe4-5007-833c-51a71333967b','32ec87c0-2e8e-5a8e-b45f-8bcf5ac63f59','legacy:00023:calculus-catalog-202609-2-14','b8dcd96c14e1dbd3443d6c4b4f67d01bcf2b3cac3b8bcc8523cd92f6734c9393','calculus-catalog-202609-2-14','CHAPTER',0);
