INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('47eb7dfd-a7a6-5581-b1cc-a3987538a702','1bc86e3e-2bed-580c-b005-ec4ef354da9b','7ada4613-10b5-5ce4-8523-4af0903b1f35','f(x,y)=x²y+3y² 在点 (1,1) 处的梯度为','["(2,7)","(2,6)","(1,7)","(7,2)"]',3,'目录考点新题 · 求梯度',1031);
