INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('6ae299dd-ddd4-5808-b650-b95354aed383','afdac469-0fe4-5007-833c-51a71333967b','e7742ada-e08b-5e92-a4db-cedfa4d5c8c1','legacy:00023:calculus-catalog-202609-3-1','6fe14ec2ede30d0de5f08daf6bf988632545d68a418eee35da75fa8de8b076bf','calculus-catalog-202609-3-1','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('7b3a25e2-3eb0-5c81-ab8f-aeeb021112d7','1bc86e3e-2bed-580c-b005-ec4ef354da9b','6ae299dd-ddd4-5808-b650-b95354aed383','一元定积分 ∫₀²(2x+1)dx 为','["4","5","6","8"]',2,'目录考点新题 · 一元积分基础知识',1032);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('7b3a25e2-3eb0-5c81-ab8f-aeeb021112d7',2,'原函数为 x²+x，代入 2 与 0 得 6。');
