INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('0ea2894c-3880-52db-abb8-d30576b49117','afdac469-0fe4-5007-833c-51a71333967b','e7742ada-e08b-5e92-a4db-cedfa4d5c8c1','legacy:00023:calculus-catalog-202609-3-2','ced9c41cf4cc569696d0500c755c43f274cb03c54baaea208e145e7dfa46fe37','calculus-catalog-202609-3-2','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('8968f621-58bb-5b96-b790-30c65b0f40b4','1bc86e3e-2bed-580c-b005-ec4ef354da9b','0ea2894c-3880-52db-abb8-d30576b49117','区域 D 为半径 3 的上半圆，求 ∬_D 1 dA','["9π","9π/2","3π","3π/2"]',3,'目录考点新题 · 几何意义求二重积分',1033);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('8968f621-58bb-5b96-b790-30c65b0f40b4',1,'积分等于区域面积，即半圆面积 π·3²/2=9π/2。');
INSERT INTO question_point (revision_id,point_id) VALUES ('8968f621-58bb-5b96-b790-30c65b0f40b4','13da0a42-04a6-581f-9987-f30729b20af8');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('0753d859-9296-51aa-b25b-dae877e461c9','afdac469-0fe4-5007-833c-51a71333967b','e7742ada-e08b-5e92-a4db-cedfa4d5c8c1','legacy:00023:calculus-catalog-202609-3-3','26b38889cb094fc2af5956ce426d4c8ca0773bb8b2c41290149de7e5fe2c3e52','calculus-catalog-202609-3-3','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('40213de6-5f1e-5062-b9e1-7d2efdd0f05e','1bc86e3e-2bed-580c-b005-ec4ef354da9b','0753d859-9296-51aa-b25b-dae877e461c9','若 D={(x,y):0≤x≤1,0≤y≤x}，则 ∬_D x dA 为','["1/6","1/3","1/2","1"]',3,'目录考点新题 · 直角坐标求二重积分',1034);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('40213de6-5f1e-5062-b9e1-7d2efdd0f05e',1,'先对 y 积分得 x²，再在 0 到 1 上积分得 1/3。');
INSERT INTO question_point (revision_id,point_id) VALUES ('40213de6-5f1e-5062-b9e1-7d2efdd0f05e','86dbd57d-2fd0-52e1-a863-2067ca02851c');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('10dc59dc-2ba6-51cb-8971-de8f2d31373d','afdac469-0fe4-5007-833c-51a71333967b','e7742ada-e08b-5e92-a4db-cedfa4d5c8c1','legacy:00023:calculus-catalog-202609-3-4','27601192b8eae58ed8c7bd2a7018e6b3f30c49b03e771fa1775825efc2ff0c5c','calculus-catalog-202609-3-4','CHAPTER',0);
