INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('5bee194f-b4a9-54c8-988a-c21082d03d1e',1,'令 x=y=t，ds=√2dt，积分为 √2∫₀¹t dt=√2/2。');
