INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('1db44ed4-8d0f-5f9f-a68f-660beb360770',1,'圆周上 x²+y²=1，积分等于圆周长 2π。');
INSERT INTO question_point (revision_id,point_id) VALUES ('1db44ed4-8d0f-5f9f-a68f-660beb360770','644ef4a2-5765-5e48-bbe0-9c877b1e5abb');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('d35dfd66-c03c-5ce5-b6f1-094ad95167af','afdac469-0fe4-5007-833c-51a71333967b','9fc3a71b-4a89-5ce2-b14c-962058f7e5f7','legacy:00023:calculus-catalog-202609-4-3','505a98c812cad61e5acb84455fb3129d0cf023caf9e8f1f192d14c815e6f96a7','calculus-catalog-202609-4-3','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('aa9e37cf-db8e-54eb-b198-7c011220c27e','1bc86e3e-2bed-580c-b005-ec4ef354da9b','d35dfd66-c03c-5ce5-b6f1-094ad95167af','L 为直线段 (0,0)→(1,1)，则 ∫_L (x dy-y dx) 为','["-1","0","1","2"]',3,'目录考点新题 · 对坐标的曲线积分',1042);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('aa9e37cf-db8e-54eb-b198-7c011220c27e',1,'令 x=y=t，则 dx=dy=dt，积分核恒为 tdt-tdt=0。');
INSERT INTO question_point (revision_id,point_id) VALUES ('aa9e37cf-db8e-54eb-b198-7c011220c27e','e21e2b33-6e49-59a6-a8a2-2e309538a3cd');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('e3663a51-9a8b-5a4e-86a7-56997d134e07','afdac469-0fe4-5007-833c-51a71333967b','9fc3a71b-4a89-5ce2-b14c-962058f7e5f7','legacy:00023:calculus-catalog-202609-4-4','78d24afc7652fd1ad4afb818c09d93ccc33f216a3672a746240873174fadf146','calculus-catalog-202609-4-4','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('6ba71b5a-6196-5d51-bd11-c1f127d46fa6','1bc86e3e-2bed-580c-b005-ec4ef354da9b','e3663a51-9a8b-5a4e-86a7-56997d134e07','L 为单位圆正向边界，则 ∮_L (-y dx+x dy) 为','["0","π","2π","4π"]',4,'目录考点新题 · 对坐标的曲线积分之格林公式',1043);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('6ba71b5a-6196-5d51-bd11-c1f127d46fa6',2,'格林公式中 Qₓ-Pᵧ=1-(-1)=2，乘以圆盘面积 π 得 2π。');
INSERT INTO question_point (revision_id,point_id) VALUES ('6ba71b5a-6196-5d51-bd11-c1f127d46fa6','1275dbf7-cc28-5dfa-8d3e-5dc099b02959');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('00cc9de2-9bc3-5675-81db-11c1e6f47678','afdac469-0fe4-5007-833c-51a71333967b','9fc3a71b-4a89-5ce2-b14c-962058f7e5f7','legacy:00023:calculus-catalog-202609-4-5','777393659a14c212b9e07254705467232e058ddc6a29517495f26dc20e70b64e','calculus-catalog-202609-4-5','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('201f8c99-7690-5f66-b60e-547ee2576fd4','1bc86e3e-2bed-580c-b005-ec4ef354da9b','00cc9de2-9bc3-5675-81db-11c1e6f47678','球面 x²+y²+z²=1 的外向通量 ∬_S (x,y,z)·n dS 为','["0","4π/3","4π","8π"]',4,'目录考点新题 · 曲面积分',1044);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('201f8c99-7690-5f66-b60e-547ee2576fd4',2,'散度为 3，单位球体体积为 4π/3，由高斯公式得 4π。');
INSERT INTO question_point (revision_id,point_id) VALUES ('201f8c99-7690-5f66-b60e-547ee2576fd4','983d19b2-46f6-57c9-8e12-666e4f58b4fa');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('d387bba4-d0fb-537c-a863-6b0c736f34c5','afdac469-0fe4-5007-833c-51a71333967b','7f2ef968-dd1d-56f8-ac00-158b51f9ac0a','legacy:00023:calculus-catalog-202609-5-1','5587f62c5fc3847aa39b2fb969af4fa8076e90d01c0a998190ca79546923eab3','calculus-catalog-202609-5-1','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('0f723a6f-20c2-56f2-9ca4-fce0cd8cda3c','1bc86e3e-2bed-580c-b005-ec4ef354da9b','d387bba4-d0fb-537c-a863-6b0c736f34c5','方程 y′=2xy 且 y(0)=3 的特解为','["3eˣ","3eˣ²","3x²","3e⁻ˣ²"]',3,'目录考点新题 · 可分离变量微分方程',1045);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('0f723a6f-20c2-56f2-9ca4-fce0cd8cda3c',1,'分离变量：dy/y=2x dx，得 y=Ceˣ²；初值使 C=3。');
INSERT INTO question_point (revision_id,point_id) VALUES ('0f723a6f-20c2-56f2-9ca4-fce0cd8cda3c','e0a5403a-eea9-569f-b3bb-2d080d2f15fc');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('4b1b478d-bd56-5bd8-9c4a-200369483478','afdac469-0fe4-5007-833c-51a71333967b','7f2ef968-dd1d-56f8-ac00-158b51f9ac0a','legacy:00023:calculus-catalog-202609-5-2','b528d78ed8750538f848e723d56e6a7d5f59a0814eccc9f005b9d0e2c8a194b2','calculus-catalog-202609-5-2','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('d3e80e86-1580-59cb-bd9e-f26600742b4c','1bc86e3e-2bed-580c-b005-ec4ef354da9b','4b1b478d-bd56-5bd8-9c4a-200369483478','方程 y′+y=1 且 y(0)=0 的特解为','["1-e⁻ˣ","e⁻ˣ","1+e⁻ˣ","xe⁻ˣ"]',3,'目录考点新题 · 一阶线性微分方程',1046);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('d3e80e86-1580-59cb-bd9e-f26600742b4c',0,'通解 y=1+Ce⁻ˣ，代入初值 C=-1。');
INSERT INTO question_point (revision_id,point_id) VALUES ('d3e80e86-1580-59cb-bd9e-f26600742b4c','ad4f59b2-22d3-57ec-b44a-6d98b840e526');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('691105f7-0937-5da2-90d1-be30e5922735','afdac469-0fe4-5007-833c-51a71333967b','7f2ef968-dd1d-56f8-ac00-158b51f9ac0a','legacy:00023:calculus-catalog-202609-5-3','aec72288283d14924026cee89c1edd01ef87839019820c8860174845db192c14','calculus-catalog-202609-5-3','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('34049971-c7e9-58fe-91f8-0dd4de22c802','1bc86e3e-2bed-580c-b005-ec4ef354da9b','691105f7-0937-5da2-90d1-be30e5922735','方程 y‴=6 的通解包含几个任意常数？','["1","2","3","6"]',2,'目录考点新题 · 高阶微分方程',1047);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('34049971-c7e9-58fe-91f8-0dd4de22c802',2,'三阶微分方程积分三次，通解含 3 个独立任意常数。');
INSERT INTO question_point (revision_id,point_id) VALUES ('34049971-c7e9-58fe-91f8-0dd4de22c802','99bb200e-7bdd-54a9-b76f-96a0ca74cd54');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('2038d762-0a5c-5bff-b1d5-980881187f76','afdac469-0fe4-5007-833c-51a71333967b','7f2ef968-dd1d-56f8-ac00-158b51f9ac0a','legacy:00023:calculus-catalog-202609-5-4','79083a69914805bac30333a00bf60a4e430a027ca2a48530990c0e1ea2b050b6','calculus-catalog-202609-5-4','CHAPTER',0);
