INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('e0f95918-0ee9-516d-8363-2a532b217327','afdac469-0fe4-5007-833c-51a71333967b','7f2ef968-dd1d-56f8-ac00-158b51f9ac0a','legacy:00023:calculus-catalog-202609-5-5','3424e29a5dc0cc9273ddb886d1a47a26c2e7b60603d2f5767ddc2a308913402c','calculus-catalog-202609-5-5','CHAPTER',0);
