INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('ab63f56d-3da0-5120-bc26-d18532749a0b','afdac469-0fe4-5007-833c-51a71333967b','7f2ef968-dd1d-56f8-ac00-158b51f9ac0a','legacy:00023:calculus-catalog-202609-5-6','34b51848704f6fddaf0e43c765d5134ed7fd3d495421ad0e554fd153e5253da8','calculus-catalog-202609-5-6','CHAPTER',0);
