INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('e75da773-ed78-565c-8912-79f150062e42','afdac469-0fe4-5007-833c-51a71333967b','7f2ef968-dd1d-56f8-ac00-158b51f9ac0a','legacy:00023:calculus-catalog-202609-5-7','a4bba16de87a3eda53dacf57abd94abbf423b670bc72620bc08b24f10619ff03','calculus-catalog-202609-5-7','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('f73937c1-964b-57a0-a811-127b67b6209e','1bc86e3e-2bed-580c-b005-ec4ef354da9b','e75da773-ed78-565c-8912-79f150062e42','方程 y′+2y=0 且 y(0)=4 的特解在 x=1 处的值为','["4e⁻²","2e⁻²","4e²","4"]',3,'目录考点新题 · 微分方程的特解',1051);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('f73937c1-964b-57a0-a811-127b67b6209e',0,'通解为 Ce⁻²ˣ，初值 C=4，故 y(1)=4e⁻²。');
