INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('65a6ad90-c68d-5bff-a0d9-21a9d01fd6f6',1,'首项 1/4、公比 1/4，和为 (1/4)/(1-1/4)=1/3。');
