INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('51fad935-ddda-5bbb-bf4e-e92cc2e15efe',0,'正项 1/n 单调趋于 0，满足交错级数莱布尼茨判别条件。');
INSERT INTO question_point (revision_id,point_id) VALUES ('51fad935-ddda-5bbb-bf4e-e92cc2e15efe','06db195a-3b88-5f85-b679-7c88e08f49e2');
