INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('e481e194-06c9-531d-af3f-7f3ba4110293','afdac469-0fe4-5007-833c-51a71333967b','8c772590-817b-5b20-a874-31fff00ed3e5','legacy:00023:calculus-catalog-202609-6-9','d9927bfe7424b614238c9f0b327a3e27c40ee9bd9b5533dcb562d1b6e13a1560','calculus-catalog-202609-6-9','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('c286a4ea-80ef-56e2-9a62-0d4fdfaac7d4','1bc86e3e-2bed-580c-b005-ec4ef354da9b','e481e194-06c9-531d-af3f-7f3ba4110293','幂级数 ∑ₙ₌₀^∞(x-1)ⁿ/2ⁿ 的收敛半径为','["1/2","1","2","∞"]',3,'目录考点新题 · 幂级数收敛半径和收敛区间',1060);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('c286a4ea-80ef-56e2-9a62-0d4fdfaac7d4',2,'这是公比 (x-1)/2 的几何级数，收敛条件 |x-1|<2。');
