INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('652be2d7-71d1-5a0d-98f4-4e189492fd88','afdac469-0fe4-5007-833c-51a71333967b','8c772590-817b-5b20-a874-31fff00ed3e5','legacy:00023:calculus-catalog-202609-6-10','af0f8357e82e99d1f3bc7108b1ad528a93f1ec941c3c880070c34365c5ed4f99','calculus-catalog-202609-6-10','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('9e82b7ef-d054-5301-95a4-9b3daf836c6b','1bc86e3e-2bed-580c-b005-ec4ef354da9b','652be2d7-71d1-5a0d-98f4-4e189492fd88','幂级数 ∑ₙ₌₁^∞xⁿ/n 在 x=-1 与 x=1 处的收敛情况分别是','["都收敛","都发散","前者收敛、后者发散","前者发散、后者收敛"]',4,'目录考点新题 · 阿贝尔定理',1061);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('9e82b7ef-d054-5301-95a4-9b3daf836c6b',2,'x=-1 时为交错调和级数；x=1 时为调和级数。');
