INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('c7de627e-2f6e-56d9-9dbf-c89eb9486266','afdac469-0fe4-5007-833c-51a71333967b','8c772590-817b-5b20-a874-31fff00ed3e5','legacy:00023:calculus-catalog-202609-6-11','3f554b5c9af84ccc693a22c6e2f8adf680efc93e4d718bd16bd4ec8f3f710c98','calculus-catalog-202609-6-11','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('668ae525-fd08-5e8f-b4a1-24805c0aa89e','1bc86e3e-2bed-580c-b005-ec4ef354da9b','c7de627e-2f6e-56d9-9dbf-c89eb9486266','当 |x|<1 时，∑ₙ₌₁^∞ n xⁿ 的和为','["x/(1-x)","x/(1-x)²","1/(1-x)²","x²/(1-x)²"]',4,'目录考点新题 · 幂级数求和',1062);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('668ae525-fd08-5e8f-b4a1-24805c0aa89e',1,'对几何级数 ∑ₙ₌₀^∞xⁿ=1/(1-x) 求导，再乘 x。');
