INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('225afbcb-ec4d-50de-9de9-7b681e97e893','afdac469-0fe4-5007-833c-51a71333967b','8c772590-817b-5b20-a874-31fff00ed3e5','legacy:00023:calculus-catalog-202609-6-13','cba0b1b8181c7071b93bdec13efa461f2dbda9c29948d7238b1ba14fd03da025','calculus-catalog-202609-6-13','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('1890ac72-78ab-54fe-b9ca-1bed2dd94d27','1bc86e3e-2bed-580c-b005-ec4ef354da9b','225afbcb-ec4d-50de-9de9-7b681e97e893','若 f(x)=x 在 (-π,π) 上作傅里叶展开，则余弦系数 aₙ (n≥1) 为','["0","1/n","(-1)ⁿ/n","2/n"]',4,'目录考点新题 · 傅里叶系数',1064);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('1890ac72-78ab-54fe-b9ca-1bed2dd94d27',0,'x 是奇函数，余弦为偶函数，乘积在对称区间上的积分为 0。');
INSERT INTO question_point (revision_id,point_id) VALUES ('1890ac72-78ab-54fe-b9ca-1bed2dd94d27','f0531ec3-fd88-5f6e-8f69-9f74029a2d0c');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('c94cf2e6-d705-508c-812b-86359fce3590','afdac469-0fe4-5007-833c-51a71333967b','8c772590-817b-5b20-a874-31fff00ed3e5','legacy:00023:calculus-catalog-202609-6-14','2f9b23c9d76c936cd2689d01bbbf7e3011957c7ddf2a9b19513fdad7fbec95d1','calculus-catalog-202609-6-14','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('d1eb0400-18a7-5bd5-bb7c-10e1b271386e','1bc86e3e-2bed-580c-b005-ec4ef354da9b','c94cf2e6-d705-508c-812b-86359fce3590','正项级数满足 limsup(aₙ)^(1/n)=1/3，则级数','["收敛","发散","条件收敛","无法判定"]',4,'目录考点新题 · 根值审敛法',1065);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('d1eb0400-18a7-5bd5-bb7c-10e1b271386e',0,'根值判别法中上极限小于 1，故级数收敛。');
