INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('c61a0d32-6883-575f-b3d9-d7e05b81a45d','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-examlike-202609-01','003b6000b4334cbce42a922066cc8a85ccd344b41f02418ff2ee66330a103e26','calculus-examlike-202609-01','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('4f31d46b-2609-555a-a39e-91c0fe98765d','1bc86e3e-2bed-580c-b005-ec4ef354da9b','c61a0d32-6883-575f-b3d9-d7e05b81a45d','设 $f(x)=x^2e^{-x}$，则 $f(x)$ 在区间 $(0,+\\infty)$ 内的极大值为','["$e^{-1}$","$2e^{-2}$","$4e^{-2}$","$4e^{-1}$"]',3,'章节刷题 · 真题难度新题 · 复合函数求导',1066);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('4f31d46b-2609-555a-a39e-91c0fe98765d',2,'$f''(x)=e^{-x}(2x-x^2)=xe^{-x}(2-x)$，唯一极大值点为 $x=2$，故极大值为 $4e^{-2}$。');
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('f03a8930-d7e1-5924-ac24-645863cef473','1da6de03-1c89-524f-824a-35bc7bb191ca','复合函数求导','复合函数求导');
INSERT INTO release_point (release_id,chapter_id,point_id,title_snapshot) VALUES ('1bc86e3e-2bed-580c-b005-ec4ef354da9b','1da6de03-1c89-524f-824a-35bc7bb191ca','f03a8930-d7e1-5924-ac24-645863cef473','复合函数求导');
INSERT INTO question_point (revision_id,point_id) VALUES ('4f31d46b-2609-555a-a39e-91c0fe98765d','f03a8930-d7e1-5924-ac24-645863cef473');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('252d2484-ac36-5b80-953f-13d4adbf2e2f','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-examlike-202609-02','64d7d93a306b1a828f0977ada6faf4421a709ca95436bfe75d4f08635c2ed143','calculus-examlike-202609-02','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('3555528a-efb9-5c0d-ac5a-eeccdb1c3127','1bc86e3e-2bed-580c-b005-ec4ef354da9b','252d2484-ac36-5b80-953f-13d4adbf2e2f','设 $f(x)$ 在 $[-1,1]$ 上连续，且 $f(x)+f(-x)=2x^2$，则 $\\int_{-1}^{1}f(x)\\,dx=$','["$0$","$\\\\frac23$","$\\\\frac43$","$2$"]',3,'章节刷题 · 真题难度新题 · 定积分',1067);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('3555528a-efb9-5c0d-ac5a-eeccdb1c3127',1,'对等式在 $[-1,1]$ 上积分。左右两项积分相等，故 $2\\int_{-1}^1f(x)dx=\\int_{-1}^12x^2dx=4/3$，所求为 $2/3$。');
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('d0a7bb0d-9fd2-5286-a8c2-fd26ab171c0a','1da6de03-1c89-524f-824a-35bc7bb191ca','定积分','定积分');
INSERT INTO release_point (release_id,chapter_id,point_id,title_snapshot) VALUES ('1bc86e3e-2bed-580c-b005-ec4ef354da9b','1da6de03-1c89-524f-824a-35bc7bb191ca','d0a7bb0d-9fd2-5286-a8c2-fd26ab171c0a','定积分');
INSERT INTO question_point (revision_id,point_id) VALUES ('3555528a-efb9-5c0d-ac5a-eeccdb1c3127','d0a7bb0d-9fd2-5286-a8c2-fd26ab171c0a');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('dc803b4f-c504-55ab-97d4-c2118612f42d','afdac469-0fe4-5007-833c-51a71333967b','9f58c98e-82a0-51b9-8946-a297b17b7840','legacy:00023:calculus-examlike-202609-03','cc4d15e8e98722d3ad1f47fb4d307a022985cafac480eadb03f41b7e2453716e','calculus-examlike-202609-03','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('6e626323-e511-573f-9926-66ba8e6f98e7','1bc86e3e-2bed-580c-b005-ec4ef354da9b','dc803b4f-c504-55ab-97d4-c2118612f42d','直线 $L:\\frac{x-1}{2}=\\frac{y+1}{-1}=\\frac{z}{2}$ 与平面 $x+2y-z+3=0$ 的位置关系是','["直线在平面内","直线与平面平行但不在平面内","直线与平面垂直","直线与平面斜交"]',3,'章节刷题 · 真题难度新题 · 向量与平面',1068);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('6e626323-e511-573f-9926-66ba8e6f98e7',3,'直线方向向量 $(2,-1,2)$ 与平面法向量 $(1,2,-1)$ 点积为 $2-2-2=-2$，不为 0，故应为斜交。');
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('9e5debf3-2819-5e1c-8a96-c3c6bcf25abb','9f58c98e-82a0-51b9-8946-a297b17b7840','向量与平面','向量与平面');
