INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('807ced70-6c31-5f94-aeaa-c8c61ab7d881','afdac469-0fe4-5007-833c-51a71333967b','9f58c98e-82a0-51b9-8946-a297b17b7840','legacy:00023:calculus-examlike-202609-04','52306420f4996edd5e92171dda5d3b537bb2710f2b80799168be7f32af4a9c84','calculus-examlike-202609-04','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('f3fceacf-c20a-5b73-81cd-3ea90c3b4680','1bc86e3e-2bed-580c-b005-ec4ef354da9b','807ced70-6c31-5f94-aeaa-c8c61ab7d881','点 $P(2,-1,3)$ 到平面 $2x-y+2z-5=0$ 的距离为','["$1$","$2$","$3$","$6$"]',3,'章节刷题 · 真题难度新题 · 点到平面距离',1069);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('f3fceacf-c20a-5b73-81cd-3ea90c3b4680',1,'代入点到平面距离公式，分子为 $|2\\times2-(-1)+2\\times3-5|=6$，分母为 $\\sqrt{2^2+(-1)^2+2^2}=3$，故距离为 2。');
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('0e094171-854d-58cc-9050-4434bfd9d6ee','9f58c98e-82a0-51b9-8946-a297b17b7840','点到平面距离','点到平面距离');
