INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('06be5dc3-13cc-52a9-8c59-ec44d38f73a5','1bc86e3e-2bed-580c-b005-ec4ef354da9b','814e68b6-8299-543e-95a0-8f118e0d863d','设 $z=xe^{xy}$，则 $dz$ 在点 $(1,0)$ 处为','["$dx+dy$","$dx+2dy$","$2dx+dy$","$e(dx+dy)$"]',3,'章节刷题 · 真题难度新题 · 全微分',1070);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('06be5dc3-13cc-52a9-8c59-ec44d38f73a5',0,'$z_x=e^{xy}(1+xy)$，$z_y=x^2e^{xy}$；在 $(1,0)$ 处均为 1，故 $dz=dx+dy$。');
