INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('37611572-f73e-59ed-bfdf-a90cf4a4e71c','1bc86e3e-2bed-580c-b005-ec4ef354da9b','636579a3-c565-5dcb-aa3a-778b968f8b9e','在约束 $x+y=1$ 下，函数 $x^2+y^2$ 的最小值为','["$0$","$\\\\frac14$","$\\\\frac12$","$1$"]',4,'章节刷题 · 真题难度新题 · 条件极值',1071);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('37611572-f73e-59ed-bfdf-a90cf4a4e71c',2,'由柯西不等式 $(x+y)^2\\le2(x^2+y^2)$，得 $x^2+y^2\\ge1/2$，在 $x=y=1/2$ 时取等号。');
