INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('d30ac68f-9440-56c0-8cf7-953aec90292d','1bc86e3e-2bed-580c-b005-ec4ef354da9b','5626ae94-76d4-5c57-9800-3d473bd8e99a','积分 $\\int_0^1dx\\int_x^1 f(x,y)dy$ 交换积分次序后为','["$\\\\int_0^1dy\\\\int_0^y f(x,y)dx$","$\\\\int_0^1dy\\\\int_y^1 f(x,y)dx$","$\\\\int_0^1dy\\\\int_0^1 f(x,y)dx$","$\\\\int_0^1dy\\\\int_0^{1-y} f(x,y)dx$"]',4,'章节刷题 · 真题难度新题 · 交换积分次序',1072);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('d30ac68f-9440-56c0-8cf7-953aec90292d',0,'积分区域为 $0\\le x\\le y\\le1$；固定 $y$ 后，$x$ 从 0 到 $y$。');
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('8bcb8437-6e74-591b-8a19-585fa1f607bc','e7742ada-e08b-5e92-a4db-cedfa4d5c8c1','交换积分次序','交换积分次序');
