INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('9156d1a5-26da-5cd2-b4ae-00d9dd3138fd','afdac469-0fe4-5007-833c-51a71333967b','e7742ada-e08b-5e92-a4db-cedfa4d5c8c1','legacy:00023:calculus-examlike-202609-08','1649aed4c4c41d1bf042e0633765d9acc578dcd2654b9d3adda9de658b4a4e4e','calculus-examlike-202609-08','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('32a5e065-4425-5be4-bad9-edc00fba4ae2','1bc86e3e-2bed-580c-b005-ec4ef354da9b','9156d1a5-26da-5cd2-b4ae-00d9dd3138fd','设 $\\Omega:x^2+y^2+z^2\\le1$，则 $\\iiint_\\Omega(x^2+y^2+z^2)\\,dV=$','["$\\\\frac{4\\\\pi}{15}$","$\\\\frac{4\\\\pi}{5}$","$\\\\frac{3\\\\pi}{5}$","$\\\\frac{4\\\\pi}{3}$"]',3,'章节刷题 · 真题难度新题 · 三重积分对称性',1073);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('32a5e065-4425-5be4-bad9-edc00fba4ae2',1,'用球坐标，积分为 $\\int_0^{2\\pi}d\\theta\\int_0^\\pi\\sin\\varphi d\\varphi\\int_0^1r^4dr=4\\pi/5$。');
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('f7b3b5fa-e362-50e7-9c67-9ad67c9b3716','e7742ada-e08b-5e92-a4db-cedfa4d5c8c1','三重积分对称性','三重积分对称性');
