INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('f88f854c-679f-570f-9e6b-c51ba846d6e0','afdac469-0fe4-5007-833c-51a71333967b','9fc3a71b-4a89-5ce2-b14c-962058f7e5f7','legacy:00023:calculus-examlike-202609-09','142f4c35f1253b94bce444e6339f740fe7da363f2a101cd95ea0b25b1fd6172d','calculus-examlike-202609-09','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('8f3ad7dd-9460-5614-8cfe-3a54516884f7','1bc86e3e-2bed-580c-b005-ec4ef354da9b','f88f854c-679f-570f-9e6b-c51ba846d6e0','$L$ 为单位圆 $x^2+y^2=1$ 的正向，则 $\\oint_L(-y\\,dx+x\\,dy)=$','["$0$","$\\\\pi$","$2\\\\pi$","$4\\\\pi$"]',4,'章节刷题 · 真题难度新题 · 第二类曲线积分',1074);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('8f3ad7dd-9460-5614-8cfe-3a54516884f7',2,'由格林公式，$\\partial Q/\\partial x-\\partial P/\\partial y=1-(-1)=2$，故积分为单位圆面积的 2 倍，即 $2\\pi$。');
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('63005fb7-b5cb-51b3-9c3f-45233c15f0e5','9fc3a71b-4a89-5ce2-b14c-962058f7e5f7','第二类曲线积分','第二类曲线积分');
INSERT INTO release_point (release_id,chapter_id,point_id,title_snapshot) VALUES ('1bc86e3e-2bed-580c-b005-ec4ef354da9b','9fc3a71b-4a89-5ce2-b14c-962058f7e5f7','63005fb7-b5cb-51b3-9c3f-45233c15f0e5','第二类曲线积分');
INSERT INTO question_point (revision_id,point_id) VALUES ('8f3ad7dd-9460-5614-8cfe-3a54516884f7','63005fb7-b5cb-51b3-9c3f-45233c15f0e5');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('4a46cf6e-c53e-5955-a75b-10b6bb73f1b4','afdac469-0fe4-5007-833c-51a71333967b','9fc3a71b-4a89-5ce2-b14c-962058f7e5f7','legacy:00023:calculus-examlike-202609-10','2fc443268d03ce1b951550daca144cdfcaf69437e8383aced7fb0af8abee164e','calculus-examlike-202609-10','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('851c29b0-0648-50d4-a66a-7971432b7ac1','1bc86e3e-2bed-580c-b005-ec4ef354da9b','4a46cf6e-c53e-5955-a75b-10b6bb73f1b4','球面 $x^2+y^2+z^2=4$ 的外侧上，$\\iint_S(x,y,z)\\cdot\\mathbf n\\,dS=$','["$8\\\\pi$","$16\\\\pi$","$24\\\\pi$","$32\\\\pi$"]',3,'章节刷题 · 真题难度新题 · 曲面积分',1075);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('851c29b0-0648-50d4-a66a-7971432b7ac1',3,'散度为 3，球体体积为 $32\\pi/3$，由高斯公式通量为 $3\\times32\\pi/3=32\\pi$。');
INSERT INTO question_point (revision_id,point_id) VALUES ('851c29b0-0648-50d4-a66a-7971432b7ac1','983d19b2-46f6-57c9-8e12-666e4f58b4fa');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('dd763d81-f558-5059-a283-b5fcbcab32e2','afdac469-0fe4-5007-833c-51a71333967b','7f2ef968-dd1d-56f8-ac00-158b51f9ac0a','legacy:00023:calculus-examlike-202609-11','61548d294cda1c0b188748d6d8f470d16e98fa512b9219ece7f07398bc1b8b94','calculus-examlike-202609-11','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('28da0a3c-50a8-5e4a-8a42-d87e6790520e','1bc86e3e-2bed-580c-b005-ec4ef354da9b','dd763d81-f558-5059-a283-b5fcbcab32e2','方程 $y''-y=e^x$ 满足 $y(0)=1$ 的特解是','["$e^x$","$(x+1)e^x$","$(x-1)e^x$","$xe^x+1$"]',3,'章节刷题 · 真题难度新题 · 一阶线性方程',1076);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('28da0a3c-50a8-5e4a-8a42-d87e6790520e',1,'乘以积分因子 $e^{-x}$，得 $(e^{-x}y)''=1$，所以 $y=(x+C)e^x$；由初值得 $C=1$。');
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('c6ae8b37-1da5-5f41-ae07-a1ca52807b1b','7f2ef968-dd1d-56f8-ac00-158b51f9ac0a','一阶线性方程','一阶线性方程');
