INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('a7798cd6-556b-5a1d-92fd-57c85709ccfd','1bc86e3e-2bed-580c-b005-ec4ef354da9b','e543358b-a6a5-5727-b368-2d8f8c95e9f1','微分方程 $y''''-2y''+y=e^x$ 的一个特解可设为','["$Ae^x$","$Axe^x$","$Ax^2e^x$","$A$"]',4,'章节刷题 · 真题难度新题 · 二阶常系数方程',1077);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('a7798cd6-556b-5a1d-92fd-57c85709ccfd',2,'特征方程 $(r-1)^2=0$，右端指数 1 是二重特征根，试探式需乘 $x^2$，故设 $Ax^2e^x$。');
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('85b92446-da48-57a0-8d62-c81aa3e348e6','7f2ef968-dd1d-56f8-ac00-158b51f9ac0a','二阶常系数方程','二阶常系数方程');
