INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('70939912-35d6-593f-8a72-952e1786e62d','1bc86e3e-2bed-580c-b005-ec4ef354da9b','73ce21a5-acb5-58de-8057-6b1e09fe901b','幂级数 $\\sum_{n=1}^{\\infty}\\frac{(x-2)^n}{n}$ 的收敛区间是','["$(1,3)$","$[1,3)$","$(1,3]$","$[1,3]$"]',4,'章节刷题 · 真题难度新题 · 幂级数收敛域',1078);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('70939912-35d6-593f-8a72-952e1786e62d',1,'收敛半径为 1。$x=1$ 时为交错调和级数，收敛；$x=3$ 时为调和级数，发散。');
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('19493bde-fcb2-5dce-80ff-6d51a808a34c','8c772590-817b-5b20-a874-31fff00ed3e5','幂级数收敛域','幂级数收敛域');
