INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('45f3406d-e73f-5fd3-8c24-a0e0e37662eb','1bc86e3e-2bed-580c-b005-ec4ef354da9b','8d754b23-e893-5a4a-9f92-40f4d7a8a7e7','级数 $\\sum_{n=1}^{\\infty}\\frac{n}{3^n}$ 的和为','["$\\\\frac12$","$\\\\frac34$","$1$","$\\\\frac32$"]',3,'章节刷题 · 真题难度新题 · 级数判敛',1079);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('45f3406d-e73f-5fd3-8c24-a0e0e37662eb',1,'由 $\\sum_{n=1}^\\infty nr^n=r/(1-r)^2$，取 $r=1/3$ 得 $(1/3)/(2/3)^2=3/4$。');
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('28911708-0e9f-5dc6-83a1-696b364687cb','8c772590-817b-5b20-a874-31fff00ed3e5','级数判敛','级数判敛');
