INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('fb0a9231-f228-5dce-a680-b95ff2457d4f','1bc86e3e-2bed-580c-b005-ec4ef354da9b','8c4c2202-29d8-57ea-a09a-0589c7b21abf','函数 $f(x)=x^3-2x+1$，则 $f''(2)=$','["6","8","10","12"]',1,'章节练习 · 导数',1080);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('fb0a9231-f228-5dce-a680-b95ff2457d4f',2,'$f''(x)=3x^2-2$，代入 $x=2$ 得 $12-2=10$。');
