INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('61ed1893-e793-5a82-97da-f3b097c76444','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-chapter-v1-2','6544de0b72957dc38b64b600b8863eecfa492485d9fb4be11c9faac1fed18dbb','calculus-chapter-v1-2','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('8e1af648-79fe-5fdf-94e1-e46213790f9f','1bc86e3e-2bed-580c-b005-ec4ef354da9b','61ed1893-e793-5a82-97da-f3b097c76444','设 $y=\\ln(1+x^2)$，则 $y''=$','["$\\\\frac{1}{1+x^2}$","$\\\\frac{2x}{1+x^2}$","$2x\\\\ln(1+x^2)$","$\\\\frac{2}{1+x^2}$"]',2,'章节练习 · 复合函数求导',1081);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('8e1af648-79fe-5fdf-94e1-e46213790f9f',1,'使用链式法则：外层对数的导数乘以内层 $1+x^2$ 的导数，得到 $2x/(1+x^2)$。');
INSERT INTO question_point (revision_id,point_id) VALUES ('8e1af648-79fe-5fdf-94e1-e46213790f9f','f03a8930-d7e1-5924-ac24-645863cef473');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('b3c7f9d4-c555-5437-a104-254173891b88','afdac469-0fe4-5007-833c-51a71333967b','1da6de03-1c89-524f-824a-35bc7bb191ca','legacy:00023:calculus-chapter-v1-3','a96ce09d5d02b3493716b03b5dfe9ba25a893669de117206d5434a12e1c3034c','calculus-chapter-v1-3','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('9b1d4c27-b768-5bd5-b3fe-d485d4aceb50','1bc86e3e-2bed-580c-b005-ec4ef354da9b','b3c7f9d4-c555-5437-a104-254173891b88','$\\int_0^1(3x^2+2x)\\,dx=$','["1","2","3","4"]',2,'章节练习 · 定积分',1082);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('9b1d4c27-b768-5bd5-b3fe-d485d4aceb50',1,'原函数为 $x^3+x^2$，在 0 到 1 上的增量为 $1+1=2$。');
INSERT INTO question_point (revision_id,point_id) VALUES ('9b1d4c27-b768-5bd5-b3fe-d485d4aceb50','d0a7bb0d-9fd2-5286-a8c2-fd26ab171c0a');
