INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('a850e6f9-289b-5de3-a54b-5465ce06fa8e','1bc86e3e-2bed-580c-b005-ec4ef354da9b','e08fceb9-4e6a-583d-babc-622048512e9a','设 $a=(1,0,0)$，$b=(0,2,0)$，则 $|a\\times b|=$','["0","1","2","4"]',2,'章节练习 · 向量叉积',1083);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('a850e6f9-289b-5de3-a54b-5465ce06fa8e',2,'两向量垂直，所以叉积模为 $|a||b|\\sin90^\\circ=1\\times2=2$。');
