INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('0d101798-753f-5ce6-855e-8a7c39145940','1bc86e3e-2bed-580c-b005-ec4ef354da9b','7ba7b774-c787-58c3-bc08-c1f064052375','平面 $x+2y-2z=3$ 与平面 $2x+4y-4z=1$ 的位置关系是','["相交但不垂直","垂直","平行但不重合","重合"]',3,'章节练习 · 平面方程',1084);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('0d101798-753f-5ce6-855e-8a7c39145940',2,'两个法向量成比例，但常数项不按同一比例，因此两平面平行且不重合。');
