INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('12ac61ba-6642-5176-baf5-d8f68480933d','afdac469-0fe4-5007-833c-51a71333967b','32ec87c0-2e8e-5a8e-b45f-8bcf5ac63f59','legacy:00023:calculus-chapter-v1-6','3ff91b083af3737b03d2c5c087cc4aa9f5824421f4e0cd89df99efd3668f8ac8','calculus-chapter-v1-6','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('6bbbb770-eb89-55f9-9c03-b9bdc7b19035','1bc86e3e-2bed-580c-b005-ec4ef354da9b','12ac61ba-6642-5176-baf5-d8f68480933d','设 $z=x^2e^y$，则 $\\frac{\\partial^2z}{\\partial x\\partial y}=$','["$xe^y$","$2xe^y$","$x^2e^y$","$2e^y$"]',2,'章节练习 · 偏导数',1085);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('6bbbb770-eb89-55f9-9c03-b9bdc7b19035',1,'先对 $y$ 求偏导得 $x^2e^y$，再对 $x$ 求导得 $2xe^y$。');
