INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('ff2b32f3-8a49-5da2-be62-140d847ad47f','1bc86e3e-2bed-580c-b005-ec4ef354da9b','cce21074-600c-54c4-b575-3d609a5d835d','函数 $f=x^2+y^2$ 在 $(1,2)$ 处沿单位向量 $(\\frac35,\\frac45)$ 的方向导数为','["2","$\\\\frac{14}{5}$","$\\\\frac{22}{5}$","5"]',4,'章节练习 · 方向导数',1086);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('ff2b32f3-8a49-5da2-be62-140d847ad47f',2,'梯度为 $\\nabla f=(2x,2y)$，在点 $(1,2)$ 处为 $(2,4)$，所以方向导数为 $(2,4)\\cdot(\\frac35,\\frac45)=\\frac{22}{5}$。');
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('628fc5a6-2832-573e-b473-40cc43974fd2','32ec87c0-2e8e-5a8e-b45f-8bcf5ac63f59','方向导数','方向导数');
