INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('47c96218-c0f2-5138-923a-3bdf75fb5c6c','1bc86e3e-2bed-580c-b005-ec4ef354da9b','069e95bd-301f-520e-8189-82fc90682d70','设 $D=[0,1]\\times[0,2]$，则 $\\iint_D(x+y)\\,dxdy=$','["2","3","4","6"]',2,'章节练习 · 二重积分',1087);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('47c96218-c0f2-5138-923a-3bdf75fb5c6c',1,'先对 $x$ 积分，再对 $y$ 积分：$\\int_0^2(1/2+y)dy=3$。');
