INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('7bd76886-3d64-534d-8297-f59b818c7d91','1bc86e3e-2bed-580c-b005-ec4ef354da9b','5bca7d28-e3e7-5cdf-a440-004c3f75b857','把二重积分化为极坐标时，面积元 $dxdy$ 应替换为','["$drd\\\\theta$","$r\\\\,drd\\\\theta$","$r^2\\\\,drd\\\\theta$","$\\\\frac1rdrd\\\\theta$"]',3,'章节练习 · 极坐标换元',1088);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('7bd76886-3d64-534d-8297-f59b818c7d91',1,'极坐标变换的雅可比行列式为 $r$，所以面积元为 $r\\,drd\\theta$。');
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('bc3f93e4-ecb1-5420-96cb-bd1fdff481af','e7742ada-e08b-5e92-a4db-cedfa4d5c8c1','极坐标换元','极坐标换元');
