INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('60467658-ce49-55f2-b26f-792048c31ba9','1bc86e3e-2bed-580c-b005-ec4ef354da9b','fb750cc3-e02c-592f-b3c1-fdcee58ec5ea','曲线 $L$ 为从 $(0,0)$ 到 $(1,1)$ 的直线段，则 $\\int_L(x+y)\\,ds=$','["1","$\\\\sqrt2$","2","$2\\\\sqrt2$"]',3,'章节练习 · 曲线积分',1089);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('60467658-ce49-55f2-b26f-792048c31ba9',1,'令 $x=y=t$，$0\\le t\\le1$，且 $ds=\\sqrt2dt$，积分为 $\\int_0^12t\\sqrt2dt=\\sqrt2$。');
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('122c1416-550f-5b47-a687-c44418a229d0','9fc3a71b-4a89-5ce2-b14c-962058f7e5f7','曲线积分','曲线积分');
