INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('7a0d68ef-dbe1-5572-9d2b-42b03d4b71c3','afdac469-0fe4-5007-833c-51a71333967b','7f2ef968-dd1d-56f8-ac00-158b51f9ac0a','legacy:00023:calculus-chapter-v1-11','1f0a3da5a15e54f9e0a31895e970304c294de6fe403455aeeb9f8a8170e71843','calculus-chapter-v1-11','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('992ad6ee-e08f-5465-a563-00b9d32ad2bb','1bc86e3e-2bed-580c-b005-ec4ef354da9b','7a0d68ef-dbe1-5572-9d2b-42b03d4b71c3','方程 $y''+y=e^{-x}$ 的通解为','["$y=(x+C)e^{-x}$","$y=Ce^{-x}+e^x$","$y=x+C$","$y=(x+C)e^x$"]',3,'章节练习 · 一阶线性方程',1090);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('992ad6ee-e08f-5465-a563-00b9d32ad2bb',0,'积分因子为 $e^x$，于是 $(e^xy)''=1$，积分得 $e^xy=x+C$。');
INSERT INTO question_point (revision_id,point_id) VALUES ('992ad6ee-e08f-5465-a563-00b9d32ad2bb','c6ae8b37-1da5-5f41-ae07-a1ca52807b1b');
