INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('f8fde29e-8106-5c2f-8a10-e86a145b415b','1bc86e3e-2bed-580c-b005-ec4ef354da9b','3250bdec-9d8f-5268-90ec-363e4f4f3d5f','下列级数绝对收敛的是','["$\\\\sum\\\\frac1n$","$\\\\sum\\\\frac{(-1)^n}{n}$","$\\\\sum\\\\frac{(-1)^n}{n^2}$","$\\\\sum1$"]',3,'章节练习 · 收敛判别',1091);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('f8fde29e-8106-5c2f-8a10-e86a145b415b',2,'取绝对值后为 $\\sum1/n^2$，这是指数大于 1 的 p 级数，因此收敛。');
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('b38e19df-1adb-535e-a9c3-25f725e9969f','8c772590-817b-5b20-a874-31fff00ed3e5','收敛判别','收敛判别');
