INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('88899dfd-5aa5-55e0-8a6d-c2a7a798b45e','afdac469-0fe4-5007-833c-51a71333967b','8c772590-817b-5b20-a874-31fff00ed3e5','legacy:00023:calculus-base-series-5','210f46d9ec157cebe831741b20cd790618131f71fb653b9501cd91c82f317919','calculus-base-series-5','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('c022a7bc-8cc8-570e-9edc-293de7c82f20','1bc86e3e-2bed-580c-b005-ec4ef354da9b','88899dfd-5aa5-55e0-8a6d-c2a7a798b45e','级数 $\\sum_{n=1}^{\\infty}(\\frac{1}{2})^n$ 的和为','["$\\\\frac{1}{1}$","$\\\\frac{2}{1}$","发散","$\\\\frac{1}{2}$"]',2,'章节题库 · 等比级数',1216);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('c022a7bc-8cc8-570e-9edc-293de7c82f20',0,'首项和公比都是 $1/2$，所以和为 $(1/2)/(1-1/2)=1/1$。');
INSERT INTO question_point (revision_id,point_id) VALUES ('c022a7bc-8cc8-570e-9edc-293de7c82f20','6cbcee1d-c14b-54ae-92aa-ffe4ef1ee210');
