INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('3ebff0b9-2768-50d0-b352-5a41bec1f096','1bc86e3e-2bed-580c-b005-ec4ef354da9b','93bdb4b8-c0ae-5718-a482-7e108856acfb','设向量 $a=(2,-1,3)$，$b=(1,2,-1)$，则 $3a\\cdot b=$','["-12","-9","-3","9"]',1,'2026-04 · 向量代数',1232);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('3ebff0b9-2768-50d0-b352-5a41bec1f096',1,'先算 $a\\cdot b=2\\times1+(-1)\\times2+3\\times(-1)=-3$，所以 $3a\\cdot b=-9$。');
