INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('13a17fef-a8fb-54bf-851c-0bb8977d87cd','1bc86e3e-2bed-580c-b005-ec4ef354da9b','6a8857a0-9ecd-5004-9f36-40716ada4298','设函数 $z=x^2y+2y^3$，则全微分 $dz$ 在点 $(1,1)$ 处等于','["$2dx+7dy$","$2dx+6dy$","$dx+7dy$","$7dx+2dy$"]',2,'2026-04 · 多元函数微分',1233);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('13a17fef-a8fb-54bf-851c-0bb8977d87cd',0,'$z_x=2xy$，$z_y=x^2+6y^2$。代入 $(1,1)$ 得 $dz=2dx+7dy$。');
