INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('06c6ff17-92e5-5120-8ebd-4ec33e2d1de9','1bc86e3e-2bed-580c-b005-ec4ef354da9b','76bf8744-c4ff-5520-8dc8-22c0084f761d','下列函数中，是微分方程 $e^{-x}dy-e^{-y}dx=0$ 通解的是','["$e^x+e^y=C$","$e^y-e^x=C$","$e^{-y}-e^{-x}=C$","$e^x-e^{-y}=C$"]',3,'2026-04 · 微分方程',1234);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('06c6ff17-92e5-5120-8ebd-4ec33e2d1de9',1,'两边乘以 $e^{x+y}$，得到 $e^y dy-e^x dx=0$。积分得 $e^y-e^x=C$。');
