INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('e9cf6f18-7b97-5a90-9adf-c246882a558b','1bc86e3e-2bed-580c-b005-ec4ef354da9b','edd0ef4e-3dd6-5b18-b608-cd6c41c776c4','级数 $\\sum_{n=1}^{\\infty}\\frac{1}{n^{2p}}$ 收敛时，$p$ 应满足','["$p>\\\\frac12$","$p\\\\ge\\\\frac12$","$p>1$","$0<p<\\\\frac12$"]',2,'2026-04 · 无穷级数',1235);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('e9cf6f18-7b97-5a90-9adf-c246882a558b',0,'把指数 $2p$ 看作 p 级数的指数。收敛要求 $2p>1$，所以 $p>1/2$。');
