INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('07c25d6d-8ac8-5efe-a2ba-f06ddd104817','1bc86e3e-2bed-580c-b005-ec4ef354da9b','50d68cb5-c0b0-51f2-91b5-d463fee04fb6','设积分区域 $D:x^2+y^2\\le4$，则 $\\iint_D(x^2+y^2)\\,dxdy=$','["$4\\\\pi$","$6\\\\pi$","$8\\\\pi$","$16\\\\pi$"]',3,'2026-04 · 二重积分',1236);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('07c25d6d-8ac8-5efe-a2ba-f06ddd104817',2,'极坐标下为 $\\int_0^{2\\pi}\\int_0^2r^3drd\\theta=2\\pi\\times4=8\\pi$。');
