INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('7a63a24d-d72e-5d83-82e3-e07149fb8616','1bc86e3e-2bed-580c-b005-ec4ef354da9b','e350757a-367c-57e1-8626-d4c4dc6f6f4d','经过点 $P(1,-2,3)$ 且法向量为 $n=(2,-1,1)$ 的平面方程是','["$2x-y+z-7=0$","$2x+y+z-3=0$","$x-2y+3z-14=0$","$2x-y-z-1=0$"]',2,'2026-04 · 空间解析几何',1237);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('7a63a24d-d72e-5d83-82e3-e07149fb8616',0,'由点法式 $2(x-1)-(y+2)+(z-3)=0$，整理得 $2x-y+z-7=0$。');
