INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('75031280-0d47-528c-b538-3bbbe95e763e','1bc86e3e-2bed-580c-b005-ec4ef354da9b','d5998882-ba87-5f85-b44e-fc3713297247','函数 $z=(4x-x^2)(6y-y^2)$ 的一个驻点是','["$(2,3)$","$(2,0)$","$(0,3)$","$(4,6)$"]',3,'2026-04 · 多元函数极值',1238);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('75031280-0d47-528c-b538-3bbbe95e763e',0,'令两个一阶偏导数同时为 0。在给出的点中，$(2,3)$ 同时满足 $4-2x=0$ 与 $6-2y=0$。');
