INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('ac83c18e-205a-545b-8941-330839d22080','1bc86e3e-2bed-580c-b005-ec4ef354da9b','17e6499e-f381-585e-be73-71865970a822','设 $\\Omega:-1\\le x\\le1,0\\le y\\le1,0\\le z\\le2$，则 $\\iiint_\\Omega(2+x+z)\\,dxdydz=$','["6","8","10","12"]',3,'2026-04 · 三重积分',1239);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('ac83c18e-205a-545b-8941-330839d22080',3,'x 项在对称区间积分为 0。$\\int_0^2(2+z)dz=6$，再乘 x、y 区间长度 $2\\times1$，结果为 12。');
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('24818e8f-d8ca-5ad9-bbc5-8a6ee325abaa','e7742ada-e08b-5e92-a4db-cedfa4d5c8c1','三重积分','三重积分');
