INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('7ca5b40e-12e8-5cb3-9b24-badf77d226d2','1bc86e3e-2bed-580c-b005-ec4ef354da9b','f5185a23-0875-5691-8826-3cf39d580a53','级数 $\\sum_{n=1}^{\\infty}\\frac{1}{n(n+2)}$ 的和是','["$\\\\frac12$","$\\\\frac23$","$\\\\frac34$","1"]',3,'2026-04 · 无穷级数',1240);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('7ca5b40e-12e8-5cb3-9b24-badf77d226d2',2,'拆分为 $\\frac1{n(n+2)}=\\frac12(\\frac1n-\\frac1{n+2})$，相消后为 $\\frac12(1+\\frac12)=\\frac34$。');
INSERT INTO question_point (revision_id,point_id) VALUES ('7ca5b40e-12e8-5cb3-9b24-badf77d226d2','26be18f4-fd0a-5b55-90db-9b765c0e3350');
