INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('981daac0-a077-5fe2-b428-8363c5227913',0,'连续积分两次：$y^{\\prime}=3e^x+2x+C_1$，再得 $y=3e^x+x^2+C_1x+C_2$。');
