INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('69d885bd-8a4f-5a63-a4b1-a7b7b6224924','1bc86e3e-2bed-580c-b005-ec4ef354da9b','a9bc8881-4e62-5786-a2f3-ca43be33e87d','设向量 $a=(k,-3,6)$ 与 $b=(-2,1,-2)$ 平行，则常数 $k=$','["-6","-3","3","6"]',2,'2025-10 · 向量代数',1242);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('69d885bd-8a4f-5a63-a4b1-a7b7b6224924',3,'其余分量比均为 $-3$，所以 $k/(-2)=-3$，得 $k=6$。');
INSERT INTO question_point (revision_id,point_id) VALUES ('69d885bd-8a4f-5a63-a4b1-a7b7b6224924','5c1f2dce-0c69-59d7-bd7c-db664e5f1c54');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('9627ef8d-30cb-54df-a326-0a20e2e5b8eb','afdac469-0fe4-5007-833c-51a71333967b','32ec87c0-2e8e-5a8e-b45f-8bcf5ac63f59','legacy:00023:calculus-generated-v1-2025-10-2','8f39c2b40371386431a96b4ac9ed47379a7ef1d370231c92566b8f1d519f0125','calculus-generated-v1-2025-10-2','VARIANT',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('e8c6f4c7-355c-5938-af16-82eabbeb0f8a','1bc86e3e-2bed-580c-b005-ec4ef354da9b','9627ef8d-30cb-54df-a326-0a20e2e5b8eb','设函数 $z=\\frac{y}{x}$，则全微分 $dz=$','["$\\\\frac1x dx-\\\\frac{y}{x^2}dy$","$-\\\\frac{y}{x^2}dx+\\\\frac1xdy$","$\\\\frac{y}{x^2}dx+\\\\frac1xdy$","$-\\\\frac1x dx+\\\\frac{y}{x^2}dy$"]',2,'2025-10 · 多元函数微分',1243);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('e8c6f4c7-355c-5938-af16-82eabbeb0f8a',1,'$z_x=-y/x^2$，$z_y=1/x$，所以 $dz=-\\frac{y}{x^2}dx+\\frac1xdy$。');
INSERT INTO question_point (revision_id,point_id) VALUES ('e8c6f4c7-355c-5938-af16-82eabbeb0f8a','e5cf4bb3-54de-5f2a-a7e6-ff26fd9427ba');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('907a6d72-2b39-5451-8896-2023056b0411','afdac469-0fe4-5007-833c-51a71333967b','7f2ef968-dd1d-56f8-ac00-158b51f9ac0a','legacy:00023:calculus-generated-v1-2025-10-3','58b14fd3f7b5e2c28ca1ecc8cadcafd1e6399915d17e6dd7a28be02a86e32714','calculus-generated-v1-2025-10-3','VARIANT',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('6be3a261-2ac2-5ef7-9de2-93e6335d8511','1bc86e3e-2bed-580c-b005-ec4ef354da9b','907a6d72-2b39-5451-8896-2023056b0411','微分方程 $y^{\\prime}-2xy=0$ 的通解是','["$y=Ce^{2x}$","$y=Ce^{x^2}$","$y=Ce^{-x^2}$","$y=Cx^2$"]',2,'2025-10 · 微分方程',1244);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('6be3a261-2ac2-5ef7-9de2-93e6335d8511',1,'分离变量得 $dy/y=2x dx$，积分后 $\\ln|y|=x^2+C$，所以 $y=Ce^{x^2}$。');
INSERT INTO question_point (revision_id,point_id) VALUES ('6be3a261-2ac2-5ef7-9de2-93e6335d8511','9df2fa40-6d40-55a3-9918-db842ff8b979');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('bd4738fd-7219-5513-94bf-2c952483d3c2','afdac469-0fe4-5007-833c-51a71333967b','8c772590-817b-5b20-a874-31fff00ed3e5','legacy:00023:calculus-generated-v1-2025-10-4','4e011b729f34a5d3f3acd94dc213283b216a8f198fd2ae8b727b7c23310f5c36','calculus-generated-v1-2025-10-4','VARIANT',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('15422c98-a806-5a79-9703-739cd1b4d117','1bc86e3e-2bed-580c-b005-ec4ef354da9b','bd4738fd-7219-5513-94bf-2c952483d3c2','级数 $\\sum_{n=0}^{\\infty}(n+1)(x-1)^n$ 收敛时，下列 x 的取值可行的是','["-1","0","$\\\\frac32$","$\\\\frac52$"]',2,'2025-10 · 幂级数',1245);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('15422c98-a806-5a79-9703-739cd1b4d117',2,'收敛半径为 1，要求 $|x-1|<1$，即 $0<x<2$。选项中只有 $x=3/2$。');
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('14773a2a-659c-51e9-9603-66606845fca2','8c772590-817b-5b20-a874-31fff00ed3e5','幂级数','幂级数');
INSERT INTO release_point (release_id,chapter_id,point_id,title_snapshot) VALUES ('1bc86e3e-2bed-580c-b005-ec4ef354da9b','8c772590-817b-5b20-a874-31fff00ed3e5','14773a2a-659c-51e9-9603-66606845fca2','幂级数');
