INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('524e046a-ece9-5315-aa43-3b6dfca2b846','afdac469-0fe4-5007-833c-51a71333967b','e7742ada-e08b-5e92-a4db-cedfa4d5c8c1','legacy:00023:calculus-generated-v1-2025-10-5','01c908f0b201dc0e4a5b8f55e095bc43b4dc2d369e560c44637719a32bce4d8a','calculus-generated-v1-2025-10-5','VARIANT',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('cee41c79-9831-5f57-8011-062b9c3b5366','1bc86e3e-2bed-580c-b005-ec4ef354da9b','524e046a-ece9-5315-aa43-3b6dfca2b846','设积分区域 $D:|x|\\le3,|y|\\le1$，则 $\\iint_D|y|\\,dxdy=$','["3","6","9","12"]',2,'2025-10 · 二重积分',1246);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('cee41c79-9831-5f57-8011-062b9c3b5366',1,'$\\int_{-1}^{1}|y|dy=1$，再乘 x 区间长度 6，结果为 6。');
INSERT INTO question_point (revision_id,point_id) VALUES ('cee41c79-9831-5f57-8011-062b9c3b5366','3cda59be-4ee4-534a-b8dc-5c1dc1278e29');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('5fe8f231-8fe4-516d-a6f9-a921ef2889bd','afdac469-0fe4-5007-833c-51a71333967b','9f58c98e-82a0-51b9-8946-a297b17b7840','legacy:00023:calculus-generated-v1-2025-10-6','dc09db44e67dc97651dcb81471d0319b22b5ecea1e793c720671d224e3ec93b4','calculus-generated-v1-2025-10-6','VARIANT',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('70b5a229-0fea-57e4-ab3d-c8dee67ae2c8','1bc86e3e-2bed-580c-b005-ec4ef354da9b','5fe8f231-8fe4-516d-a6f9-a921ef2889bd','经过点 $P(-1,2,4)$ 且方向向量为 $v=(1,-2,3)$ 的直线方程是','["$\\\\frac{x+1}{1}=\\\\frac{y-2}{-2}=\\\\frac{z-4}{3}$","$\\\\frac{x-1}{1}=\\\\frac{y+2}{-2}=\\\\frac{z+4}{3}$","$x-2y+3z=0$","$\\\\frac{x+1}{-1}=\\\\frac{y-2}{2}=\\\\frac{z-4}{3}$"]',1,'2025-10 · 空间解析几何',1247);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('70b5a229-0fea-57e4-ab3d-c8dee67ae2c8',0,'点向式为 $(x-x_0)/l=(y-y_0)/m=(z-z_0)/n$，代入点 $(-1,2,4)$ 与方向向量即可。');
INSERT INTO question_point (revision_id,point_id) VALUES ('70b5a229-0fea-57e4-ab3d-c8dee67ae2c8','4f996cf7-11f0-5ab1-ad40-ce50e25ebf07');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('0ef09453-03d2-55d2-8899-99b47bfa5d89','afdac469-0fe4-5007-833c-51a71333967b','32ec87c0-2e8e-5a8e-b45f-8bcf5ac63f59','legacy:00023:calculus-generated-v1-2025-10-7','88d9c36592507a4490ab05f1ff33ec5d984dea473248012f962d161e9765d9be','calculus-generated-v1-2025-10-7','VARIANT',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('2e7314f1-d68a-5f07-9253-ba4ed71a9005','1bc86e3e-2bed-580c-b005-ec4ef354da9b','0ef09453-03d2-55d2-8899-99b47bfa5d89','设 $z=x^4+y^4-2x^2-4y^2$，则点 $(1,\\sqrt2)$ 是函数的','["间断点","鞍点","极大值点","极小值点"]',4,'2025-10 · 多元函数极值',1248);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('2e7314f1-d68a-5f07-9253-ba4ed71a9005',3,'该点一阶偏导数为 0，且 Hessian 的两个对角元分别为 8、16，均为正，因此是极小值点。');
INSERT INTO question_point (revision_id,point_id) VALUES ('2e7314f1-d68a-5f07-9253-ba4ed71a9005','210e681f-4426-556e-9bdb-0c10532ef1d6');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('a83e7c98-bc30-5dd3-a73d-40ff9cab9f3a','afdac469-0fe4-5007-833c-51a71333967b','e7742ada-e08b-5e92-a4db-cedfa4d5c8c1','legacy:00023:calculus-generated-v1-2025-10-8','7574a4cb7906941cee7677a6a2f0d24ba10ed03accc2b25d34dcd251d78b38ee','calculus-generated-v1-2025-10-8','VARIANT',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('1a7b4038-4b72-54e2-9d4b-b72f7031b1a4','1bc86e3e-2bed-580c-b005-ec4ef354da9b','a83e7c98-bc30-5dd3-a73d-40ff9cab9f3a','设 $\\Omega:(x-2)^2+y^2+z^2\\le4$，则 $\\iiint_\\Omega(3y+z)\\,dxdydz=$','["0","$4\\\\pi$","$8\\\\pi$","$16\\\\pi$"]',2,'2025-10 · 三重积分',1249);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('1a7b4038-4b72-54e2-9d4b-b72f7031b1a4',0,'球域关于 y、z 都对称，而 $3y+z$ 的两部分均为相应变量的奇函数，所以积分为 0。');
INSERT INTO question_point (revision_id,point_id) VALUES ('1a7b4038-4b72-54e2-9d4b-b72f7031b1a4','24818e8f-d8ca-5ad9-bbc5-8a6ee325abaa');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('35cce522-9f7c-5788-82fc-47ee561ead91','afdac469-0fe4-5007-833c-51a71333967b','8c772590-817b-5b20-a874-31fff00ed3e5','legacy:00023:calculus-generated-v1-2025-10-9','64e92372ae23b097ec66b26185329dad8dc7b870bcceb8c6723f6dbaf2e59785','calculus-generated-v1-2025-10-9','VARIANT',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('33484f37-d1e3-534c-87b3-8e549f272231','1bc86e3e-2bed-580c-b005-ec4ef354da9b','35cce522-9f7c-5788-82fc-47ee561ead91','级数 $\\sum_{n=1}^{\\infty}(\\frac13)^n$ 的和是','["$\\\\frac13$","$\\\\frac12$","1","$\\\\frac32$"]',1,'2025-10 · 无穷级数',1250);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('33484f37-d1e3-534c-87b3-8e549f272231',1,'首项和公比都是 $1/3$，和为 $a_1/(1-q)=(1/3)/(2/3)=1/2$。');
INSERT INTO question_point (revision_id,point_id) VALUES ('33484f37-d1e3-534c-87b3-8e549f272231','26be18f4-fd0a-5b55-90db-9b765c0e3350');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('7b986a0a-d453-5ae9-aeca-f92145098f02','afdac469-0fe4-5007-833c-51a71333967b','7f2ef968-dd1d-56f8-ac00-158b51f9ac0a','legacy:00023:calculus-generated-v1-2025-10-10','b3bf0e9ddd4c216177b1fcafe1c54cbacd9ee080bba5a1dd085fed7bfc1d34d6','calculus-generated-v1-2025-10-10','VARIANT',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('9dba72a1-0ff1-5802-bcba-e15dc7f6bbf0','1bc86e3e-2bed-580c-b005-ec4ef354da9b','7b986a0a-d453-5ae9-aeca-f92145098f02','微分方程 $y^{\\prime\\prime}=4x+2$ 的通解是','["$y=2x^2+2x+C_1$","$y=\\\\frac23x^3+x^2+C_1x+C_2$","$y=\\\\frac43x^3+x^2+C_1x+C_2$","$y=2x^3+x^2+C_1x+C_2$"]',2,'2025-10 · 常微分方程',1251);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('9dba72a1-0ff1-5802-bcba-e15dc7f6bbf0',1,'连续积分两次：$y^{\\prime}=2x^2+2x+C_1$，再得 $y=\\frac23x^3+x^2+C_1x+C_2$。');
INSERT INTO question_point (revision_id,point_id) VALUES ('9dba72a1-0ff1-5802-bcba-e15dc7f6bbf0','82a82ec7-26e9-5b73-8f9c-044653c62b66');
