INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('fbd1c2c7-a145-5ce5-bc5f-aca4c6c69246','ccef96c1-a6be-572c-826f-6c2e4cd6eca6','3d15790c-3c12-5417-b3ee-2105b61d51cf','某程序有 $10^8$ 条指令，其中 60% 的 CPI 为 1，40% 的 CPI 为 3。时钟频率为 2GHz，则运行时间为','["$0.05s$","$0.08s$","$0.09s$","$0.18s$"]',4,'章节刷题 · 真题难度新题 · CPI 与执行时间',332);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('fbd1c2c7-a145-5ce5-bc5f-aca4c6c69246',2,'平均 CPI 为 $0.6\\times1+0.4\\times3=1.8$，时间为 $10^8\\times1.8/(2\\times10^9)=0.09s$。');
INSERT INTO knowledge_point (id,chapter_id,stable_key,title) VALUES ('347914a4-1e16-5bed-8704-1c7f025e3ce9','d17d824c-4746-56e6-9636-87f49c908959','CPI 与执行时间','CPI 与执行时间');
