INSERT INTO question_point (revision_id,point_id) VALUES ('fbd1c2c7-a145-5ce5-bc5f-aca4c6c69246','347914a4-1e16-5bed-8704-1c7f025e3ce9');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('61325e8e-de6f-576f-b059-46757850c1e8','4c6db663-13a2-5b2b-8cfa-6422a6c37205','8ba60d45-32b9-5d12-bfe6-6fa0db4a15f2','legacy:13015:systems-fresh-20260929-11','31721e58a69f031477818280ff43674cafe7be260af016cfd5a12ecb4e47cd04','systems-fresh-20260929-11','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('cb07d954-6171-508c-ac58-53efe62ee2c8','ccef96c1-a6be-572c-826f-6c2e4cd6eca6','61325e8e-de6f-576f-b059-46757850c1e8','Cache 命中时间 2ns，缺失时还需额外访问主存 80ns；若平均访存时间为 10ns，则命中率为','["$80\\\\%$","$85\\\\%$","$90\\\\%$","$95\\\\%$"]',4,'章节刷题 · 真题难度新题 · 命中率与平均访存时间',333);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('cb07d954-6171-508c-ac58-53efe62ee2c8',2,'设缺失率为 $m$，有 $2+80m=10$，得 $m=0.1$，因此命中率 90%。');
INSERT INTO question_point (revision_id,point_id) VALUES ('cb07d954-6171-508c-ac58-53efe62ee2c8','92893cf8-3bfa-5a3e-89ef-628db7fc7076');
INSERT INTO question (id,course_id,chapter_id,original_key,content_fingerprint,legacy_id,mode,eligible_original) VALUES ('59c10523-fa18-551a-81ac-3bbbdfe3528a','4c6db663-13a2-5b2b-8cfa-6422a6c37205','1a7a338e-c8c2-56c4-a525-76141fe43d39','legacy:13015:systems-fresh-20260929-12','12aa18ca1a1130bf6c516a37f274a1becf97791d7a31eb49de0eed03f55f2d83','systems-fresh-20260929-12','CHAPTER',0);
INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('c53f219d-16ee-59b2-8ebf-a9af3c4d6d9e','ccef96c1-a6be-572c-826f-6c2e4cd6eca6','59c10523-fa18-551a-81ac-3bbbdfe3528a','某总线宽度为 32 位，频率 100MHz，每时钟传输一次且不计开销，理论带宽为','["$100MB/s$","$200MB/s$","$400MB/s$","$800MB/s$"]',4,'章节刷题 · 真题难度新题 · 总线带宽',334);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('c53f219d-16ee-59b2-8ebf-a9af3c4d6d9e',2,'每次传输 32 位即 4 字节，带宽为 $4\\times100\\times10^6=400MB/s$。');
