INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('93440f87-51db-5994-b170-13ee75d87ce7','ccef96c1-a6be-572c-826f-6c2e4cd6eca6','ff724241-d25b-51d4-894c-63a7ce810709','4 级流水线每级耗时 2ns，理想情况下连续完成 10 条指令需要多少时间？','["20ns","26ns","80ns","8ns"]',3,'章节练习 · 流水线',383);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('93440f87-51db-5994-b170-13ee75d87ce7',1,'理想 k 级流水线完成 n 条指令需 $(k+n-1)\\Delta t=(4+10-1)\\times2=26ns$。');
