INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('60d46545-a9be-55b3-a3d9-b6628348e10b',0,'a⁻¹=a，且 (ab)⁻¹=b⁻¹a⁻¹=ba；又 (ab)⁻¹=ab，因此 ab=ba。');
