INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('2187c3dc-30d6-531f-9290-2435740f21d9',1,'由 $|A\\cup B|=|A|+|B|-|A\\cap B|$，交集大小为 $20+18-30=8$。');
