INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('1232e2c0-ae9c-5169-a036-d89b0810d06d','1649ffaa-533f-5031-bc0e-e35092333eaa','a5960842-4268-5958-b18c-48c23a411655','元素 a₂₃ 的代数余子式与余子式的关系为','["A₂₃=M₂₃","A₂₃=-M₂₃","A₂₃=2M₂₃","A₂₃=0"]',3,'目录考点新题 · 代数余子式',648);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('1232e2c0-ae9c-5169-a036-d89b0810d06d',1,'Aᵢⱼ=(-1)^(i+j)Mᵢⱼ，2+3 为奇数，故变号。');
INSERT INTO question_point (revision_id,point_id) VALUES ('1232e2c0-ae9c-5169-a036-d89b0810d06d','2e4a458f-54e0-5919-a3b7-12fd2ab8f946');
