INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('e34738be-945f-5c3d-89e8-bb76fb3b34e7','1649ffaa-533f-5031-bc0e-e35092333eaa','23a5a149-61bb-5847-9936-cded9c73daa0','三阶行列式 $\\begin{vmatrix}1&1&1\\\\1&2&3\\\\1&3&6\\end{vmatrix}$ 的值为','["0","1","2","3"]',4,'章节刷题 · 真题难度新题 · 行列式计算',710);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('e34738be-945f-5c3d-89e8-bb76fb3b34e7',1,'第一列不变，后两列分别减第一列，得到右下二阶行列式 $\\begin{vmatrix}1&2\\\\2&5\\end{vmatrix}=1$。');
