INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('205d2962-2538-5de3-a704-6bc1fe9dbcb3',2,'四阶矩阵满足 $|-2A|=(-2)^4|A|=16\\times3=48$。');
