INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('fa318869-8101-50c1-a793-9747ea3ff8c3','1649ffaa-533f-5031-bc0e-e35092333eaa','53252ff6-d55f-5624-8e65-2600d1c489a3','设 $A^2-A-I=0$，则 $A^{-1}=$','["$A-I$","$A+I$","$I-A$","$A^2$"]',4,'章节刷题 · 真题难度新题 · 逆矩阵',712);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('fa318869-8101-50c1-a793-9747ea3ff8c3',0,'由 $A^2-A=I$，即 $A(A-I)=I$，所以 $A^{-1}=A-I$。');
