INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('107c6cfc-7167-56ca-892e-6e31fcfa5ad6','1649ffaa-533f-5031-bc0e-e35092333eaa','696a597e-9e2e-5ec9-939e-0942bdbf5ce2','向量组 $\\alpha_1,\\alpha_2,\\alpha_3$ 线性无关，则下列向量组必线性无关的是','["$\\\\alpha_1+\\\\alpha_2,\\\\alpha_2+\\\\alpha_3,\\\\alpha_1+2\\\\alpha_2+\\\\alpha_3$","$\\\\alpha_1+\\\\alpha_2,2\\\\alpha_1+2\\\\alpha_2,\\\\alpha_3$","$\\\\alpha_1-\\\\alpha_2,\\\\alpha_2-\\\\alpha_3,\\\\alpha_3-\\\\alpha_1$","$\\\\alpha_1,\\\\alpha_1+\\\\alpha_2,\\\\alpha_1+\\\\alpha_2+\\\\alpha_3$"]',4,'章节刷题 · 真题难度新题 · 线性相关',714);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('107c6cfc-7167-56ca-892e-6e31fcfa5ad6',3,'第四组到原向量组的系数矩阵为三角矩阵且对角元全为 1，行列式非零，因此线性无关；其余各组都有一个向量可由另两个线性表示。');
