INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('9d392b5b-68b3-5947-80c0-422666d1e14c',0,'设 $\\beta=c_1\\alpha_1+c_2\\alpha_2=(c_1+c_2,c_2)$，故 $c_2=2,c_1=1$。');
