INSERT INTO question_revision (id,release_id,question_id,stem,options,difficulty,source_locator,sort_order) VALUES ('08705ea2-d98e-59e4-8df8-4fc53108d074','1649ffaa-533f-5031-bc0e-e35092333eaa','f7ec39b1-67ac-5df4-a3ba-4c4be5589a05','若三阶矩阵 $A$ 的特征值为 $1,2,3$，则 $A^2-2A$ 的特征值为','["$-1,0,3$","$1,4,9$","$-1,0,1$","$0,2,6$"]',4,'章节刷题 · 真题难度新题 · 特征值',718);
INSERT INTO question_solution (revision_id,correct_option,explanation) VALUES ('08705ea2-d98e-59e4-8df8-4fc53108d074',0,'多项式矩阵 $p(A)$ 的特征值为 $p(\\lambda)$。代入 $p(\\lambda)=\\lambda^2-2\\lambda$ 得 $-1,0,3$。');
